  ui_story_5007_50070101_110_dialog_content = "어째서 미리 대피하지 않은 거지?",
  ui_story_5007_50070101_111_dialog_content = "보통 방어선이 공격을 받고, 암귀의 대규모 침입이 시작됐다면...",
  ui_story_5007_50070101_112_dialog_content = "후방 지원을 맡은 지하성은 진작에 소식이 전파돼서 대피를 시작했어야 맞는 거잖아.",
  ui_story_5007_50070101_113_dialog_content = "설마 그쪽도 <color=#FFB400>통신 시스템</color>이 고장 난 건 아닐까?",
