  ui_story_5007_50070101_115_dialog_content = "아무튼, 가 보면 알겠지!",
  ui_story_5007_50070101_116_dialog_content = "<color=#FFB400>모래폭풍</color>!",
  ui_story_5007_50070201_1_dialog_content = "서둘러! 저쪽에서 집결한다!",
