  ui_story_5007_50070201_3_dialog_content = "어이! 여기 누가 총알을 흘렸는데?",
  ui_story_5007_50070201_4_dialog_content = "선배! 이 지하성 꼴 좀 보십시오!",
  ui_story_5007_50070201_5_dialog_content = "음... 확실히 좀 어수선하군.",
  ui_story_5007_50070201_6_dialog_content = "다 같은 일루미나 사람이지만, 이렇게 아무나 군대에 데려오면\n일반 병사보다 한참 수준이 떨어지지 않습니까!",
  ui_story_5007_50070201_7_dialog_content = "평소에는 안 쓰니 모르고, 급할 때 찾으면 부족한 법이지.",
  ui_story_5007_50070201_8_dialog_content = "선배, 지금 상황에서 농담이 나옵니까?",
  ui_story_5007_50070201_9_dialog_content = "진정하게, 브랜트.",
  ui_story_5007_50070201_10_dialog_content = "이럴 때야말로 마음을 가라앉혀야 하는 법이지. 안 그러면 화병으로 죽을 거라고.",
  ui_story_5007_50070201_11_dialog_content = "실례합니다. 혹시 대포가 어디에 있는지 아십니까?",
  ui_story_5007_50070201_12_dialog_content = "서쪽 성벽에 가서 찾아봐!",
  ui_story_5007_50070201_13_dialog_content = "세상에, 포병이 대포를 못 찾는다니!\n외출하는데 바지를 못 찾는 사람이랑 뭐가 달라?!",
  ui_story_5007_50070201_14_dialog_content = "정말 미치겠군!",
  ui_story_5007_50070201_15_dialog_content = "그럴 수도 있지. 저 포병도 이제 막 왔으니 말이야.",
  ui_story_5007_50070201_16_dialog_content = "어이, 거기 병사!",
  ui_story_5007_50070201_17_dialog_content = "예? 저요?",
  ui_story_5007_50070201_18_dialog_content = "뭐냐, 불렀는데 왜 쪼그려 앉아? 쪼그려 앉으면 내가 못 볼 줄 알았나?",
  ui_story_5007_50070201_19_dialog_content = "뭐야, 군복 바지는 어디 갔어? 왜 안 입은 거냐?",
  ui_story_5007_50070201_20_dialog_content = "보, 보고드립니다... 제 바지가 모래폭풍에 날아가 버렸습니다!",
  ui_story_5007_50070201_20X1_dialog_content = "보급소에 가서 새로 받아와!",
  ui_story_5007_50070201_21_dialog_content = "환장하겠군... 정말 바지가 없는 놈이 있단 말이야?",
  ui_story_5007_50070201_22_dialog_content = "기껏 편성한 <color=#FFB400>혼합 부대</color>가 이런 꼴이라니...",
  ui_story_5007_50070201_23_dialog_content = "이번 싸움, 괜찮겠습니까? 선배.",
  ui_story_5007_50070201_24_dialog_content = "안 될 게 뭐가 있겠나. 전부 사람인데, 암귀 몇 마리를 못 이길 리가 없지.",
  ui_story_5007_50070201_25_dialog_content = "우린 지금 <color=#FFB400>전력이 부족</color>하네. 있는 사람은 모조리 데려올 수밖에 없어.",
  ui_story_5007_50070201_26_dialog_content = "중대엔 고참 병사들이 있으니 괜찮을 걸세.",
  ui_story_5007_50070201_27_dialog_content = "전장에 나서면 누구나 뛰어난 전사가 될 수 있지!",
  ui_story_5007_50070201_28_dialog_content = "그러니 걱정하지 말고 자네 임무를 수행하게.",
  ui_story_5007_50070201_29_dialog_content = "휴, 됐습니다. 알겠습니다.",
  ui_story_5007_50070201_30_dialog_content = "24호 지하성 소대! 집합!",
  ui_story_5007_50070201_31_dialog_content = "보초병은 상황을 보고하라!",
  ui_story_5007_50070201_32_dialog_content = "보고드립니다. 모래폭풍이 지나갔고, 가시거리가 정상으로 돌아와서 아주 멀리까지 볼 수 있습니다!",
  ui_story_5007_50070201_33_dialog_content = "누가 그런 식으로 보고하라고 가르쳤나! 「멀리까지」면 얼마나 멀다는 거냐!",
  ui_story_5007_50070201_34_dialog_content = "...브, 브랜트 책임관님께 배웠습니다...",
  ui_story_5007_50070201_35_dialog_content = "어, 어제 <color=#FFB400>교육</color>에서 가르쳐 주셨습니다만...",
  ui_story_5007_50070201_36_dialog_content = "말도 안 나오는군. 내가 언제 그렇게 가르쳤다는 거냐! 됐으니까 계속 보고해라!",
  ui_story_5007_50070201_37_dialog_content = "현재 <color=#FFB400>수송 차량</color>을 추격 중인 암귀를 발견했습니다!",
  ui_story_5007_50070201_38_dialog_content = "수송 차량은 언제쯤 도착하지? 차량을 추격 중인 암귀의 예상 도달 시각은?",
  ui_story_5007_50070201_39_dialog_content = "약 4분... 아니, 3분 뒤입니다! 암귀는 차량과 아직 거리가 좀 있습니다만...",
  ui_story_5007_50070201_40_dialog_content = "똑바로 기억해라. 적의 이동속도를 추정하는 것은 매우 중요하다!",
  ui_story_5007_50070201_41_dialog_content = "이제 근무 위치로 돌아가라!",
  ui_story_5007_50070201_42_dialog_content = "예!",
  ui_story_5007_50070201_43_dialog_content = "24호 지하성 소대! 잘 들어라!",
  ui_story_5007_50070201_44_dialog_content = "암귀는 이미 수송 거점 내부에 들어왔다.\n게다가 새로 출몰한 암귀 무리까지 염두한다면, 더는 전투를 피할 수 없게 되었다!",
  ui_story_5007_50070201_45_dialog_content = "이번 작전 목표는 수송 거점에 진입하는 수송 차량을 지원하여\n저들의 안전을 보장하는 것이다!",
  ui_story_5007_50070201_46_dialog_content = "자세한 작전 명령은 문이 열린 후 상황에 따라 하달하겠다!",
  ui_story_5007_50070201_47_dialog_content = "문을 열 준비를 해라!",
  ui_story_5007_50070201_49_dialog_content = "<size=40>여명의 빛을 위하여!</size>",
  ui_story_5007_50070201_50_dialog_content = "24호 지하성 소대! 출발!",
  ui_story_5007_50070201_51_dialog_content = "PlayerName! 얼른 이리 와봐!",
  ui_story_5007_50070201_52_dialog_content = "왜 그래?",
  ui_story_5007_50070201_53_dialog_content = "이런 각도에서 24호 지하성을 본 건 처음이거든...",
  ui_story_5007_50070201_54_dialog_content = "외벽, 건물들, 일루미나 마크...",
  ui_story_5007_50070201_55_dialog_content = "저게 바로 24호 지하성이야?",
  ui_story_5007_50070201_56_dialog_content = "...저건 지상에 있으니까 「지상성」 아냐?",
  ui_story_5007_50070201_57_dialog_content = "아니야!",
  ui_story_5007_50070201_58_dialog_content = "지금 보이는 부분은 24호 지하성의 지상 시설인 수송 거점이야.",
  ui_story_5007_50070201_59_dialog_content = "수송 거점 안에는 훈련장, 수송 플랫폼, 창고 등의 시설만 있어.",
  ui_story_5007_50070201_60_dialog_content = "주거 구역이나 신병 기지, 진료소, 고아원 등의 시설은 전부 지하성에 안에 있어.",
  ui_story_5007_50070201_61_dialog_content = "그렇구나.",
  ui_story_5007_50070201_62_dialog_content = "상공에서 봤을 때 24호 지하성은 아직 암귀에게 포위당하지 않은 것 같네.",
  ui_story_5007_50070201_63_dialog_content = "그러게, 아무래도 상황이 그리 나쁘진 않은 것 같아.",
  ui_story_5007_50070201_64_dialog_content = "하지만 아래에 암귀 몇 마리가 활동하는 게 느껴져.\n그리고 강력한 오로리안도 몇 명 있어.",
  ui_story_5007_50070201_65_dialog_content = "아마 곧 암귀와 교전이 벌어질 것 같아.",
  ui_story_5007_50070201_66_dialog_content = "그럼 어서 착륙해서 지원하자!",
  ui_story_5007_50070201_67_dialog_content = "그르르...",
  ui_story_5007_50070201_68_dialog_content = "착륙은 성공했어. 그래도 아직은 문을 열면 안 돼.",
  ui_story_5007_50070201_69_dialog_content = "콜로서스가 착륙하는 걸 보고 암귀들이 몰려왔어.",
  ui_story_5007_50070201_70_dialog_content = "문을 열면 곧바로 전투가 벌어질지도 몰라.",
  ui_story_5007_50070201_71_dialog_content = "준비됐어! 하지만 우린 지금 싸울 전력이 조금 부족해.\n혹시 누가 창을 좀 들고...",
  ui_story_5007_50070201_72_dialog_content = "암귀가 문 앞까지 왔으면 나도 가만히 있을 순 없잖아.",
  ui_story_5007_50070201_73_dialog_content = "그럼 이걸로 전력은 충분해. 본의 아니게 우리 호위대장님의\n휴가 시간을 또 빼앗아 버렸는걸~",
  ui_story_5007_50070201_74_dialog_content = "지금 날 놀릴 여유도 있는 거야?\n상황이 별로 심각하지 않으니까 안심이 된 모양이네.",
  ui_story_5007_50070201_75_dialog_content = "가서 싸우자. PlayerName.",
  ui_story_5007_50070201_76_dialog_content = "좋아, 가자!",
  ui_story_5007_50070201_77_dialog_content = "크오오──!",
  ui_story_5007_50070201_78_dialog_content = "내가 나서기로 한 이상, 순순히 심판을 받는 게 좋을 거다! 암귀!",
  ui_story_5007_50070201_79_dialog_content = "전류 돌격!",
  ui_story_5007_50070201_80_dialog_content = "캬아악!",
  ui_story_5007_50070201_81_dialog_content = "......?",
  ui_story_5007_50070201_82_dialog_content = "PlayerName, 방금 지나간 건 뭐지? 감응할 수 있겠어?",
  ui_story_5007_50070201_84_dialog_content = "오로리안이 갑자기 달려와서 눈앞에 있는 암귀를 베어버리고는 재빨리 사라졌어.",
  ui_story_5007_50070201_85_dialog_content = "알고 있어, 나도 봤으니까.",
  ui_story_5007_50070201_86_dialog_content = "내가 지금 알고 싶은 건 저 녀석이 무슨 생각을 하는지야.",
  ui_story_5007_50070201_87_dialog_content = "크오오──!",
  ui_story_5007_50070201_88_dialog_content = "저 암귀들 보여? 방금 그 녀석이 유인한 게 확실해.",
  ui_story_5007_50070201_90_dialog_content = "이제 우리 쪽으로 오고 있어!",
  ui_story_5007_50070202_1_dialog_content = "크오오──!",
  ui_story_5007_50070202_2_dialog_content = "마지막 한 마리야! 카렌!",
  ui_story_5007_50070202_3_dialog_content = "알겠어. 내가 처리할게!",
  ui_story_5007_50070202_4_dialog_content = "전류! 돌격!",
  ui_story_5007_50070202_5_dialog_content = "캬아악!",
  ui_story_5007_50070202_7_dialog_content = "아까 그 애가 또 왔는데?",
  ui_story_5007_50070202_8_dialog_content = "넌 목적이 뭐지?",
  ui_story_5007_50070202_9_dialog_content = "난 레비, 너희도 수송대 사람이야?",
  ui_story_5007_50070202_10_dialog_content = "수송대라니?",
  ui_story_5007_50070202_11_dialog_content = "몰라? 그럼 아니네.",
  ui_story_5007_50070202_12_dialog_content = "우린 24호 지하성에서 보낸 <color=#FFB400>지원 요청 신호</color>를 받고 도우러 온 사람들이야.",
  ui_story_5007_50070202_13_dialog_content = "옷을 보니 지역 부대의 군인은 아닌 것 같은데?",
  ui_story_5007_50070202_14_dialog_content = "난 군인이야! 아주 잘 싸우는 군인이라고!",
  ui_story_5007_50070202_15_dialog_content = "아... 그럼 지금 상황이 어떤지 좀 설명해 줄래?",
  ui_story_5007_50070202_16_dialog_content = "안 돼. 수송대가 아니라면 나랑 아무 상관 없어. 그럼 안녕.",
  ui_story_5007_50070202_17_dialog_content = "잠깐만 기다려. 그럼 너희 상관한테 보고해줄 수 있을까?",
  ui_story_5007_50070202_18_dialog_content = "내 이름은 바이스고, 일루미나 제...",
  ui_story_5007_50070202_19_dialog_content = "난 눈에 보이는 암귀를 마저 죽이러 갈 거야. 안녕.",
  ui_story_5007_50070202_20_dialog_content = "잠깐!",
  ui_story_5007_50070202_21_dialog_content = "만약 정말 긴급 임무가 있는 거라면 이해해. 우리가 도와줄게.",
  ui_story_5007_50070202_22_dialog_content = "필요 없어. 난 하나도 안 급해.",
  ui_story_5007_50070202_23_dialog_content = "역시 남의 말을 전혀 듣지를 않는구나.",
  ui_story_5007_50070202_24_dialog_content = "모르는 사람이 갑자기 나타났는데 수상하지도 않아?",
  ui_story_5007_50070202_25_dialog_content = "네가 지하성의 병사라면 적어도 방문자의 신원부터\n먼저 확인하고 상부에 보고했어야 해!",
  ui_story_5007_50070202_26_dialog_content = "됐어, 카렌. 그냥 지하성의 경비병이나 장교를 찾아가자...",
  ui_story_5007_50070202_27_dialog_content = "멈춰! 너희가 수상한 사람들이라고?",
  ui_story_5007_50070202_28_dialog_content = "그럼 이대로 보낼 수 없어.",
  ui_story_5007_50070202_29_dialog_content = "왜 그걸 그렇게 이해하는 건데?",
  ui_story_5007_50070202_30_dialog_content = "바이스가 방금 말했잖아? 우린 지하성을 지원하러...",
  ui_story_5007_50070202_31_dialog_content = "난 너흴 몰라! 책임관님도 <color=#FFB400>지원은 없다</color>고 했어. 너흰 누구야?!",
  ui_story_5007_50070202_32_dialog_content = "레비! 어디 간 거냐?!",
  ui_story_5007_50070202_33_dialog_content = "브랜트 책임관님! 내가 여기 수상한 3인조를 붙잡았어!",
  ui_story_5007_50070202_34_dialog_content = "멈춰라! 공격하지 마라!",
  ui_story_5007_50070202_35_dialog_content = "응, 책임관님. 멈췄어.",
  ui_story_5007_50070202_36_dialog_content = "누가 허락도 없이 뛰어가라고 했지?!",
  ui_story_5007_50070202_37_dialog_content = "명령도 듣질 않는 거냐? 네 지휘관을 놔두고 돌진부터 하다니,\n대체 무슨 생각을 하는 거냐?",
  ui_story_5007_50070202_38_dialog_content = "명령 들었어. 책임관님이 눈앞에 있는 암귀부터 처리하라고 했잖아.",
  ui_story_5007_50070202_39_dialog_content = "난 멀리서 달려오는 암귀가 보이길래 와서 처리했어.",
  ui_story_5007_50070202_40_dialog_content = "800m 밖에 있는 게 눈앞이냐?",
  ui_story_5007_50070202_41_dialog_content = "눈앞이지. 내 앞 방향이잖아.",
  ui_story_5007_50070202_42_dialog_content = "이건 대체 무슨 논리냐! 넌 그냥 날 화나게 만들고 싶은 모양이구나!",
  ui_story_5007_50070202_43_dialog_content = "아니야!",
  ui_story_5007_50070202_44_dialog_content = "됐다, 됐어. 이 문제는 콜로서스 3인방을 처리한 후에 다시 따지겠다.",
  ui_story_5007_50070202_45_dialog_content = "저기... 콜로서스 3인방이 저희 얘긴가요?",
  ui_story_5007_50070202_46_dialog_content = "그래! 하얀 콜로서스를 몰고 돌아다니는 너희에 대한 정보는\n이미 사방에 널리 알려져 있다.",
  ui_story_5007_50070202_47_dialog_content = "자네는 제3군단 병사겠군. 내 질문에 답해라!",
  ui_story_5007_50070202_48_dialog_content = "왜 여기 있는 거지? 백야성 사람도 데리고 말이야.",
  ui_story_5007_50070202_49_dialog_content = "우린 콜로서스에서 24호 지하성의 지원 요청 신호를 받고 도우러 온 거예요.",
  ui_story_5007_50070202_50_dialog_content = "이쪽의 창을 든 기사는 저희 동료예요.",
  ui_story_5007_50070202_51_dialog_content = "우리가 지원을 요청한 건 맞지만, 우린 이미 자율 방어 명령을 하달받았다.",
  ui_story_5007_50070202_52_dialog_content = "지금 지원이 더 필요한 건 사막 방어선이지만, 그쪽에 가는 건 권하지 않는다.",
  ui_story_5007_50070202_53_dialog_content = "그건 왜죠?",
  ui_story_5007_50070202_54_dialog_content = "너희는 편제에 속하지 않는 외부인들이다.\n별도의 <color=#FFB400>명령이 없는 한</color>, 방어선 쪽에선 너희의 지원을 수용하지 않을 거다.",
  ui_story_5007_50070202_55_dialog_content = "나는 24호 지하성의 임시 책임관 브랜트다.",
  ui_story_5007_50070202_56_dialog_content = "우린 지금 암귀를 소탕하고 수송대를 지원하는 임무를 수행하고 있다.",
  ui_story_5007_50070202_57_dialog_content = "수송 거점에는 아직도 다수의 암귀가 돌아다니고 있다.\n너희에겐 이제 두 가지 선택지가 있다.",
  ui_story_5007_50070202_58_dialog_content = "하나, 우리와 함께 행동한다.",
  ui_story_5007_50070202_59_dialog_content = "둘, 이곳을 떠나서 왔던 곳으로 돌아간다.",
  ui_story_5007_50070202_60_dialog_content = "안녕하세요. 전 이 콜로서스의 조종사 PlayerName인데요...",
  ui_story_5007_50070202_61_dialog_content = "우린 당신들을 지원하기 위해 온 거예요. 그러니 물론 당신들과 함께 행동해야죠.",
  ui_story_5007_50070202_62_dialog_content = "좋다!",
  ui_story_5007_50070202_63_dialog_content = "이제부터 너흰 PlayerName 소대다!",
  ui_story_5007_50070202_64_dialog_content = "24호 지하성을 지원하기로 결정한 이상, 이제부터는 내 지휘를 받아야 한다.",
  ui_story_5007_50070202_65_dialog_content = "이해가 안 돼. 왜 저 사람들을 받아들이는 건데?",
  ui_story_5007_50070202_66_dialog_content = "아주 간단하다. 이건 선임 책임관의 지시다.\n「있는 사람은 모조리 데려올 수밖에 없다」!",
  ui_story_5007_50070202_67_dialog_content = "이것이 바로 가용 전력의 징집인 것이다!",
  ui_story_5007_50070202_68_dialog_content = "PlayerName 소대, 이제부터 우리와 함께 움직인다!",
  ui_story_5007_50070202_69_dialog_content = "다음 작전 목표는 수송 거점의 암귀를 소탕하는 것이다!",
  ui_story_5007_50070202_70_dialog_content = "여명의 빛을 위하여! 전원 출발!",
  ui_story_5007_50070301_1_dialog_content = "PlayerName, 넌 아이테르잖아. 아이테르는 뭐가 대단해?",
  ui_story_5007_50070301_2_dialog_content = "뭐가 대단하냐고? 음... 전장을 보는 능력이 강하다고 할 수 있으려나?",
  ui_story_5007_50070301_3_dialog_content = "강하다...",
  ui_story_5007_50070301_4_dialog_content = "왜 그래? 무슨 할 말 있어?",
  ui_story_5007_50070301_5_dialog_content = "나, 너 마음에 들어!",
  ui_story_5007_50070301_6_dialog_content = "풉! 뭐, 뭐라고? 왜 갑자기 내가 마음에 드는데?",
  ui_story_5007_50070301_7_dialog_content = "브랜트 책임관님이 널 마음에 들어 하니까, 넌 아주 강하겠지.",
  ui_story_5007_50070301_8_dialog_content = "그러니까 나도 네가 마음에 들었어!",
  ui_story_5007_50070301_9_dialog_content = "하아?",
  ui_story_5007_50070301_10_dialog_content = "레비! 어디 있는 거냐?",
  ui_story_5007_50070301_11_dialog_content = "책임관님! 여기야!",
  ui_story_5007_50070301_12_dialog_content = "책임관님! 방금 전방을 조사했는데, 암귀는 발견하지 못했어.",
  ui_story_5007_50070301_13_dialog_content = "언제 돌아온 거지? 돌아와서 즉각 보고하라고 했을 텐데, 못 들은 거냐!",
  ui_story_5007_50070301_14_dialog_content = "들었어. 다음엔 꼭 그럴게.",
  ui_story_5007_50070301_14X_dialog_content = "고지대로 가서 살펴보고, 특이 사항이 있거든 즉각 보고해라.",
  ui_story_5007_50070301_14X1_dialog_content = "응!",
  ui_story_5007_50070301_15_dialog_content = "PlayerName!",
  ui_story_5007_50070301_16_dialog_content = "네? 깜짝이야... 갑자기 왜요?",
  ui_story_5007_50070301_17_dialog_content = "쯧쯧... 팔뚝도 얇고, 몸집도 작고, 다리도 삐쩍 말랐군...",
  ui_story_5007_50070301_18_dialog_content = "평소에 훈련을 하고 있나?",
  ui_story_5007_50070301_19_option_content = "그럼 실력을 좀 보여드릴까요?",
  ui_story_5007_50070301_20_dialog_content = "그래. 어디 한번 보자고!",
  ui_story_5007_50070301_21_dialog_content = "흡! 하! 이얍!",
  ui_story_5007_50070301_22_dialog_content = "마치 방금 태어난 햇병아리를 보는 듯하군.",
  ui_story_5007_50070301_23_dialog_content = "넌 무기로 적을 공격하지 않는 게 좋겠다.",
  ui_story_5007_50070301_24_dialog_content = "그럴 시간이 있으면 살려 달라고 외쳐라!",
  ui_story_5007_50070301_24X1_dialog_content = "뭐, 됐다. 그럼 네 감응 능력은 어떻게 사용하는 거지?",
  ui_story_5007_50070301_25_option_content = "사실 절 훈련시키고 싶어 하는\n사람들이 좀 많긴 해요...",
  ui_story_5007_50070301_26_dialog_content = "그리고 마침 일루미나의 장교도 있었죠.",
  ui_story_5007_50070301_27_dialog_content = "그 사람은 아마 절 특수부대원으로 훈련시키고 싶었던 모양이에요.",
  ui_story_5007_50070301_28_dialog_content = "게다가 저한테 전투의 극의는 「습격할 수 있으면 습격한다」라고 가르쳐 줬어요.",
  ui_story_5007_50070301_29_dialog_content = "대체 어느 장교가 너한테 그런 걸 가르쳐 준 거지?",
  ui_story_5007_50070301_30_dialog_content = "미안하지만 그 사람 체면을 생각해서 이름을 밝힐 수 없겠네요...",
  ui_story_5007_50070301_30X1_dialog_content = "뭐, 됐다. 그 사람이 누군지는 됐고, 네 감응 능력은 어떻게 사용하는 건지 궁금하군.",
  ui_story_5007_50070301_31_dialog_content = "네 감응 능력은 어떻게 사용하는 거지?",
  ui_story_5007_50070301_32_dialog_content = "감응 능력을 통해 메시지를 보낼 수 있나?",
  ui_story_5007_50070301_33_dialog_content = "할 수 있죠. 그게 제 특기인걸요.",
  ui_story_5007_50070301_34_dialog_content = "바이스를 처음 만났을 때, 전 감응 능력을 사용해서 제 목소리를 직접 전했어요.",
  ui_story_5007_50070301_35_dialog_content = "정말 엄청나게 놀라더라니까요.",
  ui_story_5007_50070301_36_dialog_content = "PlayerName, 말하는 데 재미 붙인 모양이네? 별말을 다 하고 말이야.",
  ui_story_5007_50070301_37_dialog_content = "크흠, 어디까지나 보고의 일환이라고.",
  ui_story_5007_50070301_38_dialog_content = "좋다. 넌 꽤 강한 것 같군!",
  ui_story_5007_50070301_39_dialog_content = "그리고 사실 아이테르끼리는 감응 능력으로 메시지를 보내는 게 더 쉬워요. 하지만...",
  ui_story_5007_50070301_40_dialog_content = "음? 왜 말을 하다 마는 거지?",
  ui_story_5007_50070301_41_dialog_content = "아무것도 아니에요. 그냥 누가 좀 생각이 나서요...\n지금은 이미 세상을 떠났지만요. 이 얘기는 안 하는 게 좋겠어요.",
  ui_story_5007_50070301_42_dialog_content = "괴로운 기억을 떠올리게 해서 미안하군...\n<color=#FFB400>동료를 잃는다</color>는 게 얼마나 고통스러운 일인지는 나도 알고 있다.",
  ui_story_5007_50070301_43_dialog_content = "난 위로 같은 건 할 줄 모르지만, 그래도 네가 기운을 냈으면 좋겠군.",
  ui_story_5007_50070301_44_dialog_content = "또 무슨 고민이 있거든 내게 말해도 좋다.",
  ui_story_5007_50070301_45_dialog_content = "난 교관이고, 병사들을 지도하는 게 내 특기니 말이야.",
  ui_story_5007_50070301_46_dialog_content = "네... 고마워요.",
  ui_story_5007_50070301_47_dialog_content = "처음 만났을 때 전 브랜트 씨가 무척 거친 사람이라고 생각했어요.",
  ui_story_5007_50070301_48_dialog_content = "이제 보니 무척 자상한 성격이시네요.",
  ui_story_5007_50070301_49_dialog_content = "브랜트 책임관님이 널 마음에 들어 하니까, 넌 아주 강해.",
  ui_story_5007_50070301_50_dialog_content = "풉!",
  ui_story_5007_50070301_51_dialog_content = "뭐냐? 갑자기 그 반응은?",
  ui_story_5007_50070301_52_dialog_content = "아무것도 아니에요! 그냥 오해가 좀...",
  ui_story_5007_50070301_53_dialog_content = "아이테르가 뿜었다! 나도 할 수 있어! 아이테르보다 더 세게!",
  ui_story_5007_50070301_54_dialog_content = "풉──!",
  ui_story_5007_50070301_55_dialog_content = "그만해라. 그건 또 무슨 쓸데없는 경쟁이냐?",
  ui_story_5007_50070301_56_dialog_content = "언제 돌아온 거지? 돌아왔는데 보고도 안 하는 거냐?!",
  ui_story_5007_50070301_57_dialog_content = "방금 돌아왔어! 암귀 무리가 수송 거점을 향해 달려오고 있어!",
  ui_story_5007_50070301_58_dialog_content = "놈들을 주의를 끌고, 유인해서 해치워라!",
  ui_story_5007_50070301_59_dialog_content = "응! 레비, 돌격!",
  ui_story_5007_50070301_60_dialog_content = "그르르...",
  ui_story_5007_50070301_61_dialog_content = "난 여기 있어! 얼른 덤벼! 암귀!",
  ui_story_5007_50070301_62_dialog_content = "캬아악!",
  ui_story_5007_50070301_63_dialog_content = "도망치려고?!",
  ui_story_5007_50070301_64_dialog_content = "크오오──!",
  ui_story_5007_50070301_65_dialog_content = "뭐지? 저 암귀들, 레비를 아예 무시하고 있잖아?",
  ui_story_5007_50070301_66_dialog_content = "놈들은 수송 거점 중심부로 가려는 거다!",
  ui_story_5007_50070301_67_dialog_content = "암귀들의 반응이 어쨌든 일단 놈들을 막아라!",
  ui_story_5007_50070301_68_dialog_content = "알겠어요!",
  ui_story_5007_50070301_69_dialog_content = "속사 감지──!",
  ui_story_5007_50070301_70_dialog_content = "캬아악!",
  ui_story_5007_50070301_71_dialog_content = "우리가 공격해도 전혀 반응하질 않는데요?",
  ui_story_5007_50070301_72_dialog_content = "무슨 일이 있어도 수송 거점으로 갈 작정이로군.",
  ui_story_5007_50070301_73_dialog_content = "내가 놈들을 유인하겠다!",
  ui_story_5007_50070301_74_dialog_content = "<color=#e8d9bb>탕! 탕! 탕!</color>",
  ui_story_5007_50070301_75_dialog_content = "크오오──!",
  ui_story_5007_50070301_76_dialog_content = "암귀들이 우릴 쳐다보는 것 같은데요? 녀석들의 주의를 끌었어요!",
  ui_story_5007_50070301_77_dialog_content = "공격에 효과가 있었군.",
  ui_story_5007_50070301_78_dialog_content = "이 공격에 이름을 붙인다면, <color=#FFB400>「치명적 유혹」</color>이라고 부르는 게 좋겠지.",
  ui_story_5007_50070301_79_dialog_content = "<size=30>책임관님의 작명 센스가 카론 님과 비슷할 줄은 몰랐네요...</size>",
  ui_story_5007_50070301_80_dialog_content = "뭐라고 했지? 나한테 무슨 불만이라도 있는 거냐?",
  ui_story_5007_50070301_81_dialog_content = "아, 아니에요. 근데 왜 갑자기 공격에 이름을 붙이는 건데요?",
  ui_story_5007_50070301_82_dialog_content = "교관이라면 가끔은 너희 같은 젊은이들의 스타일도 배울 필요가 있거든.",
  ui_story_5007_50070301_83_dialog_content = "방금 자네도 「속사 감지」라면서 큰 소리로 외치지 않았나?",
  ui_story_5007_50070301_84_dialog_content = "갑자기 좀 부끄럽다는 생각이 드네요...",
  ui_story_5007_50070301_85_dialog_content = "집중해라. 암귀들은 이제 곧 우리의 작전 범위에 돌입한다.",
  ui_story_5007_50070301_86_dialog_content = "지금이다! PlayerName!",
  ui_story_5007_50070301_87_dialog_content = "네 지휘 능력을 발휘해 봐라!",
  ui_story_5007_50070301_88_dialog_content = "네? 갑자기 지휘 능력을 보여달라구요? 어떻게 보여주는데요?",
  ui_story_5007_50070301_89_dialog_content = "너희 PlayerName 소대가 평소에 암귀와 어떻게 싸우는지 보여달라는 거다!",
  ui_story_5007_50070302_1_dialog_content = "암귀들이 계속 브랜트 씨랑 PlayerName 쪽으로 달려가고 있어요!",
  ui_story_5007_50070302_2_dialog_content = "진형을 유지할 수가 없어요!",
  ui_story_5007_50070302_3_dialog_content = "내가 이렇게 암귀를 잘 유인하는 타입이었나...",
  ui_story_5007_50070302_4_dialog_content = "내 공격이 암귀들을 자극했기 때문이겠지.",
  ui_story_5007_50070302_5_dialog_content = "이것도 루미나의 일종이다.",
  ui_story_5007_50070302_6_dialog_content = "네가 많은 오로리안과 함께 싸워봤다면 내 말을 이해할 수 있겠지!",
  ui_story_5007_50070302_7_dialog_content = "캬악──!",
  ui_story_5007_50070302_8_dialog_content = "암귀가 점점 많아지고 있어!",
  ui_story_5007_50070302_9_dialog_content = "PlayerName, 날 따라와라!",
  ui_story_5007_50070302_10_dialog_content = "네?",
  ui_story_5007_50070302_11_dialog_content = "수송 거점 쪽으로 달려라! 거기 우리 사람들이 있다!",
  ui_story_5007_50070302_12_dialog_content = "감응 능력을 사용해서 암귀와 마주치지 않을 길을 찾아라!",
  ui_story_5007_50070302_13_dialog_content = "다른 사람들은 후방을 엄호하며 따라와라!",
  ui_story_5007_50070302_14_dialog_content = "크오오──!",
  ui_story_5007_50070302_15_dialog_content = "어떡하죠? 벌써 여기까지 왔는데 암귀가 계속 쫓아오고 있어요!",
  ui_story_5007_50070302_16_dialog_content = "걱정할 거 없다! 지휘관에게 이런 상황은 흔한 일이니까!",
  ui_story_5007_50070302_17_dialog_content = "모든 적들은 네 목을 꺾어버리고, 네 병사들을 짓뭉개고 싶어 하지!",
  ui_story_5007_50070302_18_dialog_content = "지금 이 순간 우리에게 필요한 건 바로 「벽」이다!",
  ui_story_5007_50070302_19_dialog_content = "벽을 어디서 찾죠?",
  ui_story_5007_50070302_20_dialog_content = "이제 나타날 거다... 그람──!",
  ui_story_5007_50070302_23_dialog_content = "크오오──!",
  ui_story_5007_50070302_24_dialog_content = "당신이 소리를 지르니까 암귀들이 더 사나워졌잖아요!",
  ui_story_5007_50070302_25_dialog_content = "크오오──!",
  ui_story_5007_50070302_26_dialog_content = "이러다 곧 암귀한테 따라잡히겠어요! 어떡하죠?!",
  ui_story_5007_50070302_27_dialog_content = "누가 그렇게 천천히 뛰라고 했나! 너도 날 따라서 그람을 불러라!",
  ui_story_5007_50070302_28_dialog_content = "그게 누군지는 모르겠지만 일단 알겠어요!",
  ui_story_5007_50070302_29_dialog_content = "그라아아아암───!",
  ui_story_5007_50070302_30_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5007_50070302_32_dialog_content = "뭐야?! 암귀를 날려버린 거야?",
  ui_story_5007_50070302_33_dialog_content = "부딪힌 것만으로 납작해졌잖아! 무슨 말도 안 되는...",
  ui_story_5007_50070302_34_dialog_content = "......",
  ui_story_5007_50070302_35_dialog_content = "아... 그, 그냥 좀 놀라서 해본 말이에요...",
  ui_story_5007_50070302_36_dialog_content = "브랜트, 진짜로 이 아이테르를 부대에 받아들인 건가?",
  ui_story_5007_50070302_37_dialog_content = "그래. 이건 모두 전세를 위한 결정이다.",
  ui_story_5007_50070302_38_dialog_content = "그람, 일단 뒤에 있는 암귀부터 해치워버려! 의견이 있거든 나중에 얘기하자고.",
  ui_story_5007_50070302_39_dialog_content = "알겠다.",
  ui_story_5007_50070302_40_dialog_content = "저 사람이 우리가 불렀던 「그람」인 거군요.",
  ui_story_5007_50070302_41_dialog_content = "그렇다. 이 친구가 바로 우리 24호 지하성 소대의 <color=#FFB400>「성벽」</color>이지.",
  ui_story_5007_50070302_42_dialog_content = "캬아악!",
  ui_story_5007_50070302_43_dialog_content = "크르르!",
  ui_story_5007_50070302_44_dialog_content = "확실히 벽처럼 커다란 사람이네요...\n순식간에 암귀들을 전부 날려 버리다니... 엄청 강하네요!",
  ui_story_5007_50070302_45_dialog_content = "그람, 다른 사람들은 어디 있지? 임무 진행 상황은 어떤가?",
  ui_story_5007_50070302_46_dialog_content = "임무는 완수했다. 다들 안전 구역에서 기다리고 있다.",
  ui_story_5007_50070302_47_dialog_content = "좋아! 역시 자네가 가장 믿음직하다니까!",
  ui_story_5007_50070302_48_dialog_content = "참, 정식으로 소개해 줘야겠군.",
  ui_story_5007_50070302_50_dialog_content = "이 녀석은 PlayerName, 바로 그 소문의 아이테르다.",
  ui_story_5007_50070302_51_dialog_content = "비록 젊지만 괜찮은 녀석이더군. 일개 소대의 지휘 능력 정도는 갖추고 있다.",
  ui_story_5007_50070302_52_dialog_content = "이번 기회에 서로 좀 알아두라고.",
  ui_story_5007_50070302_52X_dialog_content = "안녕하세요, 전...",
  ui_story_5007_50070302_53_dialog_content = "관심 없다.",
  ui_story_5007_50070302_54_dialog_content = "그럼 난 레비를 지원하러 가도록 하지.",
  ui_story_5007_50070302_55_dialog_content = "...저한테 전혀 관심이 없어 보이는데요... 아예 무시당한 것 같네요.",
  ui_story_5007_50070302_56_dialog_content = "신경 쓰지 마라.",
  ui_story_5007_50070302_57_dialog_content = "이제 처음 만났을 뿐이잖나.",
  ui_story_5007_50070302_58_dialog_content = "전우 간의 관계란 건 함께 싸우면서 자연스럽게 좋아지기 마련이다.",
  ui_story_5007_50070302_59_dialog_content = "괜찮아요. 저도 별로 신경 쓰진 않으니까요.",
  ui_story_5007_50070302_60_dialog_content = "왜 상관이 없지? 함께 싸우기로 결정한 이상, 서로를 이해해야만 한다.",
  ui_story_5007_50070302_61_dialog_content = "그리고 전우와 좋은 관계를 유지해야만 부대의 협력을 촉진할 수 있지.",
  ui_story_5007_50070302_62_dialog_content = "PlayerName, 걱정하지 마라. 그람에겐 내가 잘 말해줄 테니 말이다!",
  ui_story_5007_50070302_63_dialog_content = "친해지고 나면 너도 알게 될 거다.\n저 친구, 겉으로는 엄숙해 보여도 실제로는 꽤 수다스럽거든.",
  ui_story_5007_50070302_64_dialog_content = "뭐, 딱히 꼭 친해져야 할 필요도 없지 않을까요...",
  ui_story_5007_50070302_65_dialog_content = "아니, 반드시 필요하다!",
  ui_story_5007_50070302_66_dialog_content = "잘 들어라. 우리처럼 팀을 이루어 작전을 수행하는 군인들이라면...",
  ui_story_5007_50070302_67_dialog_content = "부대원이 서로 익숙해지고, 서로의 전투 스타일을 이해하는 것은 매우 중요하다.",
  ui_story_5007_50070302_68_dialog_content = "이제 30분 내로 이 수송 거점에 3개의 소대가 집결할 거다.",
  ui_story_5007_50070302_69_dialog_content = "이제 다른 사람들을 만나게 되면 너도 그들과 어울리는 데 익숙해져야만 한다!",
  ui_story_5007_50070401_1_dialog_content = "여러분~ 정──말 감사합니다아~! 안녕하세요! 저는 안시아예요!",
  ui_story_5007_50070401_2_dialog_content = "제가 바로 이 수송대의 책임자랍니다!",
  ui_story_5007_50070401_3_dialog_content = "이쪽의 두 사람은 커디와 알루라! 우린 <color=#FFB400>23호 지하성</color>으로 가는 중이에요!",
  ui_story_5007_50070401_4_dialog_content = "자세한 얘기는 나중에 하도록 하지.",
  ui_story_5007_50070401_5_dialog_content = "지금 너희 수송대가 있는 곳은 상대적으로 안전하다.",
  ui_story_5007_50070401_6_dialog_content = "이쪽은 PlayerName, 이 녀석을 너희한테 붙여주마. 암귀가 나타나면 녀석이 바로 알려줄 거다.",
  ui_story_5007_50070401_7_dialog_content = "난 그람과 함께 다른 녀석들이 뭘 하고 있는지 보러 가겠다.",
  ui_story_5007_50070401_8_dialog_content = "네네~ 좋아요! 잘 알겠습니다!",
  ui_story_5007_50070401_9_dialog_content = "뭐야... 그냥 이렇게 두고 가는 거예요?",
  ui_story_5007_50070401_10_dialog_content = "걱정하지 마세요! 우리랑 여기 있으면 위험하지 않을 테니까요~",
  ui_story_5007_50070401_11_dialog_content = "비켜, 길 막지 마.",
  ui_story_5007_50070401_12_dialog_content = "잠깐만! 알루라! 임무도 제쳐 두고 가버릴 셈이야?",
  ui_story_5007_50070401_13_dialog_content = "미안한데 가슴 좀 너무 들이대지 말아 줄래? ...커디.",
  ui_story_5007_50070401_14_dialog_content = "아, 고의는 아니었어! 급한 마음에 나도 모르게...",
  ui_story_5007_50070401_15_dialog_content = "내가 가고 나서 암귀가 습격할까 걱정인 거라면 안심하라고.",
  ui_story_5007_50070401_16_dialog_content = "방금 그 사람이 여기가 안전하다고 했잖아. 나는 못 믿어도 저 사람은 믿을 거 아냐?",
  ui_story_5007_50070401_17_dialog_content = "너흰 모두 같은 일루미나 사람들이잖아.",
  ui_story_5007_50070401_18_dialog_content = "정말... 누가 움브라톤 사람 아니랄까 봐.\n역시 내 임무가 널 감시하는 일이라는 걸 너도 잘 알고 있는 모양이네.",
  ui_story_5007_50070401_19_dialog_content = "흥, 재미없어.",
  ui_story_5007_50070401_20_dialog_content = "너한테 날 간섭할 권리가 있다고 생각해? 네가 치안관이라는 이유로?",
  ui_story_5007_50070401_21_dialog_content = "PlayerName 씨! 지금 이 상황에서 제가 어떻게 하는 게 좋을까요?",
  ui_story_5007_50070401_22_dialog_content = "지금 나한테 묻는 거야?",
  ui_story_5007_50070401_23_dialog_content = "네, 맞아요! 다들 그만 싸우게 좀 도와주세요!",
  ui_story_5007_50070401_24_dialog_content = "그런 눈빛으로 날 봐도 소용없다고...",
  ui_story_5007_50070401_25_dialog_content = "난 너희가 뭐 때문에 싸우는지도 모른단 말이야.",
  ui_story_5007_50070401_26_dialog_content = "휴... 그래서 둘이 왜 싸우는 건데?",
  ui_story_5007_50070401_27_dialog_content = "그게 말이죠! 제 말 좀 들어보세요.",
  ui_story_5007_50070401_28_dialog_content = "이 이야기는 일단 우리가 자난성에서 처음 만났을 때부터 시작해야 할 것 같아요!\n그때까지만 해도 우린 꽤 화목했어요.",
  ui_story_5007_50070401_29_dialog_content = "전 블랙 엄브렐라 연구소에 들어온 지 얼마 안 된 신입이고, <color=#FFB400>이제 막 진급했어요</color>!",
  ui_story_5007_50070401_30_dialog_content = "잠깐만! 이야기가 너무 길어질 것 같은데... 요점만 말해줄 수 있을까?",
  ui_story_5007_50070401_31_dialog_content = "좋아요. 노력해 볼게요.",
  ui_story_5007_50070401_32_dialog_content = "사실 우린 길에서 모래폭풍을 만났어요.",
  ui_story_5007_50070401_33_dialog_content = "모래폭풍이 여기까지 오기 전에 제가 확인해 볼게요!",
  ui_story_5007_50070401_34_dialog_content = "잠깐만...",
  ui_story_5007_50070401_35_dialog_content = "꺄앗──!",
  ui_story_5007_50070401_36_dialog_content = "안시아, 뭐 하는 거야?",
  ui_story_5007_50070401_37_dialog_content = "얼른 문을 닫아! 모래폭풍이 빠르게 다가오고 있어!",
  ui_story_5007_50070401_38_dialog_content = "아... 미안해요. 밖에 바람이 너무 많이 불어서, 힘껏 문을 닫다가... 차 문이 떨어졌어요.",
  ui_story_5007_50070401_39_dialog_content = "걱정하지 마세요! 제가 다시 달 수 있어요!",
  ui_story_5007_50070401_40_dialog_content = "아얏──!",
  ui_story_5007_50070401_41_dialog_content = "또 뭐야?",
  ui_story_5007_50070401_42_dialog_content = "<color=#e8d9bb>휘이잉──</color>",
  ui_story_5007_50070401_43_dialog_content = "뭐야, 안시아는 어디 갔어?",
  ui_story_5007_50070401_44_dialog_content = "모래폭풍에 날아가 버렸어... 내가 가서 찾아볼게.",
  ui_story_5007_50070401_45_dialog_content = "<color=#e8d9bb>휘이잉──</color>",
  ui_story_5007_50070401_46_dialog_content = "구해줘서 고마워요! 사실 방금 전엔 발을 헛디뎌서 날아간 거예요.",
  ui_story_5007_50070401_47_dialog_content = "근데 커디는요? 왜 차에 없는 거죠?",
  ui_story_5007_50070401_48_dialog_content = "...하나를 찾아왔더니 이번엔 다른 하나가 없어지네. 정말이지...",
  ui_story_5007_50070401_49_dialog_content = "내가 찾아볼게.",
  ui_story_5007_50070401_50_dialog_content = "...그거 「밑 빠진 독에 물 붓기」 아냐?",
  ui_story_5007_50070401_53_dialog_content = "그래. 그러다 나중엔 암귀들한테 습격당해서 화물도 지키면서 두 사람을 구해야 했어.",
  ui_story_5007_50070401_54_dialog_content = "게다가 차로 돌파하면서 모래까지 잔뜩 먹었어.",
  ui_story_5007_50070401_55_dialog_content = "결국 우리 셋만 남았고, 수송 거점으로 들어올 수밖에 없었지.",
  ui_story_5007_50070401_56_dialog_content = "그리고 이 녀석은 수송 거점의 문을 들이받기 직전이 돼서야\n사실은 지하성의 수비병들과 연락이 되지 않는다고 털어놨어.",
  ui_story_5007_50070401_57_dialog_content = "미안해요... 저도 거점이 문을 닫았을 줄은 몰랐다구요.",
  ui_story_5007_50070401_58_dialog_content = "그래도 다행히 누가 나와서 우릴 구해줬어요!",
  ui_story_5007_50070401_59_dialog_content = "지금까지 말한 문제 중 어느 하나만으로도 우리 일행을 전멸시킬 수도 있었어.",
  ui_story_5007_50070401_60_dialog_content = "우린 그저 운이 좋아서 여기까지 올 수 있었던 거야.",
  ui_story_5007_50070401_61_dialog_content = "다들 싸우는 게 사실은 안시아 너 때문이었구나...",
  ui_story_5007_50070401_62_dialog_content = "그게... 그러니까... 이런 임무를 맡는 건 저도 처음이라서...\n경험이 부족한 탓이에요!",
  ui_story_5007_50070401_63_dialog_content = "그럼 역시 네가 반성할 필요가 있을 것 같아.",
  ui_story_5007_50070401_64_dialog_content = "미안해요...",
  ui_story_5007_50070401_65_dialog_content = "사과로 문제를 해결할 수 있다면 치안관이 왜 필요해? 안 그래, 커디?",
  ui_story_5007_50070401_66_dialog_content = "뭐야? 또 싸우자는 거야?!",
  ui_story_5007_50070401_67_dialog_content = "오는 동안 내가 가장 많이 들은 말이 바로 「미안해」야.",
  ui_story_5007_50070401_68_dialog_content = "난 쟤보다 더 제대로 된 지휘관이랑 이야기하고 싶어.",
  ui_story_5007_50070401_69_dialog_content = "...왜 날 그렇게 보는 건데...",
  ui_story_5007_50070401_70_dialog_content = "브랜트 씨랑 이야기하고 싶다면 조금만 기다려 봐. 다들 이미 돌아왔으니까.",
  ui_story_5007_50070401_71_dialog_content = "브랜트 책임관님! 언제 오신 거죠?",
  ui_story_5007_50070401_72_dialog_content = "방금 전에 왔다.",
  ui_story_5007_50070401_73_dialog_content = "PlayerName, 우리가 왔다는 걸 언제 알았지?",
  ui_story_5007_50070401_74_dialog_content = "1분 정도 전에요. 감응 능력을 쓴 건 아니에요. 그냥 소리가 들렸어요.",
  ui_story_5007_50070401_75_dialog_content = "목소리가 엄청 컸으니까요. 꼭 누굴 혼...",
  ui_story_5007_50070401_76_dialog_content = "날 혼내고 있었어.",
  ui_story_5007_50070401_77_dialog_content = "내가 너무 멀리 뛰쳐나갔거든!",
  ui_story_5007_50070401_78_dialog_content = "그걸 자기 입으로 말하는구나...",
  ui_story_5007_50070401_79_dialog_content = "난 아주 당당해!",
  ui_story_5007_50070401_80_dialog_content = "됐다. 이 녀석 일은 신경 쓰지 마라.",
  ui_story_5007_50070401_81_dialog_content = "방금 누가 나한테 할 말이 있다고 했지?",
  ui_story_5007_50070401_82_dialog_content = "저예요. 제 용건은 아주 간단해요. 추가 수당을 요구하겠어요.",
  ui_story_5007_50070401_83_dialog_content = "무슨 뜻이지? 왜 갑자기 그걸 나한테 말하는 건가?",
  ui_story_5007_50070401_84_dialog_content = "책임자가 못 미더워서 임무 수행에 중대한 지장을 주고 있어요.",
  ui_story_5007_50070401_85_dialog_content = "임무의 요구사항도 의뢰 계약서와 다른데, 사전 설명에도 언급하지 않았어요.",
  ui_story_5007_50070401_86_dialog_content = "그러니 전 추가 수당을 요구하거나 임무를 포기할 권리가 있어요.",
  ui_story_5007_50070401_87_dialog_content = "당신을 찾은 건 이 특수한 상황을 처리할 방법을 결정할\n일루미나 측의 책임자가 필요했기 때문이에요.",
  ui_story_5007_50070401_88_dialog_content = "의뢰 계약서에는 책임자한테 물어보라고 되어 있지만...",
  ui_story_5007_50070401_89_dialog_content = "아, 그게... 제가 받은 임무 수첩에는 그런 내용이 없는걸요.",
  ui_story_5007_50070401_90_dialog_content = "하지만 이 책임자는 아무것도 몰라요.",
  ui_story_5007_50070401_91_dialog_content = "상황은 이해했다. 자네의 신분증을 보여주게.",
  ui_story_5007_50070401_92_dialog_content = "이건 쿠리어 길드의 추천서고, 전 쿠리어 길드의 추천을 받고 온 용병이에요.",
  ui_story_5007_50070401_93_dialog_content = "확인했다. 자네 신분에는 문제가 없군.",
  ui_story_5007_50070401_94_dialog_content = "자네의 요구는 이해했다. 용병으로서 충분히 합당한 요구지.",
  ui_story_5007_50070401_95_dialog_content = "하지만 이 문제는 임무의 의뢰인, 다시 말해서 쿠리어 길드에게\n추가 보수를 요구해야 하는 게 맞지 않겠나?",
  ui_story_5007_50070401_96_dialog_content = "알고 있어요. 하지만 지금이 상황이 특수하잖아요.\n만약 우리가 23호 지하성에 가지 못하면요?",
  ui_story_5007_50070401_97_dialog_content = "그럼 화물과 저 둘을 데리고 다시 자난성으로 돌아가야겠지.",
  ui_story_5007_50070401_98_dialog_content = "난 자네가 매우 유능한 용병이라고 생각한다.",
  ui_story_5007_50070401_99_dialog_content = "이 두 사람과 화물을 온전한 상태로 이곳까지 데려온 것을 보면 알 수 있지.",
  ui_story_5007_50070401_100_dialog_content = "부디 자네가 포기하지 않았으면 좋겠군...",
  ui_story_5007_50070401_101_dialog_content = "아, 맞다! 화물!",
  ui_story_5007_50070401_102_dialog_content = "아직 화물 상태 확인을 안 했어요!",
  ui_story_5007_50070401_104_dialog_content = "수송 거점에 들어온 지도 한참이 됐는데... 대체 머릿속에 임무 생각이 있기는 한 걸까...",
  ui_story_5007_50070401_105_dialog_content = "...마지막으로, 자네들 책임자의 신뢰도가 떨어진다는 점은 인정하지 않을 수 없겠군.",
  ui_story_5007_50070401_106_dialog_content = "그럼 안시아가 화물을 확인한 후 다음 일정을 논의하도록 하지.",
  ui_story_5007_50070501_1_dialog_content = "음... 화물 상자는 파손되지 않은 것 같네. 그래도 혹시 모르니까 열어서 확인해 볼까?",
  ui_story_5007_50070501_2_dialog_content = "......",
  ui_story_5007_50070501_3_dialog_content = "열려라! 이얍!",
  ui_story_5007_50070501_4_dialog_content = "음음, 이 상자에는 문제가 없네.",
  ui_story_5007_50070501_5_dialog_content = "............",
  ui_story_5007_50070501_6_dialog_content = "이번엔 이쪽을 확인해 볼까...",
  ui_story_5007_50070501_7_dialog_content = "아...",
  ui_story_5007_50070501_8_dialog_content = "으아아아앗! 누, 누구세요? 어, 언제부터 거기 서 있던 거죠?",
  ui_story_5007_50070501_9_dialog_content = "아... 저, 전 처음부터 그람 님이랑 같이 여러분을 맞이하러 왔었는데요...",
  ui_story_5007_50070501_10_dialog_content = "전 비다예요...",
  ui_story_5007_50070501_11_dialog_content = "나, 나중에 보초를 서러 갔구요... 기, 기억 안 나시나요?",
  ui_story_5007_50070501_12_dialog_content = "미안해요. 잊어버렸나 봐요. 여기서 뭐 하는데요?",
  ui_story_5007_50070501_13_dialog_content = "저, 전 기계를 좀 알거든요... 제가 도와드릴게요. 그리고... 차량도 점검하구요.",
  ui_story_5007_50070501_14_dialog_content = "그렇구나... 도와주는 건 좋지만, 무서우니까 말도 없이 옆에 서 있지는 마세요.",
  ui_story_5007_50070501_15_dialog_content = "어떤가?",
  ui_story_5007_50070501_16_dialog_content = "휴! 다행히 화물은 멀쩡해요. 안 그러면 제 목숨이 위험했을 거라구요.",
  ui_story_5007_50070501_17_dialog_content = "그걸 이제야 확인하다니, 이래서야 진짜 문제가 생겼을 땐 이미 늦었을 거라고.",
  ui_story_5007_50070501_18_dialog_content = "화물에 문제가 생기면 용병이 책임을 져야지.",
  ui_story_5007_50070501_19_dialog_content = "화물에 문제가 생겼다면, 그건 내가 너흴 구해주느라\n화물을 지킬 여력이 없었던 거 아닐까?",
  ui_story_5007_50070501_20_dialog_content = "여기서 싸우지 마라.",
  ui_story_5007_50070501_21_dialog_content = "이미 24호 지하성에 사람을 보내 소식을 전했다.\n그럼 이 화물들을 안으로 옮겨주길 바란다.",
  ui_story_5007_50070501_22_dialog_content = "수송 거점에는 방어 시설이 없으니, 언제 또 암귀가 다시 들이닥칠지도 모른다.",
  ui_story_5007_50070501_23_dialog_content = "잠깐만요!",
  ui_story_5007_50070501_24_dialog_content = "저기... 역시 전 계속해서 <color=#FFB400>23호 지하성까지 화물을 전달하고 싶어요</color>!",
  ui_story_5007_50070501_25_dialog_content = "이게 그렇게 급한 물건이야?",
  ui_story_5007_50070501_26_dialog_content = "23호 지하성이면 방어선에 있는 거로 기억하는데,\n그럼 설마... 최전방으로 보내는 중요한...",
  ui_story_5007_50070501_27_dialog_content = "맞아요! 이건... <color=#FFB400>중요한 장치</color>의... 예비 부품이에요!",
  ui_story_5007_50070501_28_dialog_content = "비록 예비용이긴 하지만... 그래도 이번 임무는 저한테 아주 중요해요!",
  ui_story_5007_50070501_29_dialog_content = "미자드 님이 저한테 이런 임무를 맡기신 건 처음이거든요.",
  ui_story_5007_50070501_30_dialog_content = "수송이 늦어지는 정도라면 절 용서해 주실지도 모르지만... 만약 갖다 주지 못한다면...",
  ui_story_5007_50070501_31_dialog_content = "절 끝장내실지도 모른다구요!",
  ui_story_5007_50070501_32_dialog_content = "브랜트 책임관님, 24호 지하성의 차량과 인원을 좀 빌릴 순 없을까요?",
  ui_story_5007_50070501_32X_dialog_content = "아...",
  ui_story_5007_50070501_33_dialog_content = "비다! 뒤에 숨지 말고 나와서 보고해라!",
  ui_story_5007_50070501_36_dialog_content = "네...",
  ui_story_5007_50070501_38_dialog_content = "보고드립니다. 브랜트 책임관님... 주변의 차량들을... 모두 검사했습니다.",
  ui_story_5007_50070501_39_dialog_content = "하, 한 대도... 사용할 수 없습니다.",
  ui_story_5007_50070501_40_dialog_content = "네?! 어째서죠?",
  ui_story_5007_50070501_41_dialog_content = "암귀가 차량을 전부 박살 냈거든.",
  ui_story_5007_50070501_42_dialog_content = "자네들이 오기 전, 수송 거점은 이미 암귀에게 습격당했다.",
  ui_story_5007_50070501_43_dialog_content = "하지만 자네들에게 차량을 줘서 육로로 수송하는 것보다 더 좋은 방법이 있지.",
  ui_story_5007_50070501_44_dialog_content = "PlayerName, 너도 봤겠지만, 이곳엔 사용 가능한 차량이 없다.",
  ui_story_5007_50070501_45_dialog_content = "아! 이해했어요!",
  ui_story_5007_50070501_46_dialog_content = "우리 멋진 PlayerName 씨... 보시다시피 저희가 지금 좀 곤란한 상황인데요...\n브랜트 책임관님 말씀이 무슨 뜻인지 이해하셨죠?",
  ui_story_5007_50070501_47_option_content = "이해했어.",
  ui_story_5007_50070501_48_dialog_content = "콜로서스를 가지고 화물을 운송하고 싶은 거지?",
  ui_story_5007_50070501_49_dialog_content = "사실 우리가 이곳에 온 것도 뭔가 도울 일이 없는지 보러 온 거였어.",
  ui_story_5007_50070501_50_dialog_content = "그러니까 너희 일도 우리가 도와줄 수 있어.",
  ui_story_5007_50070501_51_dialog_content = "정말 흔쾌히 승낙해버렸네.",
  ui_story_5007_50070501_52_option_content = "전혀 모르겠어.",
  ui_story_5007_50070501_53_dialog_content = "PlayerName 씨, 일루미나는 도움을 준 사람들을 결코 잊지 않아요!",
  ui_story_5007_50070501_54_dialog_content = "우린 가끔 용병도 모집하고 충분한 보수도 지급하고 있어요!",
  ui_story_5007_50070501_55_dialog_content = "...말이 나온 김에 그 충분한 보수, 한 번 더 강조하고 싶은걸.",
  ui_story_5007_50070501_56_dialog_content = "물론 임무를 완수하고 나면 추가 보수도 지급할 거예요! 아~주 많이요!",
  ui_story_5007_50070501_57_dialog_content = "100% 이해했어!",
  ui_story_5007_50070501_58_dialog_content = "수송대와 화물을 방어선의 23호 지하성으로 운반해 주면 되는 거잖아? 돈을 받고!",
  ui_story_5007_50070501_58X_dialog_content = "그래, 그래. 기꺼이 도와줄게!",
  ui_story_5007_50070501_59_dialog_content = "잠깐 기다려.",
  ui_story_5007_50070501_60_dialog_content = "미리 확인해 두고 싶은데 말이지. 너흰 우리가 어딜 가려는 건지 정확히 알고 있어?",
  ui_story_5007_50070501_61_dialog_content = "23호 지하성은 지금 암귀와 교전 중이라고.",
  ui_story_5007_50070501_62_dialog_content = "거긴 전장이야. 부디 성급하게 결정하진 않았으면 해.",
  ui_story_5007_50070501_63_dialog_content = "정식 고용 관계도 아니고, 그냥 말로만 도와주겠다고 해놓고...\n나중에 후회하는 모습은 보고 싶지 않아.",
  ui_story_5007_50070501_65_dialog_content = "콜로서스는 날 수 있고, 상황이 좋지 않다면 착륙하지 않고 다시 돌아올 수도 있어.",
  ui_story_5007_50070501_66_dialog_content = "대신 착륙할 때 돌발 상황이 발생한다면, 다수의 암귀와 싸우게 될지도 몰라.",
  ui_story_5007_50070501_67_dialog_content = "우린 많은 암귀와 싸워 왔어.",
  ui_story_5007_50070501_68_dialog_content = "조종사가 있는 한 우린 아주 강해!",
  ui_story_5007_50070501_69_dialog_content = "크흠, 갑자기 날 칭찬하니까 역시 좀 부끄럽단 말이지...",
  ui_story_5007_50070501_70_dialog_content = "아무튼 우리도 충분히 생각해서 말한 거야. 우리가 도와줄게.\n가야 할 곳이 전장이라 해도 말이야.",
  ui_story_5007_50070501_71_dialog_content = "비록 구두 약속일 뿐이지만, 우린 절대 후회하진 않을 거야.\n<color=#FFB400>우릴 믿어줬으면 좋겠어</color>.",
  ui_story_5007_50070501_72_dialog_content = "믿을게요! 전 여러분을 무조건 믿어요!",
  ui_story_5007_50070501_73_dialog_content = "좋아, 알겠어.",
  ui_story_5007_50070501_74_dialog_content = "혹시 무슨 불만이 있는 거면 이번 임무를 포기해도 상관없어.",
  ui_story_5007_50070501_75_dialog_content = "저기, 브랜트 씨?",
  ui_story_5007_50070501_76_dialog_content = "뭐야, 지금 날 무시한 거야?!",
  ui_story_5007_50070501_77_dialog_content = "보급을 좀 제공해 줬으면 해요.",
  ui_story_5007_50070501_78_dialog_content = "사실 이번 임무의 탄약 소모량은 제 예상을 훨씬 뛰어넘었거든요.",
  ui_story_5007_50070501_79_dialog_content = "물론 가능하지.",
  ui_story_5007_50070501_80_dialog_content = "저기... 사실 저도 보급이 필요해요.",
  ui_story_5007_50070501_81_dialog_content = "<color=#e8d9bb>꼬르륵...</color>",
  ui_story_5007_50070501_82_dialog_content = "방금 그거 배에서 난 소리야?",
  ui_story_5007_50070501_83_dialog_content = "맞아요... 어, 어제부터 아무것도 못 먹었더니...\n에너지 소모량이 제 예상을 훨씬 뛰어넘었거든요.",
  ui_story_5007_50070501_84_dialog_content = "레비, 창고에 가서 먹을 만한 통조림과 냄비를 가져와라.",
  ui_story_5007_50070501_85_dialog_content = "비다, 넌 지하성에 돌아가서 알루라 양에게 줄 탄약을 찾아봐라.",
  ui_story_5007_50070501_86_dialog_content = "나머지 사람들은 나와 함께 화물을 옮긴다.",
  ui_story_5007_50070501_87_dialog_content = "그럼 콜로서스 부근에서 집결하도록.",
  ui_story_5007_50070501_88_dialog_content = "그리고 PlayerName, 지금 수송 거점의 상황이 어떤지 감응해 줬으면 좋겠군.",
  ui_story_5007_50070501_89_dialog_content = "...어느새 제가 탐지 장비처럼 쓰이고 있는 느낌인데요.",
  ui_story_5007_50070501_90_dialog_content = "지금 그 어떤 탐지 장비도 너보다 유용하진 못해. 투덜대지 말고 서둘러라.",
  ui_story_5007_50070501_91_dialog_content = "네, 네. 알겠습니다요.",
  ui_story_5007_50070501_92_dialog_content = "왠지...",
  ui_story_5007_50070501_93_dialog_content = "크르르르...",
  ui_story_5007_50070501_94_dialog_content = "또 암귀가 수송 거점에 들어온 것 같아요.",
  ui_story_5007_50070501_95_dialog_content = "그럼 우선 암귀부터 처리하고 임무를 수행하자고!",
  ui_story_5007_50070502_1_dialog_content = "브랜트.",
  ui_story_5007_50070502_2_dialog_content = "저 아이테르를 계속 남겨둘 생각인가?",
  ui_story_5007_50070502_3_dialog_content = "그래. 비록 나이도 어리고, 경험과 능력 역시 부족할지도 모르지.",
  ui_story_5007_50070502_4_dialog_content = "하지만 녀석이 전투를 지휘하는 모습을 보면 자네도 이해할 거야.",
  ui_story_5007_50070502_5_dialog_content = "녀석이 상대해 온 암귀들은 아마 다른 전사들보다 결코 적지 않을 거다. 훌륭한 재목이라고.",
  ui_story_5007_50070502_6_dialog_content = "녀석이 우리와 함께한다면, 어쩌면 용사 별동대 같은 팀을 다시 만들 수 있을지도 모른다.",
  ui_story_5007_50070502_7_dialog_content = "그러니 자네도 저 녀석과 좀 더 잘 지내는 게 어떻겠나...",
  ui_story_5007_50070502_8_dialog_content = "자네가 녀석을 데리고 새로운 팀을 만들고 싶다면 난 반대하지 않아. 하지만 난 관심 없어.",
  ui_story_5007_50070502_9_dialog_content = "그러니 나한테 녀석과 어울리라고 강요할 필요도 없다는 거지.",
  ui_story_5007_50070502_10_dialog_content = "그람, 이건 좋은 기회야.",
  ui_story_5007_50070502_11_dialog_content = "우리가 <color=#FFB400>무엇 때문에 싸워 왔는지</color> 잊지 마라.",
  ui_story_5007_50070502_12_dialog_content = "자네도 젊은이들과 힘을 합친다면, 분명히 <color=#FFB400>새로운 미래</color>를 보게 될 거야.",
  ui_story_5007_50070502_13_dialog_content = "이미 몇 번이나 했던 말 아닌가...",
  ui_story_5007_50070502_14_dialog_content = "그리고 난 저들이 자넬 분명히 좋아할 거라고 생각한다...",
  ui_story_5007_50070502_15_dialog_content = "꿀꺽── 꿀꺽── 저, 정말 맛있어요!",
  ui_story_5007_50070502_16_dialog_content = "흑흑, 정말 최고예요... 배도 채워주고 영혼을 치유해주는 맛이에요!",
  ui_story_5007_50070502_17_dialog_content = "응? 무슨 일이야?",
  ui_story_5007_50070502_18_dialog_content = "왜 둘이서 냄비 앞에서 울고 있어?",
  ui_story_5007_50070502_19_dialog_content = "PlayerName 씨! 얼른 이 수프 좀 먹어봐요!",
  ui_story_5007_50070502_20_dialog_content = "수, 수프? 바이스가 만든 수프라면... 내 기억엔 매번...",
  ui_story_5007_50070502_21_dialog_content = "PlayerName, 설마 또 나 욕하는 거야?",
  ui_story_5007_50070502_22_dialog_content = "그, 그런 거 아냐! 그냥... 갑자기 네가 걱정이 돼서 그래.",
  ui_story_5007_50070502_23_dialog_content = "응? 수상한데... 손에 들고 있는 건 또 뭐야?",
  ui_story_5007_50070502_24_dialog_content = "냄새가 진짜 좋네!",
  ui_story_5007_50070502_25_dialog_content = "우린 아직도 물건 나르고 있는데, 너희끼리 벌써 밥을 먹는 거야?",
  ui_story_5007_50070502_26_dialog_content = "미안해요. 전 물건 나르는 게 빠르거든요!",
  ui_story_5007_50070502_27_dialog_content = "미안해요... 저, 전 물건을 못 들어서요...",
  ui_story_5007_50070502_28_dialog_content = "미안... 이 수프는 방금 받은 거야. 아직 안 먹었어.",
  ui_story_5007_50070502_29_dialog_content = "아무튼, 아무튼, 다들 얼른 먹어보세요!",
  ui_story_5007_50070502_30_dialog_content = "이 옆에 있는 빈 깡통들... 내 기억에 일루미나의 통조림은\n항상 이상한 냄새가 났던 것 같은데 말이지...",
  ui_story_5007_50070502_31_dialog_content = "이번엔 좀 괜찮았으면 좋겠는걸.",
  ui_story_5007_50070502_32_dialog_content = "......",
  ui_story_5007_50070502_33_dialog_content = "엄청 맛있잖아?!",
  ui_story_5007_50070502_33X_dialog_content = "진하고 부드러운 수프에 연한 고기랑 감자의 풍부한 식감이 어우러져 있어...\n이렇게 맛있는 수프는 태어나서 처음이야!",
  ui_story_5007_50070502_34_dialog_content = "뭐야, 통조림 맛이 전혀 안 나는데?!",
  ui_story_5007_50070502_35_dialog_content = "바이스 넌 왜 그걸 가지고 놀라는 건데?",
  ui_story_5007_50070502_36_dialog_content = "미안... 전에 통조림으로 요리했을 때 맛이 없어서... 난 통조림 탓인 줄 알았거든.",
  ui_story_5007_50070502_37_dialog_content = "......",
  ui_story_5007_50070502_38_dialog_content = "(통조림은 잘못이 없다고 말하고 싶지만... 이럴 땐 그냥 조용히 넘어가는 게 좋겠지...)",
  ui_story_5007_50070502_39_dialog_content = "나도 연구해 볼래!",
  ui_story_5007_50070502_40_dialog_content = "감자 통조림, 쇠고기 통조림, 우유 통조림, 그리고 완두콩 통조림...",
  ui_story_5007_50070502_41_dialog_content = "토, 토, 통조림으로 만든 수프가 어째서 이렇게 완벽할 수 있는 건데?!",
  ui_story_5007_50070502_42_dialog_content = "대체 어떤 셰프가 만든 거야?!",
  ui_story_5007_50070502_43_dialog_content = "나도 배우게 해줘!",
  ui_story_5007_50070502_43X_dialog_content = "......",
  ui_story_5007_50070502_45_dialog_content = "바로 저분이에요!",
  ui_story_5007_50070502_46_dialog_content = "뭐?!",
  ui_story_5007_50070502_47_dialog_content = "맞아요! 저희가 물건을 옮기는 동안 이 수프를 준비해 주셨어요.",
  ui_story_5007_50070502_48_dialog_content = "정말 대단하다니까요!",
  ui_story_5007_50070502_49_dialog_content = "안녕하세요! 전 바이스라고 해요! 그람 님, 잠깐 이야기 좀 나눌 수 있을까요?",
  ui_story_5007_50070502_50_dialog_content = "난 장교가 아니니까 존칭은 필요 없다.",
  ui_story_5007_50070502_51_dialog_content = "아, 죄송해요... 혹시 어떤 일을 맡고 계신지 알 수 있을까요?\n전에 병참 업무를 담당한 적이 있으신 거죠?",
  ui_story_5007_50070502_52_dialog_content = "한때 그랬었지. 지금은 창고 관리자다.",
  ui_story_5007_50070502_53_dialog_content = "그람 씨처럼 강한 보급병은 처음 봤어요. 요리 실력도 전투력도 정말 대단하시네요!",
  ui_story_5007_50070502_54_dialog_content = "아! 전에 24호 지하성에서 어느 보급병의 이야기를 들은 적이 있었는데...\n한때 전설적인 군인이었다고... 그럼 설마...",
  ui_story_5007_50070502_55_dialog_content = "잡담은 여기까지 하지. 난 안시아한테 물어볼 게 있어서 왔다.",
  ui_story_5007_50070502_56_dialog_content = "네? 누가 절 불렀나요? 안시아가 갑니다!",
  ui_story_5007_50070502_57_dialog_content = "화물 중에 콜로서스의 입구에 들어갈 수 없는 커다란 상자가 있다.",
  ui_story_5007_50070502_58_dialog_content = "내용물만 콜로서스에 싣고 상자는 놔둬도 괜찮겠나?",
  ui_story_5007_50070502_59_dialog_content = "물론이죠. 괜찮아요! 상자는 필요 없어요! 밖에 버려두면 돼요!",
  ui_story_5007_50070502_60_dialog_content = "알겠다.",
  ui_story_5007_50070502_61_dialog_content = "아, 가버렸어... 아직 맛있는 수프 만드는 법도 못 물어봤는데...",
  ui_story_5007_50070502_62_dialog_content = "아니면 따라가서 일을 도와주고, 자연스럽게 말도 더 걸어보는 건 어때?",
  ui_story_5007_50070502_63_dialog_content = "바로 그거야! 이대로 포기할 순 없어. 지금 바로 갈게!",
  ui_story_5007_50070502_64_dialog_content = "바이스가 저렇게 적극적이라니 다행이네. 하긴, 이 수프... 정말...",
  ui_story_5007_50070502_65_dialog_content = "PlayerName, 넌 일루미나에 대해 어떻게 생각하지?",
  ui_story_5007_50070502_66_dialog_content = "맛있어요... 네? 잠깐만요. 왜 갑자기 그걸 묻는 건데요? 전 또 수프 얘기인 줄 알고...",
  ui_story_5007_50070502_67_dialog_content = "넌 지휘관으로서 좋은 재목이기 때문이다.",
  ui_story_5007_50070502_68_dialog_content = "네가 일루미나에 머물면서 더 많은 전투 지식을 배운다면...",
  ui_story_5007_50070502_69_dialog_content = "장차 큰 성과를 낼 수 있을 거다.",
  ui_story_5007_50070502_70_dialog_content = "무슨 말을 하시려는지는 알겠어요...",
  ui_story_5007_50070502_71_dialog_content = "하지만 전 그런 생각도 해본 적 없고, 원하지도 않아요. 미안해요.",
  ui_story_5007_50070502_72_dialog_content = "좋다. 단칼에 거절하는군. 그래도 난 네가 천천히 생각해 봤으면 한다.",
  ui_story_5007_50070502_73_dialog_content = "왜 저한테 그런 이야기를 하시는지는 잘 모르겠지만...",
  ui_story_5007_50070502_74_dialog_content = "브랜트 책임관님이 널 마음에 들어 하니까.",
  ui_story_5007_50070502_75_dialog_content = "크흠! 그, 그래도 호의는 감사히 받을게요.",
  ui_story_5007_50070502_76_dialog_content = "그래도... 저한테 그렇게 잘해주실 필요는 없어요.",
  ui_story_5007_50070502_77_dialog_content = "무슨 말이지? 왜 슬그머니 멀어지는 거냐?",
  ui_story_5007_50070502_78_dialog_content = "아, 아무것도 아니에요. 그냥 이해가 잘 안 돼서요... 왜 절 그렇게 신경 쓰시는 거죠?",
  ui_story_5007_50070502_79_dialog_content = "일루미나의 교관으로서, 난 일루미나의 미래를 생각하지 않을 수 없기 때문이다.",
  ui_story_5007_50070502_80_dialog_content = "그리고 네가 지휘하는 모습을 보면 전의 동료들과 함께 싸우던 때가 생각이 난다.",
  ui_story_5007_50070502_81_dialog_content = "그때 우리의 작전을 지휘했던 소대장도 아이테르였다.",
  ui_story_5007_50070502_82_dialog_content = "넌 그와 무척 비슷하다.",
  ui_story_5007_50070502_83_dialog_content = "잠깐만요, 아이테르가 일루미나에 합류해서 지휘관이 됐다는 말인가요?",
  ui_story_5007_50070502_84_dialog_content = "엄밀히 말하자면 그는 일루미나에 합류하지는 않았다.",
  ui_story_5007_50070502_85_dialog_content = "그는 우연히 지하성 근처를 지나던 중이었고, 우리가 암귀의 위협을 받고 있다는\n소식을 듣고 지원하러 왔었던 것이다.",
  ui_story_5007_50070502_86_dialog_content = "그는 자신도 전투에 참가하겠다고 강력히 요청했었지. 마치 너처럼 말이야.",
  ui_story_5007_50070502_87_dialog_content = "그 사람이 언제 왔었죠? 지금은 어디 있죠?\n혹시 그 사람이 헤븐즈 밸리의 일에 대해 말하진 않았나요?",
  ui_story_5007_50070502_88_dialog_content = "약 20년 전의 일이다. 그는 혼자서 이곳에 왔다.",
  ui_story_5007_50070502_89_dialog_content = "그 후 그는 다시 헤븐즈 밸리로 돌아갔고, 우린 다시는 그를 만나지 못했다...",
  ui_story_5007_50070502_90_dialog_content = "그런가요... 그럼 이미 세상을 떠났겠죠.",
  ui_story_5007_50070502_95_dialog_content = "어쩐지, 우릴 처음 봤을 때부터 그렇게 빨리 우릴 받아들인 이유가 있었군요.",
  ui_story_5007_50070502_96_dialog_content = "저한테 관심을 보이는 것도 당연한 일이겠네요. 이미 아이테르 친구가 있었으니까요.",
  ui_story_5007_50070502_97_dialog_content = "그것도 이유 중 하나지만, 우리에게 전력이 되어줄 사람이 필요하기 때문이기도 했다.",
  ui_story_5007_50070502_98_dialog_content = "음, 브랜트 씨가 절 마음에 들어 한다고 레비가 말했을 때 전 깜짝 놀랐거든요.\n다행히 제 오해였네요.",
  ui_story_5007_50070502_99_dialog_content = "방금 레비가 뭐라고 했다고?",
  ui_story_5007_50070502_100_dialog_content = "네? 브랜트 씨가 절 마음에 들어 한다고...",
  ui_story_5007_50070502_101_dialog_content = "...확실히 오해한 모양이군.",
  ui_story_5007_50070502_102_dialog_content = "레비 녀석은 가끔 말을 좀 이상하게 할 때가 있으니, 너무 진지하게 생각하지 마라.",
  ui_story_5007_50070502_103_dialog_content = "난 매일 하루에 열 번은 그 녀석한테 대체 무슨 생각을 하고 있냐고 묻곤 하지.",
  ui_story_5007_50070502_104_dialog_content = "뭐, 한 가지 덧붙이자면...",
  ui_story_5007_50070502_105_dialog_content = "당시 우리 <color=#FFB400>용사 별동대</color>는 네 소대보다 월등히 강했다.",
  ui_story_5007_50070502_106_dialog_content = "네? 갑자기 왜 저희랑 비교를 하는 거죠...",
  ui_story_5007_50070502_107_dialog_content = "신경 쓰지 마라. 노병이란 항상 호승심을 품기 마련이니까.",
  ui_story_5007_50070502_108_dialog_content = "짧은 시간이었지만 널 만나서 정말 기뻤다.",
  ui_story_5007_50070502_109_dialog_content = "저도 그래요.",
  ui_story_5007_50070502_110_dialog_content = "『찾았습니다...』",
  ui_story_5007_50070502_111_dialog_content = "『드디어 찾았습니다.』",
  ui_story_5007_50070502_112_dialog_content = "『어머니의 의지를 따르겠습니다.』",
  ui_story_5007_50070502_113_dialog_content = "『우리에게 주신 이 힘으로.』",
  ui_story_5007_50070502_114_dialog_content = "『명령을 완수할 것입니다.』",
  ui_story_5007_50070502_115_dialog_content = "『전진해라!』",
  ui_story_5007_50070502_116_dialog_content = "휴, 나도 전선으로 지원을 가고 싶어.",
  ui_story_5007_50070502_117_dialog_content = "갑자기 무슨 소리야?",
  ui_story_5007_50070502_118_dialog_content = "지방군이 동원됐잖아. 감시대의 장교님들도 모자라서 옆 숙소의 신병까지 다 데려갔다고.",
  ui_story_5007_50070502_119_dialog_content = "근데 왜 나만 여기 있는 거야!",
  ui_story_5007_50070502_120_dialog_content = "그렇게 방어선에 가서 싸우고 싶어?",
  ui_story_5007_50070502_121_dialog_content = "당연하지. 전공을 세울 절호의 기회잖아.",
  ui_story_5007_50070502_122_dialog_content = "여기서 보초만 서고 있으면 언제 강해질 수 있겠어?",
  ui_story_5007_50070502_123_dialog_content = "그것보다 중요한 건 일루미나를 위해 얼마나 공헌할 수 있는지 아니겠어?",
  ui_story_5007_50070502_125_dialog_content = "어이, 저기 뭐가 있는데?",
  ui_story_5007_50070502_126_dialog_content = "뭐가? 노란 모래먼지 말고... 아무것도 안 보이는데?",
  ui_story_5007_50070502_127_dialog_content = "방금 망원경으로 봤을 때는 검은 점이 없었는데...",
  ui_story_5007_50070502_128_dialog_content = "검은 점? 그런 건 보통 그냥 떠돌아다니는 암귀잖아? 뭐 대단한 거라고.",
  ui_story_5007_50070502_128X1_dialog_content = "근데 저 멀리 있는 모래먼지... 설마 모래폭풍이 또 부는 건가?",
  ui_story_5007_50070502_131_dialog_content = "역시 선임 책임관님한테 보고드리는 게 좋겠어.",
  ui_story_5007_50070502_132_dialog_content = "<color=#e8d9bb>삐익──! 삐익──!</color>",
  ui_story_5007_50070502_133_dialog_content = "음? 이건 무슨 소리죠?",
  ui_story_5007_50070502_135_dialog_content = "긴급 집합 신호다! 지하성 안에서 보낸 거다!",
  ui_story_5007_50070502_136_dialog_content = "PlayerName, 감응 능력을 사용하여 최대한 먼 곳을 살펴봐라!",
  ui_story_5007_50070502_137_dialog_content = "알겠어요. 한번 해볼게요.",
  ui_story_5007_50070502_138_dialog_content = "이건...",
  ui_story_5007_50070502_139_dialog_content = "암귀예요.",
  ui_story_5007_50070502_140_dialog_content = "...암귀!",
  ui_story_5007_50070502_141_dialog_content = "사방이 암귀예요!",
  ui_story_5007_50070502_142_dialog_content = "엄청난 수의 암귀가 지금 24호 지하성으로 몰려오고 있어요!",
  ui_story_5007_50070502_144_dialog_content = "이런, 암귀가 대규모 침공을 시작했다면 방어선이 뚫렸을 가능성이 높다.",
  ui_story_5007_50070502_145_dialog_content = "대규모 침공? 그럼 어떡하죠? 성안의 군대는 싸울 준비가 돼 있나요?",
  ui_story_5007_50070502_146_dialog_content = "24호 지하성엔 병력이 어느 정도 있죠?",
  ui_story_5007_50070502_147_dialog_content = "24호 지하성은 병력이 적었던 거로 기억해. 3천? 아니, 2천 정도였나?",
  ui_story_5007_50070502_148_dialog_content = "지금 24호 지하성에는 군대가 없다.",
  ui_story_5007_50070502_149_dialog_content = "군대가 없다니 그게 무슨 말이죠?!",
  ui_story_5007_50070502_150_dialog_content = "군대는 모두 방어선의 지원에 나섰고, 남은 건 경비대와 신병, 그리고 비전투인원뿐이다.",
  ui_story_5007_50070502_151_dialog_content = "PlayerName, 네 콜로서스로 지하성 내 부상자와 아이들을 대피시켜야 한다!",
  ui_story_5007_50070502_152_dialog_content = "가장 가까운 안전한 지하성을 찾아라!",
  ui_story_5007_50070502_153_dialog_content = "알겠어요!",
  ui_story_5007_50070502_154_dialog_content = "하지만 네 콜로서스로는 부상자를 한 번에 태울 수 없을 거다.\n모두를 피난시키려면 적어도 두 번은 왕복해야 되겠지.",
  ui_story_5007_50070502_155_dialog_content = "비록 이기진 못하더라도, 반드시 암귀의 공격을 막고 철수할 시간을 벌어야 한다.",
  ui_story_5007_50070502_156_dialog_content = "우선 지하성으로 돌아간다! 철수 명령을 내리고 계획을 세워야 한다!",
  ui_story_5007_50070601_1_dialog_content = "이게 대체 어떻게 된 거야?",
  ui_story_5007_50070601_2_dialog_content = "어째서 암귀가 저렇게 잔뜩 몰려오는 건데!",
  ui_story_5007_50070601_3_dialog_content = "설마... 우리 군의 방어선이 무너진 건가?!",
  ui_story_5007_50070601_4_dialog_content = "모르겠어... 하지만 이 수는... 너무 많아...",
  ui_story_5007_50070601_8_dialog_content = "어느 정도지?",
  ui_story_5007_50070601_9_dialog_content = "마, 마치 파도가 몰아치는 것 같습니다! 우릴 통째로 삼켜버릴 만한 수입니다!",
  ui_story_5007_50070601_10_dialog_content = "무, 무서워하지 마. 우리에겐 성벽이 있잖아! 성벽이 우릴 지켜줄 거야!",
  ui_story_5007_50070601_11_dialog_content = "틀렸네, 젊은이.",
  ui_story_5007_50070601_12_dialog_content = "성벽은 우리가 지키는 것이다.",
  ui_story_5007_50070601_13_dialog_content = "하지만 책임관님... 저희가 어떻게 지켜내죠?",
  ui_story_5007_50070601_14_dialog_content = "암귀 놈들은 아직 공격 범위에 들어오지 않았다. 기다려라.",
  ui_story_5007_50070601_15_dialog_content = "부상자나 아이들이 콜로서스를 타고 대피한 뒤에 싸울 수 있다면 좋겠는데 말이야.",
  ui_story_5007_50070601_16_dialog_content = "부상자 여러분! 이쪽이에요!",
  ui_story_5007_50070601_18_dialog_content = "줄을 따라 플랫폼에 올라와서 콜로서스에 탑승하세요! 밀지 마시구요!",
  ui_story_5007_50070601_19_dialog_content = "안시아, 이리 와 봐. 할 말 있어.",
  ui_story_5007_50070601_20_dialog_content = "아, 깜짝이야... 갑자기 나타나서 놀랐잖아요.",
  ui_story_5007_50070601_21_dialog_content = "왜 반대하지 않은 거야?",
  ui_story_5007_50070601_22_dialog_content = "뭘 반대해요?",
  ui_story_5007_50070601_23_dialog_content = "저들이 콜로서스를 쓰는 거 말이야. 화물 운송은 포기할 셈이야?",
  ui_story_5007_50070601_24_dialog_content = "모두의 생명이 더 중요하잖아요. 게다가 브랜트 님이랑도 따로 이야기를 끝냈어요.",
  ui_story_5007_50070601_25_dialog_content = "암귀들이 쳐들어오면 23호 지하성이 함락될 수도 있대요.",
  ui_story_5007_50070601_26_dialog_content = "그럼 화물 같은 건 의미도 없게 돼버릴 거예요.",
  ui_story_5007_50070601_27_dialog_content = "사실 저도 잘 알고 있어요.",
  ui_story_5007_50070601_28_dialog_content = "애초에 예비 부품은 중요한 게 아니었을지도 몰라요.\n지금까지 전 그저 제 직위를 지킬 생각뿐이었던 거죠.",
  ui_story_5007_50070601_29_dialog_content = "전에 당신이 했던 말이 맞아요. 그래서 전 반성했어요!",
  ui_story_5007_50070601_30_dialog_content = "화물 수송을 포기하고 이곳 사람들의 생명을 지킨다. 그게 네 결정이구나.",
  ui_story_5007_50070601_31_dialog_content = "맞아요. 그게 제 결정이에요. 저희도 이곳에 남아서 암귀를 막기로 해요.\n임무 문제는 제가 책임지고 해명할게요.",
  ui_story_5007_50070601_32_dialog_content = "그럼 이 화물들은 어떻게 할 건지 생각했어?",
  ui_story_5007_50070601_33_dialog_content = "그게...",
  ui_story_5007_50070601_34_dialog_content = "넌 미덥지 못한 녀석이지만, 그래도 이 화물에 대해선 책임을 져야만 해.",
  ui_story_5007_50070601_35_dialog_content = "우리가 남아서 전투를 돕길 바란다면, 화물의 안전은 네가 보장해.",
  ui_story_5007_50070601_36_dialog_content = "안전한 지하성을 찾아서 물건을 두고, 넌 돌아오지 마.",
  ui_story_5007_50070601_37_dialog_content = "어차피 돌아와 봤자 방해만 될 뿐이니까.",
  ui_story_5007_50070601_38_dialog_content = "내가 하고 싶은 말은 이게 다야. 그럼 안녕.",
  ui_story_5007_50070601_39_dialog_content = "다, 당신 말이 맞아요... 알겠어요.",
  ui_story_5007_50070601_40_dialog_content = "브랜트 씨, 24호 지하성을 어떻게 지킬 생각이죠?",
  ui_story_5007_50070601_41_dialog_content = "성에서 출격해 암귀와 맞설 특별 작전조가 필요하다.",
  ui_story_5007_50070601_42_dialog_content = "그래서 너희들의 도움이 필요해.",
  ui_story_5007_50070601_43_dialog_content = "좋아요! 하지만 콜로서스 조종에는 조종사가 필요하니까, 저랑 카렌이 남을게요.",
  ui_story_5007_50070601_44_dialog_content = "아니, 콜로서스에는 자동 조종 시스템이 있어.\n바이스가 콜로서스에서 보조 조작만 해주면 돼. 내가 남을게.",
  ui_story_5007_50070601_45_dialog_content = "PlayerName, 전장에 남을 생각이야?",
  ui_story_5007_50070601_46_dialog_content = "응. 브랜트 씨가 이런 상황에선 내가 감지 장치보다 더 유용하다고 하셨거든.",
  ui_story_5007_50070601_47_dialog_content = "나도 그렇게 생각하고 말이야.",
  ui_story_5007_50070601_48_dialog_content = "저 아가씨는 지금 네 안전을 걱정하고 있는 거다. 나도 넌 여기 남지 않는 게 좋겠다고 생각한다.",
  ui_story_5007_50070601_49_dialog_content = "알고 있어요. 하지만 저도 두 사람을 걱정하니까 하는 얘기예요.",
  ui_story_5007_50070601_50_dialog_content = "게다가 전 모두의 전투를 지휘할 수 있으니까. 분명히 도움이 될 거예요.",
  ui_story_5007_50070601_51_dialog_content = "물론 내 입장에선 PlayerName 네가 남아주는 게 좋다.",
  ui_story_5007_50070601_52_dialog_content = "그렇다면 지휘관으로서, 난 전세를 위해 네가 이곳에 남아주었으면 한다!",
  ui_story_5007_50070601_53_dialog_content = "알겠어요!",
  ui_story_5007_50070601_54_dialog_content = "바이스, 걱정하지 마! 난 괜찮을 거야!",
  ui_story_5007_50070601_55_dialog_content = "...알았어, 네가 그렇게 말한다면야.",
  ui_story_5007_50070601_56_dialog_content = "카렌, 그럼 조종사는 너한테 부탁할게. 너희라면 분명히 24호 지하성을 지켜낼 수 있을 거야!",
  ui_story_5007_50070601_57_dialog_content = "응, 나한테 맡겨.",
  ui_story_5007_50070601_58_dialog_content = "좋다! 그럼 남아서 싸울 자들은 지하성 입구에서 집결한다!",
  ui_story_5007_50070601_59_dialog_content = "잘 들어라! 대규모의 암귀가 지금 코앞까지 몰려왔다!",
  ui_story_5007_50070601_60_dialog_content = "이번 작전 목표는 암귀가 지하성에 침입하는 것을 막고,\n콜로서스의 순조로운 철수를 보장하는 것이다!",
  ui_story_5007_50070601_61_dialog_content = "바이스와 안시아는 콜로서스를 타고 떠나고, 나머지 사람들은 작전에 참가한다.",
  ui_story_5007_50070601_62_dialog_content = "작전에 참가하는 건 상관없어요. 하지만 적어도 승산이 있어야죠.",
  ui_story_5007_50070601_63_dialog_content = "승산? 물론 있지.",
  ui_story_5007_50070601_64_dialog_content = "1분만 기다려라. 답이 들려올 테니까.",
  ui_story_5007_50070601_65_dialog_content = "명령을 기다려라!",
  ui_story_5007_50070601_66_dialog_content = "전원 준비!",
  ui_story_5007_50070601_67_dialog_content = "발사!",
  ui_story_5007_50070601_68_dialog_content = "<color=#e8d9bb>펑! 펑! 퍼엉──!</color>",
  ui_story_5007_50070601_69_dialog_content = "포격이다!",
  ui_story_5007_50070601_70_dialog_content = "24호 지하성에도 수비 병력이 남아 있었군요!",
  ui_story_5007_50070601_71_dialog_content = "그렇다. 하지만 수가 많지는 않다. 대부분의 탄약은 방어선으로 보내졌으니까.",
  ui_story_5007_50070601_72_dialog_content = "대신 이 지하성에는 노련한 선임 책임관이 있다.\n남은 화력을 최대한으로 활용할 수 있을 거다.",
  ui_story_5007_50070601_73_dialog_content = "최선의 전개는 포격으로 암귀의 대열을 어지럽히는 것이다.",
  ui_story_5007_50070601_74_dialog_content = "그 뒤에 놈들을 각개격파하는 거지!",
  ui_story_5007_50070601_75_dialog_content = "보고드립니다! 첫 암귀 부대가 곧 수송 거점에 도달합니다!\n예상 도달 시간은 3분 후입니다!",
  ui_story_5007_50070601_76_dialog_content = "모든 작전 병력이 집합을 완료했습니다!",
  ui_story_5007_50070601_77_dialog_content = "임시 편성한 신병 소대 5개, 혼성 소대 3개 모두 고참병이 인솔합니다!",
  ui_story_5007_50070601_78_dialog_content = "장비와 탄약의 지급도 완료했습니다!",
  ui_story_5007_50070601_79_dialog_content = "좋아! 문을 열 준비를 해라!",
  ui_story_5007_50070601_80_dialog_content = "여명의 빛을 위하여!",
  ui_story_5007_50070601_81_dialog_content = "모두 정신 바짝 차리고 전투에 임한다!",
  ui_story_5007_50070602_1_dialog_content = "『망설이지 마라.』",
  ui_story_5007_50070602_2_dialog_content = "『전진해라.』",
  ui_story_5007_50070602_3_dialog_content = "『오직 전진할 뿐이다.』",
  ui_story_5007_50070602_4_dialog_content = "『우리에겐 어머니께서 주신 힘이 있다.』",
  ui_story_5007_50070602_5_dialog_content = "『그 무엇과도 비할 수 없는 막강한 힘.』",
  ui_story_5007_50070602_6_dialog_content = "『내 명령에 따르라.』",
  ui_story_5007_50070602_7_dialog_content = "『전진해라.』",
  ui_story_5007_50070602_8_dialog_content = "『그 장소에 도착해서...』",
  ui_story_5007_50070602_9_dialog_content = "『폭발해라!』",
  ui_story_5007_50070602_10_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5007_50070602_11_dialog_content = "방금 저 폭발음은 뭐냐?",
  ui_story_5007_50070602_12_dialog_content = "보고드립니다!",
  ui_story_5007_50070602_13_dialog_content = "갑자기 어디선가 암귀가 나타나 성벽을 공격했습니다!",
  ui_story_5007_50070602_14_dialog_content = "현재 성벽 아래의 암귀를 공격하고 있습니다! 아직까진 통제 가능한 상황입니다!",
  ui_story_5007_50070602_15_dialog_content = "어디선가 나타나? 지금 장난하는 거냐?!",
  ui_story_5007_50070602_16_dialog_content = "모, 모래먼지가 너무 심해서 관측이 불가능합니다!",
  ui_story_5007_50070602_17_dialog_content = "됐다! 성벽의 상황은?",
  ui_story_5007_50070602_18_dialog_content = "아직 버틸 수 있습니다!",
  ui_story_5007_50070602_19_dialog_content = "PlayerName! 근처의 상황을 감응할 수 있겠나?",
  ui_story_5007_50070602_23_dialog_content = "암귀가...",
  ui_story_5007_50070602_24_dialog_content = "암귀가 지하성의 후방을 공격하려고 해요!",
  ui_story_5007_50070602_25_dialog_content = "뭐야... 다크매터가 하늘에도?!",
  ui_story_5007_50070602_26_dialog_content = "뭐라고?!",
  ui_story_5007_50070602_27_dialog_content = "먼 곳의 공중에 암귀가 나타난 게 느껴져요!",
  ui_story_5007_50070602_28_dialog_content = "엄청나게 강한 녀석이에요...",
  ui_story_5007_50070602_29_dialog_content = "여기서도 느껴질 정도라구요!",
  ui_story_5007_50070602_30_dialog_content = "아무래도 고위 암귀인 모양이군.",
  ui_story_5007_50070602_31_dialog_content = "녀석이 오기 전에 콜로서스가 출발해서 다행이야.",
  ui_story_5007_50070602_32_dialog_content = "하지만 녀석이 지하성 상공에서 공격한다면 큰일이다.",
  ui_story_5007_50070602_33_dialog_content = "상공에서의 공격이라면 막아낼 수 없을 거다.",
  ui_story_5007_50070602_34_dialog_content = "PlayerName, 카렌, 그람, 레비. 너희들은 즉시 출격해 고위 암귀의 부대를 막아라!",
  ui_story_5007_50070602_35_dialog_content = "지하성의 선임 책임관이라면 그 고위 암귀를 격추시킬 수 있을 거다!",
  ui_story_5007_50070602_36_dialog_content = "고위 암귀가 떨어지면 신속히 놈을 처치해라!",
  ui_story_5007_50070602_40_dialog_content = "PlayerName, 우리에게 승산이 있다고 생각하나?",
  ui_story_5007_50070602_41_dialog_content = "솔직히 말해서... 잘 모르겠어요... 그 암귀의 다크매터가 너무 강해서 몸이 불편해요.",
  ui_story_5007_50070602_42_dialog_content = "너무 부담 갖지 마라. 이길 수 없을 것 같다면 즉시 퇴각해라.",
  ui_story_5007_50070602_43_dialog_content = "놈을 상대할 방법은 아직 많으니까!",
  ui_story_5007_50070602_44_dialog_content = "그래도 전 꼭 임무를 완수하고 싶어요!",
  ui_story_5007_50070602_45_dialog_content = "그래. 그런 투지가 있어야지.",
  ui_story_5007_50070602_47_dialog_content = "레비, 절대 잊지 마라. 반드시 <color=#FFB400>PlayerName의 명령</color>을 따라야만 한다. 멋대로 나서지 마라.",
  ui_story_5007_50070602_48_dialog_content = "알겠어!",
  ui_story_5007_50070602_49_dialog_content = "좋다. 널 믿으마.",
  ui_story_5007_50070602_50_dialog_content = "PlayerName, 전세를 판단하기 어려울 땐 그람에게 물어라.",
  ui_story_5007_50070602_51_dialog_content = "그람은 백전노장이고 판단력도 나 못지않다.",
  ui_story_5007_50070602_52_dialog_content = "네, 알겠어요.",
  ui_story_5007_50070602_53_dialog_content = "그람! 전장에 나서는 건 오랜만이겠지.",
  ui_story_5007_50070602_54_dialog_content = "하지만 전장을 극복하는 최고의 방법은 전장을 마주하는 것 아니겠나!",
  ui_story_5007_50070602_55_dialog_content = "이런 마당에 나한테 잔소리를 하는 건가?",
  ui_story_5007_50070602_56_dialog_content = "나 혼자만 전장에서 고생할 순 없으니 말이야!",
  ui_story_5007_50070602_57_dialog_content = "PlayerName, 그리고 레비, 두 사람을 부탁한다!",
  ui_story_5007_50070602_58_dialog_content = "그래, 알겠다고. 안심해라.",
  ui_story_5007_50070602_59_dialog_content = "브랜트 님, 다음 암귀 무리가 약 5분 뒤에 수송 거점에 도달합니다!",
  ui_story_5007_50070602_60_dialog_content = "암귀들의 목표는 수송 거점입니다. 다음 명령을 하달해 주십시오!",
  ui_story_5007_50070602_A1_dialog_content = "좋다. 모두의 임무를 다시 한번 설명하겠다.",
  ui_story_5007_50070602_A2_dialog_content = "PlayerName, 그리고 그람은 소대와 함께 우회하여 고위 암귀를 직접 노린다.",
  ui_story_5007_50070602_A3_dialog_content = "나머지는 나와 함께 수송 거점 안에서 전선의 전장을 방어한다.",
  ui_story_5007_50070602_61_dialog_content = "비다!",
  ui_story_5007_50070602_62_dialog_content = "앗! 네!",
  ui_story_5007_50070602_63_dialog_content = "적합한 지뢰 매설 위치는 알고 있겠지?",
  ui_story_5007_50070602_64_dialog_content = "네... 자, 잘 알고 있어요.",
  ui_story_5007_50070602_65_dialog_content = "떨지 마라! 이곳은 전쟁터다! 겁에 질리는 버릇은 고쳐라!",
  ui_story_5007_50070602_66_dialog_content = "네, 네! 반드시... 열심히, 고치겠습니다...",
  ui_story_5007_50070602_67_dialog_content = "됐다. 어서 가서 지뢰를 준비해라!",
  ui_story_5007_50070602_68_dialog_content = "지뢰가 부족하면 7번 창고로 가서 챙겨라. 아직 몇 상자 남아 있을 거다!",
  ui_story_5007_50070602_69_dialog_content = "병사들을 데리고 즉시 출발해라!",
  ui_story_5007_50070602_70_dialog_content = "알루라 양! 레비가 없는 상황에선 자네가 이곳에서 가장 움직임이 빠른 사람일 거다.",
  ui_story_5007_50070602_71_dialog_content = "자네는 지뢰를 매설한 장소까지 암귀를 유인해 주었으면 한다!",
  ui_story_5007_50070602_72_dialog_content = "그런 의뢰는 수락하지 않겠어요. 너무 위험하잖아요.",
  ui_story_5007_50070602_73_dialog_content = "일루미나를 위한 전쟁에 참전하는 용병에겐 상당한 보수가 지급될 거다!",
  ui_story_5007_50070602_74_dialog_content = "이번만이에요.",
  ui_story_5007_50070602_75_dialog_content = "추가 계약서 작성도 잊지 마세요.",
  ui_story_5007_50070701_A1_dialog_content = "브랜트 씨가 우리한테 측면에서 길을 뚫고 고위 암귀를 공격하라고 했지만...",
  ui_story_5007_50070701_A2_dialog_content = "지하성엔 출구가 하나뿐이잖아요. 수송 거점이랑 연결된 곳 말이에요.",
  ui_story_5007_50070701_A3_dialog_content = "수송 거점에도 출구가 하나뿐이니까, 밖으로 나가면 곧바로 암귀 무리랑 마주칠 텐데...",
  ui_story_5007_50070701_A4_dialog_content = "대체 어떻게 피해서 가라는 거죠?!",
  ui_story_5007_50070701_A5_dialog_content = "나한테 방법이 있다. 일단 지하성으로 돌아간다.",
  ui_story_5007_50070701_1_dialog_content = "보고드립니다! 모든 준비를 마쳤습니다!",
  ui_story_5007_50070701_2_dialog_content = "좋다! 놈이 더 가까워지면 몇 발 먹여줘라!",
  ui_story_5007_50070701_3_dialog_content = "놈에게 일루미나의 포탄 맛을 보여주는 거다!",
  ui_story_5007_50070701_4_dialog_content = "책임관님! 그냥 대포로 녀석을 한 번에 쓰러트릴 순 없나요?",
  ui_story_5007_50070701_5_dialog_content = "정말 순진하군. 아이테르 꼬마.",
  ui_story_5007_50070701_6_dialog_content = "이런 평범한 포탄으로는 고위 암귀에게 큰 타격을 주지 못할 거다.",
  ui_story_5007_50070701_7_dialog_content = "하지만 방금 내가 망원경으로 놈을 살펴봤지...",
  ui_story_5007_50070701_8_dialog_content = "놈은 나방 같은 날개가 달렸으니, 포격으로 그걸 찢어버릴 순 있을 거다!",
  ui_story_5007_50070701_9_dialog_content = "PlayerName, 암귀가 적은 방향을 알려줘라.",
  ui_story_5007_50070701_10_dialog_content = "음... 지하성 동쪽이 상대적으로 수가 적어요.",
  ui_story_5007_50070701_11_dialog_content = "레비, 동쪽 성벽에 가서 밧줄을 준비해라.",
  ui_story_5007_50070701_12_dialog_content = "지휘관은 PlayerName인걸. 난 PlayerName 말만 들을 거야.",
  ui_story_5007_50070701_13_dialog_content = "아, 난 상황을 잘 모르니까... 레비, 그람 씨 말대로 해줘.",
  ui_story_5007_50070701_14_dialog_content = "알겠어. 네가 그렇게 말한다면 지금 바로 갈게.",
  ui_story_5007_50070701_15_dialog_content = "근데... 밧줄로 뭘 하려는 거죠?",
  ui_story_5007_50070701_16_dialog_content = "우린 동쪽 성벽에서 뛰어내릴 거다.",
  ui_story_5007_50070701_17_dialog_content = "뛰어내리는 거군요.",
  ui_story_5007_50070701_18_dialog_content = "네?",
  ui_story_5007_50070701_19_dialog_content = "성벽에서 뛰어내린다고요?!",
  ui_story_5007_50070701_20_dialog_content = "밧줄 준비 다 했어. 한쪽 끝을 잘 묶어놨어.",
  ui_story_5007_50070701_21_dialog_content = "약한 녀석은 밧줄을 써. 난 강하니까 필요 없어!",
  ui_story_5007_50070701_22_dialog_content = "아, 아니, 잠깐만, 아무리 봐도 길이가 부족하잖아!",
  ui_story_5007_50070701_23_dialog_content = "PlayerName, 꾸물대지 말고 한번 해봐.",
  ui_story_5007_50070701_24_dialog_content = "난 그냥 아이테르야... 너희 같은 오로리안이랑 똑같이 생각하지 마!",
  ui_story_5007_50070701_25_dialog_content = "내 신체 능력은 약해 빠졌다고!",
  ui_story_5007_50070701_26_dialog_content = "전에 내던져져서 모래사장에 떨어졌을 때도 죽을 뻔했다니까...",
  ui_story_5007_50070701_27_dialog_content = "근데 이번엔 이렇게 높은 성벽 위에서 뛰어내리라고?",
  ui_story_5007_50070701_28_dialog_content = "나머지는 밧줄을 사용해 낙하 속도를 조절해라.",
  ui_story_5007_50070701_29_dialog_content = "PlayerName, 넌 나와 함께 간다.",
  ui_story_5007_50070701_30_dialog_content = "네?",
  ui_story_5007_50070701_31_dialog_content = "네 안전은 내가 지켜주마.",
  ui_story_5007_50070701_32_dialog_content = "네, 뭐, 뭔데요?! 갑자기 왜 절 잡는 거죠?!",
  ui_story_5007_50070701_33_dialog_content = "한 손으로 조종사를 들다니, 꼭 병아리 같네.",
  ui_story_5007_50070701_34_dialog_content = "뭐, 뭘 하려는 거죠?",
  ui_story_5007_50070701_35_dialog_content = "내가 널 잡고 뛰어내리면 안전할 거다!",
  ui_story_5007_50070701_36_dialog_content = "네? 이대로 뛰어내린다고요?!",
  ui_story_5007_50070701_37_dialog_content = "아, 아무리 그래도 이건 아니잖아아아아아──!",
  ui_story_5007_50070701_38_dialog_content = "<color=#e8d9bb>펑! 펑! 퍼엉──!</color>",
  ui_story_5007_50070701_39_dialog_content = "보고드립니다!",
  ui_story_5007_50070701_40_dialog_content = "거대한 비행 암귀를 격추시켰습니다!",
  ui_story_5007_50070701_41_dialog_content = "잘했다!",
  ui_story_5007_50070701_42_dialog_content = "생각했던 것보다 훨씬 약한 녀석인 모양이군.",
  ui_story_5007_50070701_43_dialog_content = "이번 공격만 버텨라!",
  ui_story_5007_50070701_44_dialog_content = "이번 공격을 버티면 내가 배식에 닭다리를 하나씩 추가해 주마!",
  ui_story_5007_50070701_45_dialog_content = "탄약은 얼마나 남았지?",
  ui_story_5007_50070701_46_dialog_content = "이제 절반도 안 남았습니다!",
  ui_story_5007_50070701_47_dialog_content = "예상했던 것보다 소비가 많군...",
  ui_story_5007_50070701_48_dialog_content = "포병의 절반을 소대로 편성한다! 소총을 챙겨 브랜트 쪽으로 집결하라!",
  ui_story_5007_50070701_49_dialog_content = "예!",
  ui_story_5007_50070701_50_dialog_content = "나머지는 저 아이테르 꼬마한테 맡기는 수밖에.",
  ui_story_5007_50070701_A6_dialog_content = "기, 기절할 뻔했잖아요... 이런 스릴은 진짜 처음이네요...",
  ui_story_5007_50070701_A7_dialog_content = "절 붙잡고 뛰어내린다길래 어디 돌에 묶어서 던지는 거랑 다를 게 없을 줄 알았죠...",
  ui_story_5007_50070701_A8_dialog_content = "의외로... 안전하네요.",
  ui_story_5007_50070701_A9_dialog_content = "멀쩡하면 됐다. 떨지 마라.",
  ui_story_5007_50070701_51_dialog_content = "감응 능력으로 그 고위 암귀가 어디에 있는지 알아낼 수 있겠나?",
  ui_story_5007_50070701_52_dialog_content = "네. 추락한 곳을 찾았어요. 저쪽 방향이에요.",
  ui_story_5007_50070701_53_dialog_content = "전방에 소규모의 암귀 무리가 있어요. 빠르게 해치우죠.",
  ui_story_5007_50070701_54_dialog_content = "알겠어! 명령대로 지금 바로 갈게!",
  ui_story_5007_50070702_1_dialog_content = "좋아. 모래바람에 숨어들어 전진한다.",
  ui_story_5007_50070702_2_dialog_content = "난 PlayerName 명령밖에 안 들을 거라고...",
  ui_story_5007_50070702_3_dialog_content = "레비, 우리 이번엔 그람 씨 말을 듣자. 알겠지?",
  ui_story_5007_50070702_4_dialog_content = "알겠어.",
  ui_story_5007_50070702_5_dialog_content = "그오오오...",
  ui_story_5007_50070702_6_dialog_content = "고위 암귀가 보여!",
  ui_story_5007_50070702_7_dialog_content = "레비 출격!",
  ui_story_5007_50070702_8_dialog_content = "캬아악──!",
  ui_story_5007_50070702_9_dialog_content = "저 암귀... 머리가 날아갔는데도 움직이는 거야?!",
  ui_story_5007_50070702_10_dialog_content = "정말 징그럽네.",
  ui_story_5007_50070702_11_dialog_content = "근데 머리 말고는... <color=#FFB400>아무 피해도 입지 않은 것 같은데</color>?",
  ui_story_5007_50070702_12_dialog_content = "레비, 따라와라. 놈을 해치운다.",
  ui_story_5007_50070702_13_dialog_content = "말 안 해도 알거든!",
  ui_story_5007_50070702_14_dialog_content = "잠깐만! 저 암귀... 뭔가 이상해요! 다크매터가 <color=#FFB400>급속도로 증가</color>하고 있어요!",
  ui_story_5007_50070702_15_dialog_content = "크오오오──!",
  ui_story_5007_50070702_16_dialog_content = "공격을 조심해! 거리를 벌려라!",
  ui_story_5007_50070702_17_dialog_content = "크윽...",
  ui_story_5007_50070702_18_dialog_content = "레비, 맞은 거냐?",
  ui_story_5007_50070702_19_dialog_content = "안 맞았거든! 그냥 스친 것뿐이라구!",
  ui_story_5007_50070702_20_dialog_content = "뭐지...이 암귀 말고도 뭔가 이상한 느낌이 들어...",
  ui_story_5007_50070702_21_dialog_content = "저 고위 암귀 밑에... 뭔가 있는 것 같은데?",
  ui_story_5007_50070702_22_dialog_content = "땅 밑으로 암귀가 접근하고 있어! 모두 조심해!",
  ui_story_5007_50070702_23_dialog_content = "땅 밑에 암귀가 있다고?!",
  ui_story_5007_50070702_24_dialog_content = "야! 땅에서 암귀가 나왔어!",
  ui_story_5007_50070702_25_dialog_content = "조심해라! 그 녀석은 자폭할 거다──!",
  ui_story_5007_50070702_26_dialog_content = "PlayerName!",
  ui_story_5007_50070702_27_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5007_50070801_1_dialog_content = "브랜트 님!",
  ui_story_5007_50070801_2_dialog_content = "거대한 우두머리급 암귀가 모래먼지를 뚫고 수송 거점으로 접근하고 있습니다!",
  ui_story_5007_50070801_3_dialog_content = "저희 화력으로는 막을 수 없습니다!",
  ui_story_5007_50070801_4_dialog_content = "선임 책임관님께서 브랜트 님께 보고하라고 하셨습니다.\n저 암귀는 그람 님과 아이테르 일행이 있는 곳에서 날아왔습니다.",
  ui_story_5007_50070801_5_dialog_content = "2분 전에 그곳에서 거대한 폭발이 있었습니다. 아무래도...",
  ui_story_5007_50070801_6_dialog_content = "돌아가서 보고하라. 24호 지하성 방어 작전은 아직 끝나지 않았다.",
  ui_story_5007_50070801_7_dialog_content = "저 암귀를 격추시켜 날지 못하게 할 수만 있다면 우리에게도 아직 승산이 있다.",
  ui_story_5007_50070801_8_dialog_content = "예!",
  ui_story_5007_50070801_9_dialog_content = "PlayerName, 그람...",
  ui_story_5007_50070801_10_dialog_content = "폭발에 휘말려 죽은 건가요?",
  ui_story_5007_50070801_11_dialog_content = "전장에서 죽음이란 흔한 일이다.\n하지만 난 그들이 무사할 거라고 믿는다.",
  ui_story_5007_50070801_12_dialog_content = "아무 근거도 없는데 그걸 어떻게 믿죠?",
  ui_story_5007_50070801_13_dialog_content = "내가 아는 그들이라면 믿을 수 있다.",
  ui_story_5007_50070801_14_dialog_content = "그래가지고는 아무 설득력도 없는데요...",
  ui_story_5007_50070801_15_dialog_content = "중요한 건 지금 거대한 비행형 암귀가 곧 지하성에 온다는 거예요.\n육안으로도 보일 정도라고요.",
  ui_story_5007_50070801_16_dialog_content = "저 녀석은 아무리 봐도 우두머리급 암귀네요. 이래가지곤 승산은 없어요.",
  ui_story_5007_50070801_17_dialog_content = "이제 어떻게 할 생각이죠?",
  ui_story_5007_50070801_18_dialog_content = "<color=#e8d9bb>펑! 펑! 퍼엉──!</color>",
  ui_story_5007_50070801_19_dialog_content = "이 대포 소리가 들리나?",
  ui_story_5007_50070801_20_dialog_content = "우리 포병들이 놈을 격추시킬 거다! 그 뒤에 우리가 놈을 처치한다!",
  ui_story_5007_50070801_21_dialog_content = "비다 소대는 작전 계획에 따라 수송 거점 내의 암귀 잔당들을 해치워라.",
  ui_story_5007_50070801_22_dialog_content = "2소대는 1소대와 합류하여 암귀를 섬멸한다!",
  ui_story_5007_50070801_23_dialog_content = "방금 도착한 포병대도 비다 쪽으로 가서 명령을 기다려라. 언제든지 내 신호에 유의해라.",
  ui_story_5007_50070801_24_dialog_content = "나머지 소대는 들어라. 고위 암귀가 수송 거점에 들어서면,\n이어서 들이닥치는 암귀 잡졸들을 밖에서 막아내라!",
  ui_story_5007_50070801_25_dialog_content = "책임관님, 소형 비행형 암귀가 나타났습니다! 저격이 힘든 상황입니다!",
  ui_story_5007_50070801_26_dialog_content = "알루라 양, 요격을 부탁한다.",
  ui_story_5007_50070801_27_dialog_content = "자네의 사격 솜씨라면 문제없겠지.",
  ui_story_5007_50070801_28_dialog_content = "그래요. 다녀올게요.",
  ui_story_5007_50070801_29_dialog_content = "<color=#e8d9bb>스슥, 스스스슥.</color>",
  ui_story_5007_50070801_30_dialog_content = "뭐야! 이, 이 암귀들은 또 어디서 온 거야?!",
  ui_story_5007_50070801_31_dialog_content = "화, 화염 공격!",
  ui_story_5007_50070801_32_dialog_content = "이런, 화나게 만든 건가?",
  ui_story_5007_50070801_33_dialog_content = "<color=#e8d9bb>탕탕! 탕탕!</color>",
  ui_story_5007_50070801_34_dialog_content = "......",
  ui_story_5007_50070801_35_dialog_content = "대단해... 몇 방에 다 쓰러트렸어...",
  ui_story_5007_50070801_36_dialog_content = "여기서 뭐 해? 커디.",
  ui_story_5007_50070801_37_dialog_content = "나... 난 전력이 안되니까... 지하성에서 심부름이라도 도와주려고...",
  ui_story_5007_50070801_38_dialog_content = "진심이야?",
  ui_story_5007_50070801_39_dialog_content = "무슨 뜻이야? 난 그냥 치안관일 뿐인걸... 전쟁 같은 건 해본 적도 없어.\n전장에 있어봤자 모두의 발목만 잡고 말 거야.",
  ui_story_5007_50070801_40_dialog_content = "역시 넌 자기 자신을 제대로 파악하질 못하는구나.\n네가 나한테 부딪혔을 때 난 내 갈비뼈가 부러졌을까 걱정했다고.",
  ui_story_5007_50070801_41_dialog_content = "뭐야? 또 싸우자는 거야?!",
  ui_story_5007_50070801_42_dialog_content = "내 말은 그러니까, 너도 충분히 싸울 수 있다는 거야.\n넌 그저 전의와 자신감이 부족할 뿐이야.",
  ui_story_5007_50070801_43_dialog_content = "뭐, 그래도 지하성 안의 일을 돕는 것도 나쁘진 않을 것 같아. 더 안전하기도 하고.",
  ui_story_5007_50070801_44_dialog_content = "암귀한테 습격당할 위험도 없을 거야.",
  ui_story_5007_50070801_45_dialog_content = "<color=#e8d9bb>구오오오...</color>",
  ui_story_5007_50070801_46_dialog_content = "무슨 소리가 나는 것 같은데?",
  ui_story_5007_50070801_47_dialog_content = "음... 뭔가 느낌이 안 좋아...",
  ui_story_5007_50070801_48_dialog_content = "아까 그 고위 암귀... 그 정도의 포격을 맞았는데...",
  ui_story_5007_50070801_49_dialog_content = "그오오오오...",
  ui_story_5007_50070801_50_dialog_content = "어떻게 이런 곳까지 올라온 거야?!",
  ui_story_5007_50070801_51_dialog_content = "크오오오──!",
  ui_story_5007_50070801_52_dialog_content = "<color=#e8d9bb>탕탕! 탕!</color>",
  ui_story_5007_50070801_53_dialog_content = "...내 공격이 전혀 효과가 없잖아?!",
  ui_story_5007_50070801_54_dialog_content = "캬악──!",
  ui_story_5007_50070801_55_dialog_content = "크윽!",
  ui_story_5007_50070801_56_dialog_content = "윽... 제길... 너무 좁아서... 피할 수가 없잖아...",
  ui_story_5007_50070801_57_dialog_content = "암귀! 여기서 죽는 한이 있어도 반드시 쓰러트리겠어!",
  ui_story_5007_50070801_58_dialog_content = "내 앞을 막으면 어쩌자는 거야?! 도망쳐!",
  ui_story_5007_50070801_59_dialog_content = "여기선 어차피 도망칠 수도 없어! 그럼 목숨 걸고 싸워야지!",
  ui_story_5007_50070801_60_dialog_content = "그오오오오...",
  ui_story_5007_50070801_61_dialog_content = "왜... 공격을 안 하는 거지?",
  ui_story_5007_50070801_62_dialog_content = "설마 저 상자를 노리는 건가?",
  ui_story_5007_50070801_63_dialog_content = "<color=#e8d9bb>퍼어엉!</color>",
  ui_story_5007_50070801_64_dialog_content = "그으으...",
  ui_story_5007_50070801_65_dialog_content = "암귀가... 방금 공격에 정신이 팔렸어!",
  ui_story_5007_50070801_66_dialog_content = "브랜트 님이야!",
  ui_story_5007_50070801_67_dialog_content = "공격에 효과가 있어서 다행이군.",
  ui_story_5007_50070801_68_dialog_content = "크오오오!",
  ui_story_5007_50070801_69_dialog_content = "각 소대에 알린다! 지정 위치에서 준비하라!",
  ui_story_5007_50070801_70_dialog_content = "이제 「추격전」을 개시한다!",
  ui_story_5007_50070801_71_dialog_content = "책임관님! 전 암귀한테 쫓기는 것보다 뒤쫓는 게 더 좋습니다!",
  ui_story_5007_50070801_72_dialog_content = "책임관님 덕분에 저놈이 지금 우릴 죽일 기세로 달려들고 있단 말입니다!",
  ui_story_5007_50070801_73_dialog_content = "캬아악──!",
  ui_story_5007_50070801_74_dialog_content = "이 녀석, 땅에 떨어트리니까 일어서는 데 한참 걸리는군요...\n그나마 지능이 높지 않아서 다행입니다!",
  ui_story_5007_50070801_75_dialog_content = "뭘 그리 말이 많은 거냐! 달려라!",
  ui_story_5007_50070801_76_dialog_content = "첫 번째 지뢰 매설 지역에 알려라! 내가 놈을 유인하겠다!",
  ui_story_5007_50070801_77_dialog_content = "알겠습니다!",
  ui_story_5007_50070801_78_dialog_content = "1번 지뢰 위치 준비!",
  ui_story_5007_50070801_79_dialog_content = "명령 전까지는 아무도 발포해선 안 된다!",
  ui_story_5007_50070801_80_dialog_content = "오발로 작전을 망치는 자는 군법에 의해 처벌한다!",
  ui_story_5007_50070801_81_dialog_content = "브랜트 책임관님이 40초 뒤에 골목을 통과하실 거다!",
  ui_story_5007_50070801_82_dialog_content = "그 뒤로 고위 암귀가 접근 중이다. 50초 후 지정 위치에 도달한다!",
  ui_story_5007_50070801_83_dialog_content = "지뢰는 준비됐어요! 언제든지 사용할 수 있어요!",
  ui_story_5007_50070801_84_dialog_content = "지뢰 기폭 준비!",
  ui_story_5007_50070801_85_dialog_content = "준비 완료!",
  ui_story_5007_50070801_86_dialog_content = "대피해라!",
  ui_story_5007_50070801_87_dialog_content = "즉시 산개한다!",
  ui_story_5007_50070801_88_dialog_content = "각자 위치로 대피하라!",
  ui_story_5007_50070801_89_dialog_content = "거기 신병! 건물 안으로 숨지 마! 이번 상대는 대형 암귀라고!",
  ui_story_5007_50070801_90_dialog_content = "앗! 네!",
  ui_story_5007_50070801_91_dialog_content = "난 정면으로 가서 브랜트 님과 합류한다!",
  ui_story_5007_50070801_92_dialog_content = "네가 내 위치를 맡아!",
  ui_story_5007_50070801_93_dialog_content = "네!",
  ui_story_5007_50070801_94_dialog_content = "브랜트 님이 예정 장소를 통과하셨습니다!",
  ui_story_5007_50070801_95_dialog_content = "10, 9, 8, 7, 6, 5, 4...",
  ui_story_5007_50070801_96_dialog_content = "암귀 출현!",
  ui_story_5007_50070801_97_dialog_content = "크오오오──!",
  ui_story_5007_50070801_98_dialog_content = "폭파!",
  ui_story_5007_50070801_99_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5007_50070801_100_dialog_content = "성공했나요?!",
  ui_story_5007_50070801_101_dialog_content = "......",
  ui_story_5007_50070801_102_dialog_content = "구오오오...",
  ui_story_5007_50070801_103_dialog_content = "이런! 위력이 부족해요!",
  ui_story_5007_50070801_104_dialog_content = "다시 일어섰어요!",
  ui_story_5007_50070801_105_dialog_content = "브랜트 님! 지뢰가... 정말 효과가 있을까요?",
  ui_story_5007_50070801_106_dialog_content = "이 암귀는 회복 능력이 있는 모양이군. 하지만 아까보다는 확실히 약해졌다.",
  ui_story_5007_50070801_107_dialog_content = "비다에게 전해라. 7번 창고를 최대 위력의 폭발 지점으로 만들어라!",
  ui_story_5007_50070801_108_dialog_content = "놈을 7번 창고에 유인해서 단번에 산산조각 내는 거다!",
  ui_story_5007_50070801_109_dialog_content = "알겠습니다!",
  ui_story_5007_50070801_110_dialog_content = "<color=#e8d9bb>휘익──</color>",
  ui_story_5007_50070801_111_dialog_content = "잠깐, 이게 무슨 소리죠?",
  ui_story_5007_50070801_112_dialog_content = "<color=#e8d9bb>휘익──</color>",
  ui_story_5007_50070801_113_dialog_content = "큰일입니다! 암귀가 다시 날아오를 생각인가 봅니다!",
  ui_story_5007_50070801_114_dialog_content = "뭐가 큰일이냐. 진작에 준비하고 있었다. 호각을 불어라!",
  ui_story_5007_50070801_115_dialog_content = "<color=#e8d9bb>삐익──!</color>",
  ui_story_5007_50070801_116_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5007_50070801_117_dialog_content = "어떻게 된 거죠?! 호각을 불자 마자 미사일이 날아오다니...",
  ui_story_5007_50070801_118_dialog_content = "바보 같긴. 미리 신호를 정해둔 거다.",
  ui_story_5007_50070801_119_dialog_content = "포병대는 계속 내 신호를 기다리고 있었다.",
  ui_story_5007_50070801_120_dialog_content = "호각 소리가 들리면 숨겨뒀던 박격포를 사용하도록 말이야!",
  ui_story_5007_50070801_121_dialog_content = "이제 놈을 묵사발로 만들 차례다!",
  ui_story_5007_50070801_122_dialog_content = "<color=#e8d9bb>쾅── 콰광── 쾅──</color>",
  ui_story_5007_50070801_123_dialog_content = "전투는 아직 끝나지 않았다!",
  ui_story_5007_50070801_124_dialog_content = "그람이 돌아왔을 때 웃음거리가 될 수는 없으니까!",
  ui_story_5007_50070901_1_dialog_content = "어이! 아이테르! 정신 차려!",
  ui_story_5007_50070901_2_dialog_content = "으윽...",
  ui_story_5007_50070901_3_dialog_content = "PlayerName! 일어나라!",
  ui_story_5007_50070901_4_dialog_content = "크억, 쿨럭쿨럭... 푸웁... 퉤...",
  ui_story_5007_50070901_5_dialog_content = "정신이 드나?",
  ui_story_5007_50070901_6_dialog_content = "푸엑... 입안이 온통 모래투성이네요... 퉤엣...",
  ui_story_5007_50070901_7_dialog_content = "어떻게 된 거죠?",
  ui_story_5007_50070901_8_dialog_content = "우린 자폭 암귀의 습격을 받았다.",
  ui_story_5007_50070901_9_dialog_content = "널 제외한 나머지 사람들은 모두 폭발을 피했다...",
  ui_story_5007_50070901_10_dialog_content = "저만 못 피했다구요?!",
  ui_story_5007_50070901_11_dialog_content = "아, 휴... 다행이다. 그래도 손발은 멀쩡하네요. 깜짝이야...",
  ui_story_5007_50070901_12_dialog_content = "근데 왜 안 다친 거죠? 제가 못 피했다면서요.",
  ui_story_5007_50070901_13_dialog_content = "그러고 보니 그때 「벽」 같은 게 저한테 밀려와서... 멀리 튕겨 날아갔던 기억이 나네요.",
  ui_story_5007_50070901_14_dialog_content = "역시 그람 씨가 절 지켜준 거군요.",
  ui_story_5007_50070901_15_dialog_content = "음. 사고 능력은 정상인 걸 보면 충격으로 머리가 이상해지진 않은 것 같군.",
  ui_story_5007_50070901_16_dialog_content = "다른 사람들은요?",
  ui_story_5007_50070901_17_dialog_content = "모래 속에 묻혀 있다.",
  ui_story_5007_50070901_18_dialog_content = "움직일 수 있겠으면 도와줘라. 다른 사람들을 모래에서 파내야 한다.",
  ui_story_5007_50070901_19_dialog_content = "다들 잠깐 기절한 것 같으니까.",
  ui_story_5007_50070901_20_dialog_content = "네 감응 능력을 이용해서 깨우면 될 거다.",
  ui_story_5007_50070901_21_dialog_content = "알겠어요...",
  ui_story_5007_50070901_22_dialog_content = "카렌, 괜찮아?!",
  ui_story_5007_50070901_23_dialog_content = "으음...",
  ui_story_5007_50070901_24_dialog_content = "다행이다! 카렌, 어디 다친 덴 없고?",
  ui_story_5007_50070901_25_dialog_content = "난 괜찮아. 머리가 좀 어지러울 뿐이야...",
  ui_story_5007_50070901_26_dialog_content = "콜록, 콜록콜록... 푸푸푸!",
  ui_story_5007_50070901_27_dialog_content = "뭐야! 내가 암귀 따위한테 터져서 모래 안에 파묻힌 거야?!",
  ui_story_5007_50070901_28_dialog_content = "이게 무슨 망신이야! 말도 안 돼!",
  ui_story_5007_50070901_29_dialog_content = "자폭 암귀의 존재를 느끼고 곧바로 범위에서 떨어진 것만으로도 충분히 행운이었어.",
  ui_story_5007_50070901_30_dialog_content = "PlayerName, 그 고위 암귀 시체도 모래에 묻힌 거야?",
  ui_story_5007_50070901_31_dialog_content = "걘 분명히 폭발로 죽었을 거야. 폭발 지점에 제일 가까이 있는 걸 봤거든.",
  ui_story_5007_50070901_32_dialog_content = "근데 자기 우두머리를 폭발에 휘말리게 해서 우릴 없애려는 암귀가 있을까?",
  ui_story_5007_50070901_33_dialog_content = "PlayerName, 넓은 범위의 감응도 가능한가? 지하성 쪽의 상황을 알고 싶다.",
  ui_story_5007_50070901_34_dialog_content = "해볼게요!",
  ui_story_5007_50070901_35_dialog_content = "『오로리안이... 아직 살아있다...』",
  ui_story_5007_50070901_36_dialog_content = "『살아있다...』",
  ui_story_5007_50070901_37_dialog_content = "『놈들이... 하이롱거 님을 방해하게 둘 순 없다!』",
  ui_story_5007_50070901_38_dialog_content = "그람 씨! 암귀가 우릴 발견했어요! 다수의 암귀가 이쪽으로 오고 있어요!",
  ui_story_5007_50070901_39_dialog_content = "놈들이 온다면 맞서 싸우는 수밖에...",
  ui_story_5007_50070901_40_dialog_content = "키에에엑──!",
  ui_story_5007_50070901_41_dialog_content = "잠깐만요... 그 고위 암귀가 지금 수송 거점 안에 있는 것 같아요!",
  ui_story_5007_50070901_42_dialog_content = "하지만 다크매터가 무척 약해져 있어요...",
  ui_story_5007_50070901_43_dialog_content = "무슨 일이 벌어진 거지?",
  ui_story_5007_50070901_44_dialog_content = "캬악──!",
  ui_story_5007_50070901_45_dialog_content = "서둘러 주변의 암귀를 제거한다!",
  ui_story_5007_50070901_46_dialog_content = "그리고 즉시 24호 지하성으로 돌아가는 거다!",
  ui_story_5007_50070902_1_dialog_content = "성공했나요?",
  ui_story_5007_50070902_2_dialog_content = "안에선 아무 움직임도 없어요...",
  ui_story_5007_50070902_3_dialog_content = "보고드립니다! 고위 암귀는 산산조각이 났습니다!",
  ui_story_5007_50070902_4_dialog_content = "작전 성공입니다!",
  ui_story_5007_50070902_5_dialog_content = "성공했다고? 우와! 우리가 해냈어요!",
  ui_story_5007_50070902_6_dialog_content = "아, 잠깐만요. 브, 브랜트 님은요?",
  ui_story_5007_50070902_7_dialog_content = "쿨럭, 쿨럭쿨럭...",
  ui_story_5007_50070902_8_dialog_content = "...어디서 목소리가...",
  ui_story_5007_50070902_9_dialog_content = "아, 왠지... 브랜트 님 목소리 같은데?",
  ui_story_5007_50070902_10_dialog_content = "브랜트 님! 꺄앗!",
  ui_story_5007_50070902_11_dialog_content = "비다... 달릴 땐 발밑을 조심해야지... 왜 항상 넘어지는 거냐?",
  ui_story_5007_50070902_12_dialog_content = "죄, 죄송해요... 괜찮으세요?",
  ui_story_5007_50070902_13_dialog_content = "난 괜찮다... 잔해에 파묻혔을 뿐이다...",
  ui_story_5007_50070902_14_dialog_content = "너한테 신호를 보냈을 때 난 이미 위험 범위 밖으로 대피해 있었다.",
  ui_story_5007_50070902_15_dialog_content = "히잉... 다행이에요...",
  ui_story_5007_50070902_16_dialog_content = "울지 마라!",
  ui_story_5007_50070902_17_dialog_content = "아, 알겠어요...",
  ui_story_5007_50070902_18_dialog_content = "보초병을 불러 상황을 보고하도록...",
  ui_story_5007_50070902_19_dialog_content = "난 여기서 좀 쉬어야겠어...",
  ui_story_5007_50070902_20_dialog_content = "네, 알겠습니다!",
  ui_story_5007_50070902_21_dialog_content = "감시대의 보고를 받았습니다.",
  ui_story_5007_50070902_22_dialog_content = "측면 전장의 암귀들에게서 철수 징후가 보입니다.",
  ui_story_5007_50070902_23_dialog_content = "하지만 아직도 다수의 암귀들이 수송 거점으로 향하고 있습니다.",
  ui_story_5007_50070902_24_dialog_content = "수송 거점 밖에서 작전 중이던 소대들은 이미 거점 안으로 철수했습니다.",
  ui_story_5007_50070902_25_dialog_content = "현재 건물을 엄폐물로 사용해 작전 중입니다.",
  ui_story_5007_50070902_26_dialog_content = "좋은 소식은 암귀의 공세가 뚜렷이 감소했고, 움직임도 둔해졌다는 겁니다.",
  ui_story_5007_50070902_27_dialog_content = "PlayerName 소대의 소식은?",
  ui_story_5007_50070902_28_dialog_content = "보고에 따르면 동쪽 전장에서 루미나를 발산할 때의 섬광이 포착되었다고 합니다.",
  ui_story_5007_50070902_29_dialog_content = "오로리안이 수송 거점을 향해 오고 있는 것으로 보입니다.",
  ui_story_5007_50070902_30_dialog_content = "분명히 그들이겠지! 그럴 거다! 크윽, 쿨럭쿨럭...",
  ui_story_5007_50070902_31_dialog_content = "책임관님! 괜찮으십니까?!",
  ui_story_5007_50070902_32_dialog_content = "하하... 난 괜찮다...",
  ui_story_5007_50070902_33_dialog_content = "그람 쪽도 이제 곧 돌아올 테니...",
  ui_story_5007_50070902_34_dialog_content = "주변의 전투 가능 인원을 모두 집합시켜라!",
  ui_story_5007_50070902_35_dialog_content = "반격의 때가 되었다!",
  ui_story_5007_50070902_36_dialog_content = "예!",
  ui_story_5007_50070902_37_dialog_content = "전원! 반격 개시다!",
  ui_story_5007_50070902_38_dialog_content = "24호 지하성 방어전의 반격을 시작한다!",
  ui_story_5007_50070902_39_dialog_content = "<anim type=Shake><size=42>우오오오오오!</size></anim>",
  ui_story_5007_50070902_40_dialog_content = "돌격──!",
  ui_story_5007_50070902_41_dialog_content = "우리 일루미나를 침략한 암귀를 절대 용서하지 마라!",
  ui_story_5007_50070902_42_dialog_content = "총구로 적을 조준해라!",
  ui_story_5007_50070902_43_dialog_content = "<color=#e8d9bb>푸슉.</color>",
  ui_story_5007_50070902_44_dialog_content = "......",
  ui_story_5007_50070902_45_dialog_content = "(...이게 무슨 소리냐...)",
  ui_story_5007_50070902_46_dialog_content = "(어째서... 하필 이때... 이런 일이 일어나는 거냐.)",
  ui_story_5007_50070902_47_dialog_content = "그르르르르...",
  ui_story_5007_50070902_48_dialog_content = "(농담이겠지...)",
  ui_story_5007_50070902_49_dialog_content = "(불사신이라도 된다는 거냐...)",
  ui_story_5007_50070902_50_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5007_50070902_51_dialog_content = "잔해에서 뭔가 튀어나왔다! ...암귀가 아직 살아있어!",
  ui_story_5007_50070902_52_dialog_content = "크오오──!",
  ui_story_5007_50070902_53_dialog_content = "<size=45>브랜트 님! 안 돼──!</size>",
  ui_story_5007_50071001_1_dialog_content = "(그러고 보면... 난 왜 여기서 지휘를 하고 있는 건가...)",
  ui_story_5007_50071001_2_dialog_content = "(분명히 난 그때 그람과 마찬가지로... 다시는 전쟁에 나서지 않겠다고 생각했는데 말이야.)",
  ui_story_5007_50071001_3_dialog_content = "(하지만 24호 지하성의 선배가 항상 날 찾아왔었지.)",
  ui_story_5007_50071001_4_dialog_content = "버나드가 목숨을 잃은 후, 용사 별동대는 해산됐습니다.",
  ui_story_5007_50071001_5_dialog_content = "그람은 세상을 등진 채 지내고 있고 말이지요.",
  ui_story_5007_50071001_6_dialog_content = "전 그람처럼 괴로워하진 않을 겁니다.",
  ui_story_5007_50071001_7_dialog_content = "그람은 저와는 달리 마음이 따뜻한 녀석이니 말입니다.",
  ui_story_5007_50071001_8_dialog_content = "다를 게 뭐가 있겠나.",
  ui_story_5007_50071001_9_dialog_content = "내가 보기엔 자네도 아직 한참 젊어. 브랜트.",
  ui_story_5007_50071001_10_dialog_content = "자네들은 다 똑같다고!",
  ui_story_5007_50071001_11_dialog_content = "모두 훌륭한 군인이자 전사고. 철혈의 병사이자 바른 마음을 지닌 녀석들이다.",
  ui_story_5007_50071001_12_dialog_content = "...그만 좀 두들기세요. 선배님.",
  ui_story_5007_50071001_13_dialog_content = "왕년의 상처까지 아플 지경이란 말입니다.",
  ui_story_5007_50071001_14_dialog_content = "이런, 미안하네. 난 이번에 자네가 24호 지하성의 교관이 되어준다고 해서 정말 기뻤거든.",
  ui_story_5007_50071001_15_dialog_content = "용사 별동대의 대원이 두 명이나 우리 24호 지하성을 찾아줬으니 말이야.\n다들 자랑스럽게 생각하고 있어!",
  ui_story_5007_50071001_16_dialog_content = "이미 오래된 일입니다. 자랑할 것도 못 됩니다.",
  ui_story_5007_50071001_17_dialog_content = "게다가 그람도 옛날 생각은 안 하고 싶을 테니...\n선배도 녀석 앞에서는 옛날 얘기 좀 꺼내지 마세요.",
  ui_story_5007_50071001_18_dialog_content = "휴... 자네들 모두 오랜 전우들인데, 그 시절 얘기도 마음대로 못 꺼내는 건가? 정말 답답하군.",
  ui_story_5007_50071001_19_dialog_content = "참, 그 아이도 우리 쪽 신병 캠프에 배속됐다. 알고 있었나?",
  ui_story_5007_50071001_20_dialog_content = "어느 아이 말입니까?",
  ui_story_5007_50071001_21_dialog_content = "자네의 <color=#FFB400>전우 버나드의 딸</color> 말이야.",
  ui_story_5007_50071001_22_dialog_content = "이름은 레비라고 한다.",
  ui_story_5007_50071001_23_dialog_content = "아마 이번에 자네가 교육을 맡게 될 거다. 잘 돌봐줘라.",
  ui_story_5007_50071001_24_dialog_content = "...26년 전이었지. 용사 별동대의 탄생.",
  ui_story_5007_50071001_25_dialog_content = "자네, 그람, 버나드, 그리고 나중에 합류한 아이테르...",
  ui_story_5007_50071001_26_dialog_content = "그 부대는 누구보다도 강한 최강의 소대가 되었다.",
  ui_story_5007_50071001_27_dialog_content = "그 후에 그 아이테르는 헤븐즈 밸리로 돌아갔지만, 헤븐즈 밸리는 암귀에게 멸망당했고...\n우린 다시는 그가 돌아오길 기다릴 수 없게 되었지.",
  ui_story_5007_50071001_28_dialog_content = "그러나 14년 전 어둠의 위기가 시작됐을 때...",
  ui_story_5007_50071001_29_dialog_content = "자네들은 그 아이테르의 의지를 계승했고,\n다시 기적 같은 소대의 전설을 만들며 무수한 암귀를 쓰러트렸다.",
  ui_story_5007_50071001_30_dialog_content = "당시 얼마나 많은 병사들이 자네들의 전설에 힘을 얻었는지는 자네도 알고 있겠지.",
  ui_story_5007_50071001_31_dialog_content = "레비도 이젠 버나드의 뜻을 이어받은 훌륭한 전사가 됐다.",
  ui_story_5007_50071001_32_dialog_content = "오늘 자네들이 한자리에 모인 것을 본 것으로 내 염원이 하나 이루어졌네.",
  ui_story_5007_50071001_33_dialog_content = "언젠가는 세 사람이 함께 싸우는 모습을 볼 수 있다면 좋겠는데 말이야.",
  ui_story_5007_50071001_34_dialog_content = "분명히 희망으로 가득 찬 모습이겠지. 하하.",
  ui_story_5007_50071001_35_dialog_content = "그렇지 않은가? 브랜트?",
  ui_story_5007_50071001_36_dialog_content = "(그러게 말입니다...)",
  ui_story_5007_50071001_37_dialog_content = "(정말 빨리도 오는군... 역시 내가 인정한 자들답다...)",
  ui_story_5007_50071001_38_dialog_content = "브랜트 씨!",
  ui_story_5007_50071001_39_dialog_content = "<size=40>브랜트 님──!</size>",
  ui_story_5007_50071001_40_dialog_content = "<size=45>브랜트──!</size>",
  ui_story_5007_50071001_41_dialog_content = "엄호해라! 브랜트를 구하러 간다!",
  ui_story_5007_50071001_42_dialog_content = "전력 돌격!",
  ui_story_5007_50071001_43_dialog_content = "전부 불타버려!",
  ui_story_5007_50071001_44_dialog_content = "키에에엑──!",
  ui_story_5007_50071001_45_dialog_content = "브랜트! 가자!",
  ui_story_5007_50071001_46_dialog_content = "네가 브랜트 님을 죽였어! 절대 용서 못 해!",
  ui_story_5007_50071001_47_dialog_content = "난 아직...",
  ui_story_5007_50071001_48_dialog_content = "레비! 진정해라! 브랜트는 아직 죽지 않았어!",
  ui_story_5007_50071001_49_dialog_content = "신경... 쓰지 마라... 지하성... 부터...",
  ui_story_5007_50071001_50_dialog_content = "알고 있다고! 지금은 말하지 마라!",
  ui_story_5007_50071001_51_dialog_content = "크오오오──!",
  ui_story_5007_50071001_A1_dialog_content = "그람 씨! 브랜트 씨는요?!",
  ui_story_5007_50071001_A2_dialog_content = "......",
  ui_story_5007_50071001_52_dialog_content = "레비! PlayerName! 브랜트의 명령이다!",
  ui_story_5007_50071001_53_dialog_content = "죽는 한이 있더라도 암귀를 막고 24호 지하성을 지켜라!",
  ui_story_5007_50071001_54_dialog_content = "어떻게든 이겨라!",
  ui_story_5007_50071001_55_dialog_content = "PlayerName, 지휘는 네게 맡긴다! 멀리서 지휘해라! 될 수 있는 대로 떨어져라!",
  ui_story_5007_50071001_56_dialog_content = "알겠어요!",
  ui_story_5007_50071001_57_dialog_content = "레비! 넌 좌측으로 가라! 연계 공격을 기다려!",
  ui_story_5007_50071001_58_dialog_content = "말 안 해도 알고 있어! 전류 돌격!",
  ui_story_5007_50071001_59_dialog_content = "카렌, 넌 다른 병사와 함께 부상자들의 퇴각을 도와줘라!",
  ui_story_5007_50071001_60_dialog_content = "알겠어!",
  ui_story_5007_50071001_61_dialog_content = "그오오오...",
  ui_story_5007_50071001_62_dialog_content = "공격을 조심해! 레비! 철수해라!",
  ui_story_5007_50071001_63_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5007_50071001_64_dialog_content = "구오오오...",
  ui_story_5007_50071001_65_dialog_content = "<color=#e8d9bb>휘익── 휘익──</color>",
  ui_story_5007_50071001_66_dialog_content = "놈이 날아가려고 해! 내가 떨어트리겠어!",
  ui_story_5007_50071001_67_dialog_content = "기다려! 레비!",
  ui_story_5007_50071001_68_dialog_content = "내버려 둬!",
  ui_story_5007_50071001_69_dialog_content = "여기서 싸운다면 철수 중인 부상자들까지 휘말릴 거다!",
  ui_story_5007_50071001_70_dialog_content = "그람 씨! 녀석이 플랫폼 쪽으로 가려고 해요!",
  ui_story_5007_50071001_71_dialog_content = "설마 지하성으로 들어갈 생각인가?",
  ui_story_5007_50071001_72_dialog_content = "그렇다면 우리도 가서 놈을 붙잡는다!",
  ui_story_5007_50071002_1_dialog_content = "암귀가 쓰러졌어...?",
  ui_story_5007_50071002_2_dialog_content = "어째서...",
  ui_story_5007_50071002_3_dialog_content = "이렇게 약한 암귀가 어떻게 브랜트 님을 해친 거냐고!",
  ui_story_5007_50071002_4_dialog_content = "인정할 수 없어!",
  ui_story_5007_50071002_5_dialog_content = "그런 게 아닙니다...",
  ui_story_5007_50071002_6_dialog_content = "그 암귀는 전혀... 약하지 않았습니다...",
  ui_story_5007_50071002_7_dialog_content = "거기 당신! 부상이 심하잖아! 왜 여기 있는 거야?",
  ui_story_5007_50071002_8_dialog_content = "어서 대피해!",
  ui_story_5007_50071002_9_dialog_content = "아니... 꼭 전할 말이 있습니다...",
  ui_story_5007_50071002_10_dialog_content = "부탁입니다...",
  ui_story_5007_50071002_11_dialog_content = "지금 녀석이 약해진 건... 책임관님이 저희와 함께 그 녀석에 맞서 싸웠기 때문입니다.",
  ui_story_5007_50071002_12_dialog_content = "하지만... 놈은 계속해서 다시 일어섰습니다.",
  ui_story_5007_50071002_13_dialog_content = "그러니... 놈이 다시는 일어서지 못하게...",
  ui_story_5007_50071002_14_dialog_content = "잿더미로 만들어 완전히 소멸시켜야 합니다!",
  ui_story_5007_50071002_15_dialog_content = "레비, 그람 씨, 계속해서 암귀를 공격해 줘!",
  ui_story_5007_50071002_16_dialog_content = "알겠다.",
  ui_story_5007_50071002_17_dialog_content = "알겠어! 방금 전엔 내가 틀렸어. 내가 잘못 말한 거야!",
  ui_story_5007_50071002_18_dialog_content = "전류! 참격!",
  ui_story_5007_50071002_19_dialog_content = "계속! 계속 공격해야 합니다!",
  ui_story_5007_50071002_20_dialog_content = "놈이 재가 돼서 더는 재생할 수 없을 때까지!",
  ui_story_5007_50071002_21_dialog_content = "전류! 참격!",
  ui_story_5007_50071002_22_dialog_content = "참격! 참격! 참격──!",
  ui_story_5007_50071002_23_dialog_content = "아직 멀었어! 멀었다구!",
  ui_story_5007_50071002_24_dialog_content = "키에에엑...",
  ui_story_5007_50071002_25_dialog_content = "놈이 손을 뻗는다! 조심해!",
  ui_story_5007_50071002_26_dialog_content = "아직... 아직 더 공격할 수 있다구!",
  ui_story_5007_50071002_27_dialog_content = "잠깐만! 녀석은 지금 공격하려는 게 아냐! 사라지고 있어!",
  ui_story_5007_50071002_28_dialog_content = "크에엑...",
  ui_story_5007_50071002_29_dialog_content = "이 녀석... 왜 상자에 손을 뻗는 거야?",
  ui_story_5007_50071002_30_dialog_content = "......",
  ui_story_5007_50071002_31_dialog_content = "잿더미로 변해버렸어...",
  ui_story_5007_50071002_32_dialog_content = "...놈은 사라지기 직전까지 저 상자를 노렸던 것 같군.",
  ui_story_5007_50071002_33_dialog_content = "저건 화물이 있던 상자입니다. 설마... <color=#FFB400>수송대의 화물</color>을 빼앗는 게 놈들의 목적이었을까요?",
  ui_story_5007_50071002_34_dialog_content = "그래봤자 안에는 텅 비었는데 말입니다.",
  ui_story_5007_50071002_35_dialog_content = "상자 안의 물건을 갖고 싶은데, 안이 텅 비어 있다는 걸 알게 되면 어떨 것 같나?",
  ui_story_5007_50071002_36_dialog_content = "아마 당신들이 물건을 숨겼을 거라고 생각하고...\n지하성을 전부 뒤져서라도 찾으려고 하겠지.",
  ui_story_5007_50071002_37_dialog_content = "상자는 여기 두자고. 신경 쓰지 마라.",
  ui_story_5007_50071002_38_dialog_content = "암귀가 상자를 노린다면, 길목에 함정을 준비하면 된다.",
  ui_story_5007_50071002_39_dialog_content = "보고드립니다! 다수의 암귀가 수송 거점으로 접근하는 것을 감시대에서 포착했습니다!",
  ui_story_5007_50071002_40_dialog_content = "브랜트 님이 명령을 내리셨습니다!",
  ui_story_5007_50071002_41_dialog_content = "24호 지하성이 안전해지거나 모든 시민의 대피가 완료될 때까지,\n전 병력은 끝까지 작전을 수행합니다!",
  ui_story_5007_50071002_42_dialog_content = "또한, 브랜트 님은 전장 지휘의 모든 권한을 그람 님께 위임하셨습니다.",
  ui_story_5007_50071002_43_dialog_content = "브랜트의 상태는 어떻지?",
  ui_story_5007_50071002_44_dialog_content = "책임관님은 수송 거점 내의 임시 진료소에서 응급 처치를 받고 계십니다!",
  ui_story_5007_50071002_45_dialog_content = "치료 중입니다만, 부상이 심각합니다!",
  ui_story_5007_50071002_46_dialog_content = "부탁드립니다! 시간을 벌어 주십시오! 수송 거점을 반드시 지켜야 합니다!",
  ui_story_5007_50071002_47_dialog_content = "알겠다.",
  ui_story_5007_50071002_48_dialog_content = "『하이롱거 님께서 새로운 명령을 내리셨다.』",
  ui_story_5007_50071002_49_dialog_content = "『이제부터 우리는 하이롱거 님의 지시에 따라...』",
  ui_story_5007_50071002_50_dialog_content = "『지하성을 파괴한다! 목표를 파괴해라!』",
  ui_story_5007_50071002_51_dialog_content = "『전진!』",
  ui_story_5007_50071002_52_dialog_content = "『전진해라!』",
  ui_story_5007_50071002_53_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5007_50071002_54_dialog_content = "폭발인가?!",
  ui_story_5007_50071002_55_dialog_content = "PlayerName, 상황 확인을 부탁한다!",
  ui_story_5007_50071002_56_dialog_content = "암귀가 벌써 지하성 내부로 침입했어요! 대부분 후방에 몰려 있지만 수는 많지 않아요.",
  ui_story_5007_50071002_57_dialog_content = "하지만 대규모의 암귀가 수송 거점을 향해 몰려오고 있어요.",
  ui_story_5007_50071002_58_dialog_content = "후방이 이미 함락됐는데, 다수의 암귀가 수송 거점으로 향하고 있다...?",
  ui_story_5007_50071002_59_dialog_content = "역시, 지하성 습격은 2순위 목표였을 뿐인가.",
  ui_story_5007_50071002_60_dialog_content = "난 병력을 데리고 지하성에 침입한 암귀를 처리하고 오겠다.",
  ui_story_5007_50071002_61_dialog_content = "레비, 넌 PlayerName 곁에 있어라.",
  ui_story_5007_50071002_62_dialog_content = "정면의 전장에서 수송 거점으로 들어가려는 암귀를 모두 막는 거다!",
  ui_story_5007_50071002_63_dialog_content = "알겠어. 그건 브랜트 님의 명령이니까.",
  ui_story_5007_50071002_64_dialog_content = "기억하고 있다고.",
  ui_story_5007_50071002_65_dialog_content = "자, 모두 계속해서 싸우는 거다!",
  ui_story_5007_50071002_66_dialog_content = "잠깐만요... 저도 계속 싸울 거예요.",
  ui_story_5007_50071002_67_dialog_content = "알루라, 너, 상처가...",
  ui_story_5007_50071002_68_dialog_content = "괜찮아. 브랜트 씨가 우릴 구해줬어. 그러니 우린 빚을 진 거야.",
  ui_story_5007_50071002_68X_dialog_content = "게다가 난 벌써 브랜트 씨의 의뢰를 받아버렸으니까...",
  ui_story_5007_50071002_69_dialog_content = "맞아요. 저희도 도울게요!",
  ui_story_5007_50071002_70_dialog_content = "좋다.",
  ui_story_5007_50071002_71_dialog_content = "알루라, 커디, 너희도 PlayerName 일행과 움직인다.",
  ui_story_5007_50071002_72_dialog_content = "비다, 넌 나와 지하성으로 간다.",
  ui_story_5007_50071002_73_dialog_content = "작전 목표는 수송 거점을 지키고, 24호 지하성을 지키는 거다!",
  ui_story_5007_50071002_74_dialog_content = "여명의 빛을 위하여!",
  ui_story_5007_50071002_75_dialog_content = "출발!",
  ui_story_5007_50071101_1_dialog_content = "보고드립니다!",
  ui_story_5007_50071101_2_dialog_content = "지하성에 암귀가 점점 더 많아지고 있습니다! 성벽의 구멍도 커지고 있습니다!",
  ui_story_5007_50071101_3_dialog_content = "고참병들의 지원이 도착했지만, 도저히 막을 수가 없습니다!",
  ui_story_5007_50071101_4_dialog_content = "...이대로면 더 많은 암귀들이 몰려와서... 더는 버티지 못할 거예요.",
  ui_story_5007_50071101_5_dialog_content = "더 큰 문제는...",
  ui_story_5007_50071101_6_dialog_content = "크르르르...",
  ui_story_5007_50071101_7_dialog_content = "노, 놈들이 이미 이곳까지...",
  ui_story_5007_50071101_8_dialog_content = "어서 사격해!",
  ui_story_5007_50071101_9_dialog_content = "캬아악!",
  ui_story_5007_50071101_10_dialog_content = "아, 안 되겠어요... 이대로면 성에 들어오는 암귀가 더 많아질 뿐이에요...",
  ui_story_5007_50071101_11_dialog_content = "당황하지 말고 계속 싸워!",
  ui_story_5007_50071101_12_dialog_content = "뭐, 더 나빠져봤자 레드 키를 써서 같이 자폭하는 것밖에 더하겠나!",
  ui_story_5007_50071101_13_dialog_content = "너희에겐 미안하다. 적의 계획을 미처 파악하지 못한 내 잘못이다...",
  ui_story_5007_50071101_14_dialog_content = "적의 규모나 잠입도 생각하지 못했지. 미안하다.",
  ui_story_5007_50071101_15_dialog_content = "이젠 레드 키도 누를 수 없는 건가...",
  ui_story_5007_50071101_16_dialog_content = "책임관님! 그런 말씀 마십시오! 절대 책임관님 잘못이 아닙니다!",
  ui_story_5007_50071101_17_dialog_content = "캬악──!",
  ui_story_5007_50071101_18_dialog_content = "암귀가 갈수록 많아지고 있어요... 이래서는 끝도 없다구요...",
  ui_story_5007_50071101_19_dialog_content = "더는 못 버티겠어요!",
  ui_story_5007_50071101_20_dialog_content = "크르르르...",
  ui_story_5007_50071101_21_dialog_content = "엎드려!",
  ui_story_5007_50071101_22_dialog_content = "그, 그람 님의 불꽃이야! 그람 님이 오셨어!",
  ui_story_5007_50071101_23_dialog_content = "선배, 적의 위협은 이미 제거했다.",
  ui_story_5007_50071101_24_dialog_content = "지금부터 수송 거점과 24호 지하성을 전력으로 방어하겠다.",
  ui_story_5007_50071101_25_dialog_content = "반격은 아직 끝나지 않았다. 우린 패배한 게 아니다.",
  ui_story_5007_50071101_26_dialog_content = "좋다. 뒤쪽 성벽에 큰 구멍이 뚫려 다수의 암귀가 지하성으로 침입해버렸다.",
  ui_story_5007_50071101_27_dialog_content = "자네가 우리와 함께 암귀가 들어오는 구멍을 막아준다면,\n승산이 높아질 것이다.",
  ui_story_5007_50071101_28_dialog_content = "이 정도 병사로 구멍을 막기는 어렵다.",
  ui_story_5007_50071101_29_dialog_content = "이미 요충지마다 병사를 파견해 뒀다.",
  ui_story_5007_50071101_30_dialog_content = "모두가 우리의 작전 계획에 협조해 주길 바란다.\n암귀들을 전부 후방의 고아원으로 유인하는 거다.",
  ui_story_5007_50071101_31_dialog_content = "좋다. 전원 주목하라!",
  ui_story_5007_50071101_31X_dialog_content = "성의 아이들은 이미 대피했고, 고아원에는 아무도 없다.",
  ui_story_5007_50071101_32_dialog_content = "암귀들을 모두 고아원으로 유인해라!",
  ui_story_5007_50071101_33_dialog_content = "크르르르...",
  ui_story_5007_50071101_34_dialog_content = "끼익... 키이익...",
  ui_story_5007_50071101_35_dialog_content = "크오?",
  ui_story_5007_50071101_36_dialog_content = "뛰어, 어서 뛰어!",
  ui_story_5007_50071101_37_dialog_content = "우왓!",
  ui_story_5007_50071101_38_dialog_content = "아, 위험했어... 그래도 안 넘어졌어!",
  ui_story_5007_50071101_39_dialog_content = "드디어... 안전 구역에 도착했습니다!",
  ui_story_5007_50071101_40_dialog_content = "크르르르...",
  ui_story_5007_50071101_41_dialog_content = "암귀가 모두 고아원 근처에 모였습니다... 다행이에요.",
  ui_story_5007_50071101_42_dialog_content = "폭파를 준비하라!",
  ui_story_5007_50071101_43_dialog_content = "안녕... 내가 제일 좋아했던... 16년 동안 살았던... 24호 고아원!",
  ui_story_5007_50071101_44_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5007_50071101_45_dialog_content = "『전진.』",
  ui_story_5007_50071101_46_dialog_content = "『전진해라.』",
  ui_story_5007_50071101_47_dialog_content = "『하이롱거 님의 마지막 명령에 따르는 것이다.』",
  ui_story_5007_50071101_48_dialog_content = "『압도적인 힘으로.』",
  ui_story_5007_50071101_49_dialog_content = "『오로리안들에게 절망을 선사해라.』",
  ui_story_5007_50071101_50_dialog_content = "알루라!",
  ui_story_5007_50071101_51_dialog_content = "난 괜찮아. 뭐 하러 왔어?",
  ui_story_5007_50071101_52_dialog_content = "암귀들이 잔뜩 너한테 달려가는 걸 봤거든... 넌 부상도 입었고 하니까...",
  ui_story_5007_50071101_53_dialog_content = "그리고 내가 한 방에 터트려버렸잖아.",
  ui_story_5007_50071101_54_dialog_content = "이렇게.",
  ui_story_5007_50071101_55_dialog_content = "캬악──!",
  ui_story_5007_50071101_56_dialog_content = "다른 사람을 돕겠다는 마음은 좋은데, 암귀를 더 유인하진 말아 줄래?",
  ui_story_5007_50071101_57_dialog_content = "일부러 그런 거 아니야!",
  ui_story_5007_50071101_58_dialog_content = "바깥쪽 전장은 완전히 난장판이 됐어.\n사방이 온통 암귀투성이야. 무슨 좋은 방법 없을까?",
  ui_story_5007_50071101_59_dialog_content = "난장판일 땐 난장판에 맞게 싸우면 돼... 넌 가서 녀석들을 내 쪽으로 유인해.",
  ui_story_5007_50071101_60_dialog_content = "에? 나보고 미끼가 되라는 거야?!",
  ui_story_5007_50071101_61_dialog_content = "난 달리기도 느린데!",
  ui_story_5007_50071101_62_dialog_content = "가슴이 커서 뛰는 데 방해된다고 말하면 가만 안 둘 거야.\n난 부상자라고. 나보단 네가 더 빠를 거야.",
  ui_story_5007_50071101_62X_dialog_content = "벼, 별로 방해는 안 되거든! 그게 왜 나와!",
  ui_story_5007_50071101_63_dialog_content = "빨리 가기나 해!",
  ui_story_5007_50071101_64_dialog_content = "따라오는 녀석들은 하나도 남김없이 쏴서 죽여줄 테니까!",
  ui_story_5007_50071101_65_dialog_content = "크오오──!",
  ui_story_5007_50071101_66_dialog_content = "거기 병사! 위험해!",
  ui_story_5007_50071101_67_dialog_content = "캬아악!",
  ui_story_5007_50071101_68_dialog_content = "고마워요! 하얀 창병!",
  ui_story_5007_50071101_69_dialog_content = "하얀 창병? 날 말하는 건가?",
  ui_story_5007_50071101_70_dialog_content = "네, 누구신지는 잘 모르겠지만 구해줘서 고마워요!",
  ui_story_5007_50071101_71_dialog_content = "목숨도 살려주고 덕분에 더 많은 암귀를 때려잡을 수 있게 됐으니까요!",
  ui_story_5007_50071101_72_dialog_content = "돌격──!",
  ui_story_5007_50071101_73_dialog_content = "일루미나의 병사들은 꽤 재미있네.",
  ui_story_5007_50071101_74_dialog_content = "크오오──!",
  ui_story_5007_50071101_75_dialog_content = "레비! 돌격!",
  ui_story_5007_50071101_76_dialog_content = "캬아악!",
  ui_story_5007_50071101_77_dialog_content = "돌격!",
  ui_story_5007_50071101_78_dialog_content = "돌격! 돌격!",
  ui_story_5007_50071101_79_dialog_content = "<size=30>저기... 거기 계속 돌격하는 레비...</size>",
  ui_story_5007_50071101_80_dialog_content = "<size=30>나 좀 도와줘...</size>",
  ui_story_5007_50071101_81_dialog_content = "무슨 소리야? 어디서 모기가 우는 건가?",
  ui_story_5007_50071101_82_dialog_content = "<size=30>나 여기야... 구덩이 안에...</size>",
  ui_story_5007_50071101_83_dialog_content = "PlayerName, 왜 그런 데 있어?",
  ui_story_5007_50071101_84_dialog_content = "빠져버렸어. 얼른 꺼내줘.",
  ui_story_5007_50071101_85_dialog_content = "로봇 팔은 사람 당길 때 편해. 잡았어.",
  ui_story_5007_50071101_86_dialog_content = "엄청 힘이 센 팔이네... 내 손이 부서지는 줄 알았어... 고마워.",
  ui_story_5007_50071101_87_dialog_content = "크르르...",
  ui_story_5007_50071101_88_dialog_content = "PlayerName, 근처의 암귀는 전부 없앴어.",
  ui_story_5007_50071101_89_dialog_content = "좋아! 그럼 주변의 전장을 지원하자!",
  ui_story_5007_50071101_90_dialog_content = "『오로리안을 죽여라. 지하성에 쳐들어가 목표를 파괴해라.』",
  ui_story_5007_50071101_91_dialog_content = "『전진해라.』",
  ui_story_5007_50071101_92_dialog_content = "지금 전장이 너무 혼란스럽지 않아?",
  ui_story_5007_50071101_93_dialog_content = "응? 그래도 다들 한마음으로 싸우고 있는걸...",
  ui_story_5007_50071101_94_dialog_content = "아니지, 한마음이라곤 해도 확실히 너무 분산돼 있어.",
  ui_story_5007_50071101_95_dialog_content = "역시 총지휘관의 빈자리가 큰 거겠지...",
  ui_story_5007_50071101_96_dialog_content = "안 돼! 암귀가 너무 많아!",
  ui_story_5007_50071101_97_dialog_content = "점점 더 많아지고 있어!",
  ui_story_5007_50071101_98_dialog_content = "부상병 발생! 누가 좀 도와줘!",
  ui_story_5007_50071101_99_dialog_content = "병사, 내가 엄호하겠다. 어서 수송 거점으로 퇴각해라!",
  ui_story_5007_50071101_100_dialog_content = "그람 님이다! 다행이야!",
  ui_story_5007_50071101_101_dialog_content = "그람 님이 전장에 돌아오셨다는 건 지하성 안이 이제 안전하다는 뜻이겠군요!",
  ui_story_5007_50071101_102_dialog_content = "하지만...",
  ui_story_5007_50071101_103_dialog_content = "바깥에 암귀가... 너무 많습니다...",
  ui_story_5007_50071101_104_dialog_content = "『계속 전진해라.』",
  ui_story_5007_50071101_105_dialog_content = "『오로리안을 죽여라.』",
  ui_story_5007_50071101_106_dialog_content = "우선 철수해라! 외곽 전장은 포기한다!",
  ui_story_5007_50071101_107_dialog_content = "『모조리 죽여라.』",
  ui_story_5007_50071101_108_dialog_content = "수송 거점까지 퇴각해라!",
  ui_story_5007_50071101_109_dialog_content = "『모두 짓뭉개버려라.』",
  ui_story_5007_50071101_110_dialog_content = "더는 못 버텨... 이런 싸움은... 이길 수 없다고...",
  ui_story_5007_50071101_111_dialog_content = "<color=#e8d9bb>휘이잉──!</color>",
  ui_story_5007_50071101_112_dialog_content = "...무슨 소리지?",
  ui_story_5007_50071101_113_dialog_content = "바람 소리야! 위를 봐! 콜로서스가 돌아왔어!",
  ui_story_5007_50071101_114_dialog_content = "마이크 테스트, 마이크 테스트...",
  ui_story_5007_50071101_115_dialog_content = "여러분!",
  ui_story_5007_50071101_116_dialog_content = "들~리~나~요?!",
  ui_story_5007_50071101_117_dialog_content = "통신병 안시아! 상공에서 방송 중입니다!",
  ui_story_5007_50071101_118_dialog_content = "저희가 돌아왔어요! 포탄과 함께 말이죠!",
  ui_story_5007_50071101_119_dialog_content = "24호 지하성 방어전! 반드시 이길 수 있어요!",
  ui_story_5007_50071101_120_dialog_content = "한 번 더! 여명의 빛을 위하여!",
  ui_story_5007_50071101_121_dialog_content = "반드시 이길 수 있다구요!",
  ui_story_5007_50071101_122_dialog_content = "들었나? 가서 포병을 전부 불러와라!",
  ui_story_5007_50071101_123_dialog_content = "포탄이 왔다!",
  ui_story_5007_50071101_124_dialog_content = "몇 명은 콜로서스 착륙 지점으로 가서 물자 수령 준비를 해라!",
  ui_story_5007_50071101_125_dialog_content = "포탄을 받으면 실컷 쏟아부어 주는 거다!",
  ui_story_5007_50071101_126_dialog_content = "이 빌어먹을 암귀들을 한 놈도 살려서 보내지 마라!",
  ui_story_5007_50071102_1_dialog_content = "암귀들이 퇴각한다!",
  ui_story_5007_50071102_2_dialog_content = "<size=45>우리의 승리다!</size>",
  ui_story_5007_50071102_3_dialog_content = "브랜트, 저들의 환호성이 들리나?",
  ui_story_5007_50071102_4_dialog_content = "콜로서스가 탄약을 가져왔다. 포격이 5분 내내 지속됐지.",
  ui_story_5007_50071102_5_dialog_content = "희생된 병사의 80%는 고참병이었다... 모두 자네처럼 용감하게 싸웠지.",
  ui_story_5007_50071102_6_dialog_content = "마침내 암귀 군대가 물러났고, 우리가 이겼다.",
  ui_story_5007_50071102_7_dialog_content = "......",
  ui_story_5007_50071102_8_dialog_content = "오래 버텼더군... 의무병에게 다 들었다.",
  ui_story_5007_50071102_9_dialog_content = "이제 푹 쉬게.",
  ui_story_5007_50071102_10_dialog_content = "이상하군. 우리가 그 전쟁 뒤로 다시 만났을 때가 왜 갑자기 생각이 나는지 모르겠어.",
  ui_story_5007_50071102_11_dialog_content = "브랜트? 자네가 여긴 왜...",
  ui_story_5007_50071102_12_dialog_content = "먼저 묻는 말에 답해. 이 술병들은 어떻게 된 거지?",
  ui_story_5007_50071102_13_dialog_content = "...정신을 무디게 만들기 위해서다.",
  ui_story_5007_50071102_14_dialog_content = "겨우 이런 식으로 자신을 망치겠다는 거냐?",
  ui_story_5007_50071102_15_dialog_content = "그 전쟁은 이미 끝났어. 나도 더는 군인이 아니라고...",
  ui_story_5007_50071102_16_dialog_content = "그러니 내가 어떻게 되든 상관없잖아.",
  ui_story_5007_50071102_17_dialog_content = "상관이 없어?",
  ui_story_5007_50071102_18_dialog_content = "이름 높은 전사가 자길 이런 꼴로 만들고 있다니.",
  ui_story_5007_50071102_19_dialog_content = "네 싸움의 재능을 얼마나 많은 사람들이 부러워하는지는 아나?",
  ui_story_5007_50071102_20_dialog_content = "뭐가 싸움의 재능이냐... 아무짝에도 쓸모없다고.",
  ui_story_5007_50071102_21_dialog_content = "나는 내 전우조차 구하지 못한 놈이다.",
  ui_story_5007_50071102_22_dialog_content = "...그 고아, 한눈에 알아볼 수 있었다. 누가 봐도 녀석의 딸이었지.",
  ui_story_5007_50071102_23_dialog_content = "하지만 난 그 애에게 가서 말해줄 용기가 없었다...",
  ui_story_5007_50071102_24_dialog_content = "난 암귀가 버나드의 몸을 꿰뚫는 모습을 눈앞에서 봤다.",
  ui_story_5007_50071102_25_dialog_content = "구하지 못했다고.",
  ui_story_5007_50071102_26_dialog_content = "버나드는 일루미나를 위해 목숨을 바친 거다!",
  ui_story_5007_50071102_27_dialog_content = "녀석은 원래 살아남아서 영웅이 됐어야 했어.",
  ui_story_5007_50071102_28_dialog_content = "자신이 원하던 영웅이 돼서, 모두를 승리로 이끌 수 있었다고.",
  ui_story_5007_50071102_29_dialog_content = "패배와 함께 죽을 녀석이 아니었단 말이다.",
  ui_story_5007_50071102_30_dialog_content = "하지만 버나드는 우릴 구하고, 수많은 사람들을 구했지. 틀림없는 영웅이야.",
  ui_story_5007_50071102_31_dialog_content = "영웅이란 주변 사람들에게 영향을 미치는 법이다.\n난 녀석의 신념이 네 마음속에도 분명히 남아 있을 거라 생각한다.",
  ui_story_5007_50071102_32_dialog_content = "그저 너 자신이 눈치채지 못했을 뿐이지.",
  ui_story_5007_50071102_33_dialog_content = "우리 소대 편성 때 생각도 나더군...",
  ui_story_5007_50071102_34_dialog_content = "이번에 편성한 24호 지하성 소대에는 너와 레비 둘 다 필요하다.",
  ui_story_5007_50071102_35_dialog_content = "지금까지 레비와 제대로 얘기를 나눠본 적 없었겠지.",
  ui_story_5007_50071102_36_dialog_content = "내가 너희를 소개시켜 주마.",
  ui_story_5007_50071102_37_dialog_content = "레비, 이쪽의 커다란 전사는 그람이다.",
  ui_story_5007_50071102_38_dialog_content = "너도 와서 그람한테 널 소개해라.",
  ui_story_5007_50071102_39_dialog_content = "내가 바로 레비야!",
  ui_story_5007_50071102_40_dialog_content = "너 말이야... 자기소개도 할 줄 모르는 거냐?",
  ui_story_5007_50071102_41_dialog_content = "난 분명히 당신보다 강해!",
  ui_story_5007_50071102_42_dialog_content = "싸움이라면 난 절대 지지 않아! 나이가 많다고 절대 봐주지 않아!",
  ui_story_5007_50071102_43_dialog_content = "뭘 싸운다는 거냐. 난 두 사람을 서로 소개해 주려던 거다.",
  ui_story_5007_50071102_44_dialog_content = "재미없어. 훈련해야 돼. 그만 놀래!",
  ui_story_5007_50071102_45_dialog_content = "기다려라. 네 아버지 버나드 얘기, 듣고 싶지 않은 거냐?",
  ui_story_5007_50071102_46_dialog_content = "우리 아버지? 무슨 말을 하려는 건데...",
  ui_story_5007_50071102_47_dialog_content = "그렇게 경계할 거 없다.",
  ui_story_5007_50071102_48_dialog_content = "사실 우리 둘은 모두 네 아버지의 오랜 전우였다. 너의 아버지는 영웅이었지.",
  ui_story_5007_50071102_49_dialog_content = "아버지가 영웅이었던 것도 알고, 대단했다는 것도 알고 있어.\n그리고 전우는 더 대단했다고 들었어!",
  ui_story_5007_50071102_50_dialog_content = "그래서 당신이 바로 그 대단한 전우야?",
  ui_story_5007_50071102_51_dialog_content = "아니, 난 네 아버지만큼 강하지 않다.",
  ui_story_5007_50071102_52_dialog_content = "당신들이 아버지와 무슨 사이였는지는 관심 없어.",
  ui_story_5007_50071102_53_dialog_content = "내가 관심 있는 건 지금 내가 충분히 강한지,\n영웅이라는 아버지를 넘어설 수 있는지뿐이야!",
  ui_story_5007_50071102_54_dialog_content = "레비는 방금 전까지 계속 날뛰고 있어서 내가 타일렀다.\n이젠 녀석도 침착하게 너와 인사할 수 있을 거다.",
  ui_story_5007_50071102_55_dialog_content = "난 용감해. 나는 계속 전사처럼 싸워왔어. 난 강해. 그리고 난 약속을 지켰어.",
  ui_story_5007_50071102_56_dialog_content = "난 계속 그 목표를 향해 열심히 싸워왔어...",
  ui_story_5007_50071102_57_dialog_content = "그리고 이젠 모두가 당신을 영웅이라고 말하고 있어...\n내가 넘어야 할 목표가 하나 더 늘어나 버렸어.",
  ui_story_5007_50071102_58_dialog_content = "......",
  ui_story_5007_50071102_59_dialog_content = "용사 별동대의 전통에 따라, 네 인식표는 내가 가져가마.",
  ui_story_5007_50071102_60_dialog_content = "이럴 때 네가 뭐라고 할지 알고 있다.",
  ui_story_5007_50071102_61_dialog_content = "넌 분명 그렇게 말하겠지...",
  ui_story_5007_50071102_62_dialog_content = "「계속 싸워라.」",
  ui_story_5007_50071102_63_dialog_content = "「모든 승리가 찾아올 때까지.」",
  ui_story_5007_50071102_64_dialog_content = "「모든 암귀가 쓰러질 때까지.」",
  ui_story_5007_50071102_65_dialog_content = "「여명의 빛을 위해, 계속 싸워라...」",
  ui_story_5007_50071102_66_dialog_content = "「우리는 반드시, 최후의 승리를 거둘 것이다...」",
  ui_story_5007_50071102_67_dialog_content = "「그 모습을 지켜보는 임무는...」",
  ui_story_5007_50071102_68_dialog_content = "「너희에게 맡긴다!」",
  ui_story_5007_50071102_69_dialog_content = "......",
  ui_story_5007_50071102_70_dialog_content = "브랜트가 하려던 이야기는... 여기까지다.",
  ui_story_5007_50071201_1_dialog_content = "싸움은 아직 끝나지 않았다...",
  ui_story_5007_50071201_2_dialog_content = "자, 우선 콜로서스로 가자고.",
  ui_story_5007_50071201_3_dialog_content = "어라? 레비, 어디 가?",
  ui_story_5007_50071201_4_dialog_content = "신경 꺼...",
  ui_story_5007_50071201_5_dialog_content = "레비가 계속 콜로서스의 방에만 틀어박혀 있어요. 노크를 해도 나오질 않아요...",
  ui_story_5007_50071201_6_dialog_content = "브랜트의 죽음은 그 아이에겐 큰 충격이었을 거다.",
  ui_story_5007_50071201_7_dialog_content = "의지가 꺾이더라도 이상할 게 없겠지.",
  ui_story_5007_50071201_8_dialog_content = "그람 씨는요? 정말 괜찮아요?",
  ui_story_5007_50071201_9_dialog_content = "나 말이냐?",
  ui_story_5007_50071201_10_dialog_content = "너흰 브랜트의 인식표에 뭐라고 새겨져 있었는지 모르겠지.",
  ui_story_5007_50071201_11_dialog_content = "난 지금 그저 한없이 화가 날 뿐이다. 그 녀석은 이미 모든 걸 계획해 뒀었거든.",
  ui_story_5007_50071201_12_dialog_content = "「기운 내라」, 인식표엔 그렇게 새겨져 있더군.",
  ui_story_5007_50071201_12X_dialog_content = "인식표를 전우에게 남겨주는 건 우리 용사 별동대의 전통이었다.",
  ui_story_5007_50071201_12X1_dialog_content = "녀석은 자기가 나보다 먼저 죽는 걸 보면... 내가 다시 일어서지 못할까 걱정했던 거다.",
  ui_story_5007_50071201_13_dialog_content = "레비는 어디 있지? 내가 가서 이야기를 좀 해 봐야겠어.",
  ui_story_5007_50071201_14_dialog_content = "제가 같이 찾아드릴게요.",
  ui_story_5007_50071201_15_dialog_content = "레비... 우리에겐 아직 해야 할 임무가 있다. 기운을 내라.",
  ui_story_5007_50071201_16_dialog_content = "......",
  ui_story_5007_50071201_17_dialog_content = "사실 아까 레비가 훌쩍거리는 소리를 들었어.",
  ui_story_5007_50071201_18_dialog_content = "레비, 내 말 들어라. 만약 브랜트였다면 분명히 너한테 이렇게 얘기했을 거다.",
  ui_story_5007_50071201_19_dialog_content = "레비, 왜 그러냐?",
  ui_story_5007_50071201_20_dialog_content = "난 어릴 때부터 아버지가 남들을 위해 목숨을 바친 걸 알고 있었어.",
  ui_story_5007_50071201_21_dialog_content = "난 많이 울지도 않았고, 아버지의 일에 대해서도 별로 관심은 없었어.",
  ui_story_5007_50071201_22_dialog_content = "난 그저 아버지를 뛰어넘는 영웅이 되고 싶었어.",
  ui_story_5007_50071201_23_dialog_content = "사람들은 다들 날 이상하다고 말했어.",
  ui_story_5007_50071201_24_dialog_content = "내가 생각도 없고, 감정도 없다고 말이야.",
  ui_story_5007_50071201_25_dialog_content = "책임관님도 내가 이상하다고 생각해?",
  ui_story_5007_50071201_26_dialog_content = "그렇지 않아, 레비.",
  ui_story_5007_50071201_27_dialog_content = "넌 결코 감정이 없는 게 아니야.",
  ui_story_5007_50071201_28_dialog_content = "오히려 네 마음은 아주 강하다.\n넌 아버지의 죽음이라는 사실로부터 도망치지 않았으니까.",
  ui_story_5007_50071201_29_dialog_content = "오히려 용기를 내서 더 높은 목표를 향해 노력하고 있지.",
  ui_story_5007_50071201_30_dialog_content = "강자는 힘든 일을 겪더라도 다시 일어나 용감하게 싸우는 법이다!",
  ui_story_5007_50071201_31_dialog_content = "난 용감해. 무섭지도 않아.",
  ui_story_5007_50071201_32_dialog_content = "당신들 용사 별동대에는 한 사람이 더 있었다고 들었어.",
  ui_story_5007_50071201_33_dialog_content = "다들 그 사람은 전장에서 도망쳤다고 그랬어.",
  ui_story_5007_50071201_34_dialog_content = "그 사람은 약한 거지?",
  ui_story_5007_50071201_35_dialog_content = "그것도 아니다.",
  ui_story_5007_50071201_36_dialog_content = "사람의 힘은 저마다 다른 법이다.",
  ui_story_5007_50071201_37_dialog_content = "그람도 아주 강한 녀석이다. 너도 언젠가 보게 될 거다.",
  ui_story_5007_50071201_38_dialog_content = "우린 저마다의 싸움을 하고 있는 거다.",
  ui_story_5007_50071201_39_dialog_content = "인생이라는 이름의 전장에서 말이다.",
  ui_story_5007_50071201_40_dialog_content = "수없이 쓰러지지만, 그래도 다시 일어선다!",
  ui_story_5007_50071201_41_dialog_content = "「너흰 앞으로도 계속 싸우면서, 일루미나를 지켜나갈 거다!」",
  ui_story_5007_50071201_42_dialog_content = "그러니까, 레비...",
  ui_story_5007_50071201_43_dialog_content = "시끄러워! 내 추억을 방해하지 마!",
  ui_story_5007_50071201_44_dialog_content = "난 멀쩡하다고! 방금 전엔... 그냥 자고 있었던 거야! 이젠 괜찮아!",
  ui_story_5007_50071201_45_dialog_content = "어떤 임무야? 바로 말해!",
  ui_story_5007_50071201_46_dialog_content = "수송대의 임무를 돕고, 사막 방어선을 지원할 거다.",
  ui_story_5007_50071201_47_dialog_content = "암귀의 목표에는 이 화물들이 포함돼 있을 가능성이 높다.\n이걸 빼앗으려는 건지, 파괴하려고 하는 건지는 모르겠지만 말이다.",
  ui_story_5007_50071201_48_dialog_content = "우린 이걸 목적지까지 전달할 필요가 있다.",
  ui_story_5007_50071201_49_dialog_content = "하지만 우리가 지금 운반하는 건 예비 부품이에요.",
  ui_story_5007_50071201_50_dialog_content = "어쩌면 23호 지하성에도 이게 필요하지 않을지도 몰라요.\n그런데도 암귀가 이걸 왜 노리는 걸까요?",
  ui_story_5007_50071201_51_dialog_content = "그 암귀는 그저 상자에 손을 뻗었을 뿐이야.\n그것만 가지고는 놈들이 장치를 노린다고 단정 지을 순 없어.",
  ui_story_5007_50071201_52_dialog_content = "아니면 그냥 우리가 생각이 너무 많았던 걸까요?",
  ui_story_5007_50071201_53_dialog_content = "어쨌든 우린 이 일을 상부에 보고할 수밖에 없다. 자세한 판단은 상부에 맡기자고.",
  ui_story_5007_50071201_54_dialog_content = "우리가 할 일은 자신의 임무를 완수하는 것뿐이다. 지금 해야 할 일을 하면 되는 거다.",
  ui_story_5007_50071201_55_dialog_content = "하지만 최악의 경우는 목적지인 23호 지하성이 이미 암귀한테 함락당한 상황이겠죠.",
  ui_story_5007_50071201_56_dialog_content = "23호 지하성이 함락됐다면 21호나 22호 지하성으로 가면 된다.",
  ui_story_5007_50071201_57_dialog_content = "어딘가에 이걸 필요로 하는 곳이 있을 거다!",
  ui_story_5007_50071201_58_dialog_content = "<color=#e8d9bb>23호 지하성 안.</color>",
  ui_story_5007_50071201_59_dialog_content = "성벽의 상태는 어떤가!",
  ui_story_5007_50071201_60_dialog_content = "육안 식별 손상도는 20%, 앞으로 견딜 수 있는 자폭 공격은 십여 번이 한계입니다!",
  ui_story_5007_50071201_61_dialog_content = "남은 인원과 탄약을 계산해 보고하라!",
  ui_story_5007_50071201_62_dialog_content = "예!",
  ui_story_5007_50071201_63_dialog_content = "<color=#FFB400>3호 에너지 장치</color>는 어떻게 됐지?",
  ui_story_5007_50071201_64_dialog_content = "보고드립니다. 화재는 진압됐고 현재 긴급 수리 중입니다!",
  ui_story_5007_50071201_65_dialog_content = "이대로는 습격을 견딜 수 없을지도 모릅니다...",
  ui_story_5007_50071201_66_dialog_content = "다른 지하성의 상황은? 제3군단 지원군은 어디 있지?",
  ui_story_5007_50071201_67_dialog_content = "연락이 되질 않습니다!",
  ui_story_5007_50071201_68_dialog_content = "보고드립니다! 모래폭풍이 또 몰려오고 있습니다!",
  ui_story_5007_50071201_69_dialog_content = "또 시작이냐!",
  ui_story_5007_50071201_70_dialog_content = "예! 모래폭풍의 영향으로 다른 군단이나 지하성과 연락을 취할 수 없는 상황입니다...",
  ui_story_5007_50071201_71_dialog_content = "지하성 안에 틀어박혀 있을 수밖에 없단 말인가... 답답해 미치겠군!",
  ui_story_5007_50071301_1_dialog_content = "<color=#e8d9bb>「경고, 모래폭풍이 감지되었습니다. 비행 고도를 높이십시오.」</color>",
  ui_story_5007_50071301_2_dialog_content = "어쩌지? 모래바람 속에서 착륙해야 되는 거야?",
  ui_story_5007_50071301_3_dialog_content = "이제 곧 23호 지하성 상공에 도착할 거야.",
  ui_story_5007_50071301_4_dialog_content = "아래는 쥐죽은 듯이 조용해. 대포 소리도 안 들려.",
  ui_story_5007_50071301_5_dialog_content = "설마 벌써 함락된 건 아니겠지?",
  ui_story_5007_50071301_6_dialog_content = "아니, 일루미나의 깃발이 흐릿하게 보이고 있어.",
  ui_story_5007_50071301_7_dialog_content = "<color=#FFB400>깃발이 있다</color>는 건 지하성이 함락되지 않았다는 뜻이야.",
  ui_story_5007_50071301_8_dialog_content = "그걸로 어떻게 판단하는데?",
  ui_story_5007_50071301_9_dialog_content = "깃발의 상태도 일루미나에서 사용하는 일종의 「암호」거든.",
  ui_story_5007_50071301_10_dialog_content = "일단은 착륙하지 마라.",
  ui_story_5007_50071301_11_dialog_content = "고도를 낮추면 곧 암귀에게 들킬 거다.",
  ui_story_5007_50071301_12_dialog_content = "우선 23호 지하성의 방어선 구역을 따라 상공을 돌아보자고.",
  ui_story_5007_50071301_13_dialog_content = "PlayerName 넌 암귀를 감응해낼 수 있고, 게다가 지금은 모래폭풍이 불고 있지.",
  ui_story_5007_50071301_14_dialog_content = "정찰이든 기습이든 우리 쪽이 유리하다.",
  ui_story_5007_50071301_15_dialog_content = "네. 아래쪽의 상황은 이미 감응했어요.",
  ui_story_5007_50071301_16_dialog_content = "암귀들의 공격성도 강하지 않고, 움직임도 둔해요.",
  ui_story_5007_50071301_17_dialog_content = "크윽...",
  ui_story_5007_50071301_18_dialog_content = "PlayerName, 괜찮아? 또 감응 능력을 너무 많이 써서 그래?",
  ui_story_5007_50071301_19_dialog_content = "머리에 열이 좀 나는 것 같은데... 체온을 식힐 만한 걸 좀 갖다줄래?",
  ui_story_5007_50071301_20_dialog_content = "열이 난다고?",
  ui_story_5007_50071301_21_dialog_content = "수건 가져올게!",
  ui_story_5007_50071301_22_dialog_content = "고마워...",
  ui_story_5007_50071301_23_dialog_content = "아래쪽 상황이 뭔가 이상해요. 대규모의 암귀가 전장에 흩어져 있어요.",
  ui_story_5007_50071301_24_dialog_content = "게다가 방어선의 후방에도 다수의 암귀가 있어요...",
  ui_story_5007_50071301_25_dialog_content = "어쩌면 지하성을 포위 공격할 타이밍을 기다리고 있을지도 모르겠군.",
  ui_story_5007_50071301_26_dialog_content = "다른 전장에서 합류한 암귀들 때문에 성의 방어가 상당히 어려워졌을 거다.",
  ui_story_5007_50071301_27_dialog_content = "우선 이대로 후방 진지에 착륙해 후방의 암귀를 곧바로 습격하는 방법이 있다.",
  ui_story_5007_50071301_28_dialog_content = "우리 몇 명만으로 말이야? 그건 너무 위험해.",
  ui_story_5007_50071301_29_dialog_content = "알고 있다. 하지만 전쟁에서 기회란 한순간뿐이다.\n놈들이 공격을 시작하고 나면 때는 늦는다.",
  ui_story_5007_50071301_30_dialog_content = "이 전법의 위험성은 나도 잘 알고 있다.",
  ui_story_5007_50071301_31_dialog_content = "하지만 나의 경험이 말해주고 있다. 시도해 볼 가치는 있다.",
  ui_story_5007_50071301_32_dialog_content = "알겠어요. 저도 같이 갈게요.",
  ui_story_5007_50071301_33_dialog_content = "PlayerName, 넌 아직 열이 있잖아. 휴식이 필요해.",
  ui_story_5007_50071301_34_dialog_content = "별일 아니야. 그냥 머리가 조금 뜨거울 뿐이지...",
  ui_story_5007_50071301_35_dialog_content = "그리고 지금 왠지 <color=#FFB400>내 감응 능력이 더 강해진</color> 것 같은 느낌이 들어.",
  ui_story_5007_50071301_36_dialog_content = "작전 수립자로서 나도 네가 우리와 함께 움직이는 게 좋다고 생각한다.",
  ui_story_5007_50071301_37_dialog_content = "PlayerName 네가 있다면 모두의 전력이 대폭 향상될 테니 말이다.",
  ui_story_5007_50071301_38_dialog_content = "비록 이번 작전에는 상당한 위험이 따르겠지만,\n나와 레비가 최선을 다해 널 지킬 거다. 우릴 믿어라.",
  ui_story_5007_50071301_39_dialog_content = "맞아. 브랜트 책임관님한테 약속했어!",
  ui_story_5007_50071301_40_dialog_content = "저도 물론 두 사람을 믿어요!",
  ui_story_5007_50071301_41_dialog_content = "휴, 그럼 콜로서스 조종은 또 내가 맡아야 되는 거네...",
  ui_story_5007_50071301_42_dialog_content = "카렌, PlayerName 잘 부탁해.",
  ui_story_5007_50071301_43_dialog_content = "알겠어. 함께 싸우지 못하는 게 네겐 더 힘든 모양이구나.",
  ui_story_5007_50071301_44_dialog_content = "응. 그래도 어쩔 수 없지. PlayerName도 결정한 일이니까.",
  ui_story_5007_50071301_45_dialog_content = "대신 나도 콜로서스를 빠르게 조종해서 23호 지하성에 화물을 전달할게!",
  ui_story_5007_50071301_46_dialog_content = "그리고 재빨리 돌아와서 상공에서 모두를 기다리고 있을게.",
  ui_story_5007_50071301_47_dialog_content = "좋다. 그럼 콜로서스를 암귀의 후방에 착륙시키는 거다.",
  ui_story_5007_50071301_48_dialog_content = "기습 부대의 주요 인원은 나, 레비, 카렌, 비다로 정하겠다.",
  ui_story_5007_50071301_49_dialog_content = "전투 지휘는 PlayerName, 전술 지휘는 내가 맡는다.",
  ui_story_5007_50071301_50_dialog_content = "다른 병사들은 명령에 따라 움직이도록!",
  ui_story_5007_50071301_51_dialog_content = "강하 기습 작전을 개시한다!",
  ui_story_5007_50071301_52_dialog_content = "후방 진지 상공에 도착했어요! 강하를 시작할 수 있어요!",
  ui_story_5007_50071301_53_dialog_content = "강하 개시!",
  ui_story_5007_50071301_54_dialog_content = "아래에서 콜로서스를 발견한 암귀는 우리가 단번에 처리한다.",
  ui_story_5007_50071301_55_dialog_content = "그람 씨, 전 못 뛰어내리니까 저번처럼 붙잡고 가 줘요.",
  ui_story_5007_50071301_55X_dialog_content = "좋다. 내가 데려가마. 나머지 사람들은 각자 방법대로 내려간다.",
  ui_story_5007_50071301_56_dialog_content = "콜로서스에도 밧줄이 있으니까 필요한 사람은 써도 좋아.",
  ui_story_5007_50071301_57_dialog_content = "알겠어.",
  ui_story_5007_50071301_58_dialog_content = "이렇게 한 손으로 들리면 확실히 병아리가 된 것 같잖아...",
  ui_story_5007_50071301_59_dialog_content = "창피하게 말이야.",
  ui_story_5007_50071301_60_dialog_content = "왜 그 아저씨한테 안기는 건데?",
  ui_story_5007_50071301_61_dialog_content = "나! 내가 안을래! 나도 강해! 나도 잘 뛰어내려!",
  ui_story_5007_50071301_62_dialog_content = "그만 좀 해! 더 창피해지잖아! 나도 어쩔 수 없다고!",
  ui_story_5007_50071301_63_dialog_content = "간다.",
  ui_story_5007_50071301_64_dialog_content = "으아아아아아악!",
  ui_story_5007_50071301_65_dialog_content = "역시 이런 건 못 견디겠다고오오오──!",
  ui_story_5007_50071302_1_dialog_content = "23호 지하성 상공에 도착했어! 착륙 준비!",
  ui_story_5007_50071302_2_dialog_content = "잠깐만! 아직 아무 연락도 안 했잖아.",
  ui_story_5007_50071302_3_dialog_content = "이대로 내려가면 위험해.",
  ui_story_5007_50071302_4_dialog_content = "암귀한테 공격받으니까?",
  ui_story_5007_50071302_5_dialog_content = "아니, 방어선의 병사들한테 공격당할지도 몰라...",
  ui_story_5007_50071302_6_dialog_content = "......",
  ui_story_5007_50071302_7_dialog_content = "아니면 내기를 해볼까요?",
  ui_story_5007_50071302_8_dialog_content = "만약 방어선에도 콜로서스에 대해 아는 사람이 있다면요?\n그래서 공격해 오지 않는다면요?",
  ui_story_5007_50071302_9_dialog_content = "또 시작이네. 말하기 전에 생각부터 좀 할 순 없는 거야?",
  ui_story_5007_50071302_10_dialog_content = "네가 가져온 확성기는 장식이야?",
  ui_story_5007_50071302_11_dialog_content = "아, 그렇네요. 까먹을 뻔했어요!",
  ui_story_5007_50071302_12_dialog_content = "그럼 콜로서스의 문을 열어주세요!",
  ui_story_5007_50071302_13_dialog_content = "23호 지하성 사람들! 잘 들어라!",
  ui_story_5007_50071302_14_dialog_content = "너흰 이미 암귀에게 포위당했다!",
  ui_story_5007_50071302_15_dialog_content = "그렇게 말하면 뭔가 이상하다는 생각 안 들어?!",
  ui_story_5007_50071302_16_dialog_content = "당황하지 마세요!",
  ui_story_5007_50071302_17_dialog_content = "우린 여러분을 도우러 왔어요!",
  ui_story_5007_50071302_18_dialog_content = "착륙시켜 주세요!",
  ui_story_5007_50071302_19_dialog_content = "아까 두 번째 말을 한 뒤에 저쪽이 우릴 공격했어도 이상할 게 없었을 거야.",
  ui_story_5007_50071302_20_dialog_content = "근데 벌써 수십 초가 지났는데 공격을 안 하고 있어.",
  ui_story_5007_50071302_21_dialog_content = "착륙해도 괜찮을 것 같아.",
  ui_story_5007_50071302_22_dialog_content = "문을 열어라! 나와라!",
  ui_story_5007_50071302_23_dialog_content = "여러분! 우린 지원을 온 거예요. 수송대의 화물도 가져왔어요.",
  ui_story_5007_50071302_24_dialog_content = "우선 제 말 좀 들...",
  ui_story_5007_50071302_25_dialog_content = "조용히 해. 우리한테 해명해도 소용없다.",
  ui_story_5007_50071302_26_dialog_content = "뭐야, 왜 다들 우리한테 총을 겨누고 있는 거야?",
  ui_story_5007_50071302_27_dialog_content = "상부의 명령이다.",
  ui_story_5007_50071302_28_dialog_content = "지휘관이 누구죠?",
  ui_story_5007_50071302_29_dialog_content = "23호 지하성의 허가도 없이 멋대로 착륙하다니!",
  ui_story_5007_50071302_30_dialog_content = "대체 무슨 생각이냐! 누가 보낸 거지?",
  ui_story_5007_50071302_31_dialog_content = "바튼 님!",
  ui_story_5007_50071302_32_dialog_content = "인사는 됐어! 질문에 대답해!",
  ui_story_5007_50071302_33_dialog_content = "군단장님, 특수 상황이에요. 이건 24호 지하성 책임관의 상황 설명서예요.",
  ui_story_5007_50071302_34_dialog_content = "얼른 줘봐!",
  ui_story_5007_50071302_35_dialog_content = "......",
  ui_story_5007_50071302_36_dialog_content = "됐다. 상황은 이해했다. 모두 총을 내려라!",
  ui_story_5007_50071302_37_dialog_content = "병사들은 콜로서스에 가서 수송대가 가져온 예비 부품을 옮겨라!",
  ui_story_5007_50071302_38_dialog_content = "지금 즉시 3호 에너지 장치 쪽으로 보내 엔지니어에게 수리가 가능한지 확인하도록 해라!",
  ui_story_5007_50071302_39_dialog_content = "예!",
  ui_story_5007_50071302_40_dialog_content = "3호 에너지 장치에 무슨 문제라도 있었나요?",
  ui_story_5007_50071302_41_dialog_content = "불이 났다. 지금은 수리 중이다.",
  ui_story_5007_50071302_42_dialog_content = "전 블랙 엄브렐라 연구소의 안시아예요. 제가 도와드릴게요.",
  ui_story_5007_50071302_43_dialog_content = "그럼 넌 저쪽 병사들과 함께 3호 장치 쪽으로 가라.",
  ui_story_5007_50071302_44_dialog_content = "나머지는 날 따라온다.",
  ui_story_5007_50071302_45_dialog_content = "24호 지하성의 상황을 상세히 보고해라.",
  ui_story_5007_50071302_46_dialog_content = "바튼 님, 그 전에 긴급히 보고드릴 일이 있어요!",
  ui_story_5007_50071302_47_dialog_content = "저희 일부 소대가 지금 적의 후방으로 침투해 기습 중이에요!",
  ui_story_5007_50071302_48_dialog_content = "암귀의 진형이 흐트러지면 23호 지하성도 반격을 가할 수 있을 거예요!",
  ui_story_5007_50071302_49_dialog_content = "전 지금 바로 기습을 진행할 작전 지역 상공으로 돌아가서\n동료들을 기다려야 해요!",
  ui_story_5007_50071302_50_dialog_content = "뭐라고?!",
  ui_story_5007_50071302_51_dialog_content = "겨우 몇 개 소대로 적진의 후방에 기습 공격을 감행했다고?",
  ui_story_5007_50071302_52_dialog_content = "어떤 책임자가 그런 작전을 세운 거냐?!",
  ui_story_5007_50071302_53_dialog_content = "작전이 성공한 것 같아요!",
  ui_story_5007_50071302_54_dialog_content = "암귀들이 이쪽으로 몰려오는 걸 느꼈어요!",
  ui_story_5007_50071302_55_dialog_content = "아직 상대의 주의를 끄는 데 성공했을 뿐이다.",
  ui_story_5007_50071302_56_dialog_content = "전원 예정 지점으로 이동한다!",
  ui_story_5007_50071302_57_dialog_content = "비다! 암귀가 예정 지점에 도착했다!",
  ui_story_5007_50071302_58_dialog_content = "준비됐어요! 지뢰 폭발!",
  ui_story_5007_50071302_59_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5007_50071302_60_dialog_content = "유인해 온 암귀 무리도 벌써 네 번째야.",
  ui_story_5007_50071302_61_dialog_content = "이 전쟁터의 암귀는 우리가 예상했던 것보다 훨씬 많군.",
  ui_story_5007_50071302_62_dialog_content = "비다, 신호탄을 쏴라! 콜로서스 쪽에 우릴 데리러 오라고 알려라!",
  ui_story_5007_50071302_63_dialog_content = "<color=#e8d9bb>휘이잉─── 펑!</color>",
  ui_story_5007_50071302_64_dialog_content = "암귀가 곧 여기로 몰려올 거다. 다시 진지를 옮겨야 한다!",
  ui_story_5007_50071302_65_dialog_content = "콜로서스가 상공에 도착하면 다시 신호탄을 발사해서\n바이스에게 우리의 위치를 알리는 거다!",
  ui_story_5007_50071302_66_dialog_content = "캬악──!",
  ui_story_5007_50071302_67_dialog_content = "전류 참격!",
  ui_story_5007_50071302_68_dialog_content = "PlayerName! 이동 경로상의 암귀는 내가 다 쓰러트렸어!",
  ui_story_5007_50071302_69_dialog_content = "크오오──!",
  ui_story_5007_50071302_70_dialog_content = "정면! 다섯 번째 암귀 무리가 온다! 다들 준비해!",
  ui_story_5007_50071302_71_dialog_content = "그르르...",
  ui_story_5007_50071302_72_dialog_content = "잠깐만! 뒤쪽에서도 암귀가 오고 있어!",
  ui_story_5007_50071302_73_dialog_content = "속도가 아주 빨라!",
  ui_story_5007_50071302_74_dialog_content = "남은 거리는?",
  ui_story_5007_50071302_75_dialog_content = "2km도 안 돼요!",
  ui_story_5007_50071302_76_dialog_content = "모두 들어라!",
  ui_story_5007_50071302_77_dialog_content = "5차 교전은 포기하고, 지뢰를 매설해 둔 동쪽으로 퇴각한다!",
  ui_story_5007_50071302_78_dialog_content = "예!",
  ui_story_5007_50071302_79_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5007_50071302_80_dialog_content = "함정이 폭발했습니다! 암귀를 모두 섬멸했어요!",
  ui_story_5007_50071302_81_dialog_content = "좋아! 동쪽을 향해 퇴각하라!",
  ui_story_5007_50071302_82_dialog_content = "PlayerName! 콜로서스와 감응할 수 있나?",
  ui_story_5007_50071302_83_dialog_content = "네! 지금 이쪽으로 오고 있어요!",
  ui_story_5007_50071302_84_dialog_content = "신호를 보내! 그동안 근처의 암귀를 모조리 쓰러트린다!",
  ui_story_5007_50071302_85_dialog_content = "콜로서스의 착륙을 방해하게 두지 마라!",
  ui_story_5007_50071302_86_dialog_content = "예!",
  ui_story_5007_50071302_87_dialog_content = "캬악──!",
  ui_story_5007_50071302_88_dialog_content = "그람 씨! 움직임이 빠른 암귀 무리가 우릴 쫓아오고 있어요!",
  ui_story_5007_50071302_89_dialog_content = "레비! 나와 함께 후방을 차단한다!",
  ui_story_5007_50071302_90_dialog_content = "저도 도울게요!",
  ui_story_5007_50071302_91_dialog_content = "크오오──!",
  ui_story_5007_50071302_92_dialog_content = "거기 밑에! 비켜!",
  ui_story_5007_50071302_93_dialog_content = "그르르?",
  ui_story_5007_50071302_94_dialog_content = "<color=#e8d9bb>쿵!</color>",
  ui_story_5007_50071302_95_dialog_content = "하늘에서 떨어져서 암귀를 짓밟았어?!",
  ui_story_5007_50071302_96_dialog_content = "휴... 위험했군...",
  ui_story_5007_50071302_97_dialog_content = "떨어져 죽는 건 아닌가 했는데, 암귀가 쿠션이 돼서 살았다.",
  ui_story_5007_50071302_98_dialog_content = "바튼 씨?!",
  ui_story_5007_50071302_99_dialog_content = "하하, PlayerName, 기운이 넘쳐 보이는군!",
  ui_story_5007_50071302_100_dialog_content = "바튼 씨 때문에 깜짝 놀란 거라구요!",
  ui_story_5007_50071302_101_dialog_content = "<color=#e8d9bb>쿵! 쿵! 쿵! 쿵!</color>",
  ui_story_5007_50071302_102_dialog_content = "뭐, 순식간에 지원군이 하늘에서 잔뜩 떨어졌는데 기운이 안 넘칠 리가 없겠죠!",
  ui_story_5007_50071302_103_dialog_content = "하하, 그러면 됐다!",
  ui_story_5007_50071302_104_dialog_content = "돌격대! 주변의 암귀를 섬멸하라!",
  ui_story_5007_50071302_105_dialog_content = "캬아악!",
  ui_story_5007_50071302_106_dialog_content = "크르르!",
  ui_story_5007_50071302_107_dialog_content = "우와... 저 사람들 정말 대단하네요!",
  ui_story_5007_50071302_108_dialog_content = "훌륭한 솜씨네. 주변의 암귀가 순식간에 모두 쓰러졌어.",
  ui_story_5007_50071302_109_dialog_content = "그거야 당연하지! 내 제2군단 병사들은 지하성 안에서 하루 종일 갇혀 있었으니까!",
  ui_story_5007_50071302_110_dialog_content = "암귀와 싸울 수 있다고 하면 누구라도 기운이 넘치게 된다고.",
  ui_story_5007_50071302_111_dialog_content = "그런데 너희들...",
  ui_story_5007_50071302_112_dialog_content = "후방 기습 같은 걸 어떻게 나한테 미리 알리지 않을 수가 있지?!",
  ui_story_5007_50071302_113_dialog_content = "이런 정신 나간 작전에 이 바튼이 어떻게 참가하지 않을 수 있겠나?!",
  ui_story_5007_50071302_114_dialog_content = "안 그런가? 용사 별동대의 그람!",
  ui_story_5007_50071302_115_dialog_content = "그 부대는 이미 존재하지 않는다. 그러니 그렇게 부를 거 없다.",
  ui_story_5007_50071302_116_dialog_content = "그람, 24호 지하성의 일은 바이스에게 들었다.",
  ui_story_5007_50071302_117_dialog_content = "난 지금까지 타인을 위로해 본 적이 없다.",
  ui_story_5007_50071302_118_dialog_content = "하지만 더 많은 일루미나인들이 당신들의 이름을 알게 되길 바란다!",
  ui_story_5007_50071302_119_dialog_content = "기왕 전장으로 돌아온 이상, 그 부대의 이름을 다시 드높이고 싶진 않은가?",
  ui_story_5007_50071302_120_dialog_content = "당신은 브랜트 못지않게 위로가 서툴군.",
  ui_story_5007_50071302_121_dialog_content = "크흠, 아무튼 이 얘기는 다음에 다시 하자고. 지금은 해야 할 일이 있으니까.",
  ui_story_5007_50071302_122_dialog_content = "모두 들어라!",
  ui_story_5007_50071302_123_dialog_content = "반격의 때가 왔다!",
  ui_story_5007_50071302_124_dialog_content = "저 멍청한 암귀들의 궁둥이를 힘껏 걷어차줘라!",
  ui_story_5007_50071302_125_dialog_content = "목표는 후방의 암귀를 완전히 소멸시키는 것이다!",
  ui_story_5007_50071302_126_dialog_content = "후방 진지를 탈환하라!",
  ui_story_5007_50071401_1_dialog_content = "전류! 돌격! 돌격!",
  ui_story_5007_50071401_2_dialog_content = "어이, 그람... 저 멋대로 뛰쳐나가는 꼬마는 당신들이 데려온 건가?",
  ui_story_5007_50071401_3_dialog_content = "브랜트가 가르친 아이다.",
  ui_story_5007_50071401_4_dialog_content = "하하. 머리는 나빠 보이지만 꽤 세잖아!",
  ui_story_5007_50071401_5_dialog_content = "당신이 단련시킨 병사들도 제법이군. 잠재력이 있어.",
  ui_story_5007_50071401_6_dialog_content = "모두 우리와 24호 지하성에서 함께 싸운 고참 신병들이다.",
  ui_story_5007_50071401_7_dialog_content = "「고참 신병」... 그건 어떤 병종이지?",
  ui_story_5007_50071401_8_dialog_content = "전쟁터에 나온 지 얼마 되지 않은 신병들이지만,\n모두 생사가 걸린 격전 끝에 승리를 거머쥔 자들이다.",
  ui_story_5007_50071401_9_dialog_content = "그렇군. 역시 전장은 군사를 단련시키는 가장 좋은 장소니 말이야.",
  ui_story_5007_50071401_10_dialog_content = "이 부대가 적의 배후에 파고든 것도 이해가 되는군. 모두 전투의 프로였잖아!",
  ui_story_5007_50071401_11_dialog_content = "난 무모한 용기에만 기대는 타입은 아니다.\n작전 계획은 모두 상황과 전력을 고려해 세우고 있다.",
  ui_story_5007_50071401_12_dialog_content = "그것보다 당신이야말로 지하성의 책임자가 후방으로 침투하다니, 괜찮은 건가?",
  ui_story_5007_50071401_13_dialog_content = "이기면 문제없잖아! 이기지 못하면 그땐 문제가 되는 거지!",
  ui_story_5007_50071401_14_dialog_content = "우리가 후방의 진지를 탈환하면 즉시 반격을 개시할 수 있을 거다!",
  ui_story_5007_50071401_15_dialog_content = "당신들은 전부 그렇게 전쟁터에서 떠드는 걸 좋아하는 건가?",
  ui_story_5007_50071401_16_dialog_content = "백야성의 호위대장이 이런 곳에 나타나는 것도 만만치 않게 이상한 일 아니겠나?",
  ui_story_5007_50071401_17_dialog_content = "PlayerName의 선택이니까. 나도 보고만 있을 순 없었어.",
  ui_story_5007_50071401_18_dialog_content = "그냥 지나가는 하얀 창병이라고 생각해줘.",
  ui_story_5007_50071401_19_dialog_content = "그럼 우리 대화는 신경 쓰지 말고, PlayerName 녀석이나 잘 지켜주라고.",
  ui_story_5007_50071401_20_dialog_content = "캬아악!",
  ui_story_5007_50071401_21_dialog_content = "조심해!",
  ui_story_5007_50071401_22_dialog_content = "전류 돌격! PlayerName한테서 떨어져!",
  ui_story_5007_50071401_23_dialog_content = "캬아악!",
  ui_story_5007_50071401_24_dialog_content = "고, 고마워...",
  ui_story_5007_50071401_25_dialog_content = "걱정하지 마. 내 전류는 계속 널 지켜보고 있으니까!",
  ui_story_5007_50071401_26_dialog_content = "난 주변의 암귀들을 없애고 올게. 넌 계속 멍때리고 있어.",
  ui_story_5007_50071401_27_dialog_content = "PlayerName, 여기서 뭘 멍하니 있는 거야?!",
  ui_story_5007_50071401_28_dialog_content = "암귀한테 공격당할 뻔했는데 피하지도 않으면 어떡해?",
  ui_story_5007_50071401_29_dialog_content = "어이, 이 혼돈의 전장은 너희가 평소 겪어 온 싸움과는 비교도 되지 않는다고.",
  ui_story_5007_50071401_30_dialog_content = "정신 바짝 차려! 진지하게 하라고!",
  ui_story_5007_50071401_31_dialog_content = "미안해요... 방금은 감응 능력을 썼을 뿐이에요.",
  ui_story_5007_50071401_32_dialog_content = "저쪽에서 강력한 다크매터가 다가오는 걸 느꼈어요...",
  ui_story_5007_50071401_33_dialog_content = "놈이 오고 있어요!",
  ui_story_5007_50071401_34_dialog_content = "구오오오...",
  ui_story_5007_50071401_35_dialog_content = "역겨운 다크매터가 느껴져요.",
  ui_story_5007_50071401_36_dialog_content = "24호 지하성에서 마주쳤던 그 암귀랑 똑같아요.",
  ui_story_5007_50071401_37_dialog_content = "...확실해요. 절대 잊을 수 없는 끔찍한 느낌...",
  ui_story_5007_50071401_38_dialog_content = "어떤 암귀였지?",
  ui_story_5007_50071401_39_dialog_content = "거대하고 하늘을 날 수 있는 우두머리급 암귀였다.\n엄청난 힘을 지니고 있었지. 쓰러트리기도 힘들었어.",
  ui_story_5007_50071401_40_dialog_content = "뭐? 거대하고 하늘을 날아? 그럼 그냥 살아있는 표적 아냐?",
  ui_story_5007_50071401_41_dialog_content = "<color=#e8d9bb>펑! 퍼엉!</color>",
  ui_story_5007_50071401_42_dialog_content = "저 감동적인 포격 소리가 들리니? 정말 끝내주게 시끄럽지!",
  ui_story_5007_50071401_43_dialog_content = "안 돼요! 평범한 포격으로는 놈을 쓰러트릴 수 없어요!",
  ui_story_5007_50071401_44_dialog_content = "서둘러 지하성으로 가야겠어요. 놈은 지하성을 습격할지도 몰라요!",
  ui_story_5007_50071401_45_dialog_content = "평범한 포격?",
  ui_story_5007_50071401_46_dialog_content = "너 아무래도 일루미나 방어선의 장비에 뭔가 오해가 있는 것 같은데 말이지.",
  ui_story_5007_50071401_47_dialog_content = "내 23호 지하성에 배치되어 있는 건 중장갑 암귀 전용 <color=#FFB400>AA-88 요새포</color>다!\n2年前",
  ui_story_5007_50071401_48_dialog_content = "이동할 수 없고 장전에도 시간이 걸리긴 하지만.",
  ui_story_5007_50071401_49_dialog_content = "위력은 그 무엇보다도 강하지. 어떤 암귀라도 산산조각 낼 수 있다고!",
  ui_story_5007_50071401_50_dialog_content = "저 소리가 들리나? 저게 바로...",
  ui_story_5007_50071401_51_dialog_content = "어떤 대포든 그 암귀한테는 효과가 없어요! 감응으로 느낀 거라구요!",
  ui_story_5007_50071401_52_dialog_content = "제 말대로 해요! 지금 즉시 지하성으로 돌아가라는 명령을 내려줘요!",
  ui_story_5007_50071401_53_dialog_content = "너... 알았다. 네 감응 능력을 믿도록 하지.",
  ui_story_5007_50071401_54_dialog_content = "베니, 쿠로! 명령을 내리겠다!",
  ui_story_5007_50071401_55_dialog_content = "네! 군단장님!",
  ui_story_5007_50071401_56_dialog_content = "너희 둘은 3개 소대 병력을 데리고 이곳을 지켜라.\n모처럼 되찾은 진지니까 다시 놓칠 순 없지.",
  ui_story_5007_50071401_57_dialog_content = "나머지는 나와 함께 즉시 돌아간다! 23호 지하성의 후문으로 간다!",
  ui_story_5007_50071501_1X_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5007_50071501_1_dialog_content = "캬악──!",
  ui_story_5007_50071501_2_dialog_content = "방금 폭발은 뭐지? 성벽은 괜찮은 거냐?",
  ui_story_5007_50071501_3_dialog_content = "중대! 어서 방어군을 지원해라! 서둘러!",
  ui_story_5007_50071501_4_dialog_content = "레비! 길을 열어줘! 전방의 암귀를 쓰러트리고 비전투인원의 피난을 도와야 해!",
  ui_story_5007_50071501_5_dialog_content = "알겠어! 전류 돌격!",
  ui_story_5007_50071501_6_dialog_content = "캬악──!",
  ui_story_5007_50071501_7_dialog_content = "PlayerName, 드디어 왔구나!",
  ui_story_5007_50071501_8_dialog_content = "내가 자리를 비운 지 1시간도 안 됐는데, 어떻게 암귀가 침입한 거지?",
  ui_story_5007_50071501_9_dialog_content = "아까 그 폭발과 관계가 있는 거냐?",
  ui_story_5007_50071501_10_dialog_content = "아마 그 폭발도 자폭 암귀의 짓일 거예요!",
  ui_story_5007_50071501_11_dialog_content = "고위 암귀가 성벽 근처에 있는 게 느껴져... 그람 씨! 레비!",
  ui_story_5007_50071501_12_dialog_content = "보고드립니다!",
  ui_story_5007_50071501_12X1_dialog_content = "약 10분 전 대규모의 자폭 암귀가 성벽을 습격해 폭발로 성벽에 균열을 일으켰습니다!",
  ui_story_5007_50071501_12X2_dialog_content = "추가 병력을 보내 방어하고 있지만, 적은 매우 강력한 대형 암귀입니다!\n방어가 어려운 상황입니다!",
  ui_story_5007_50071501_13_dialog_content = "바튼 씨, 그람 씨, 고위 암귀가 성벽 근처에 있는 게 느껴져요...",
  ui_story_5007_50071501_14_dialog_content = "레비라면 분명히 그 암귀를 찾으러 성벽 쪽으로 갈 거다!",
  ui_story_5007_50071501_15_dialog_content = "바튼! 우리는 그 암귀를 상대한 적이 있다! 놈은 우리가 상대하겠다!",
  ui_story_5007_50071501_16_dialog_content = "좋다. 그럼 부탁하지.",
  ui_story_5007_50071501_17_dialog_content = "포병대가 언제든지 너희를 엄호하겠다! 전술은 너희가 정해라!",
  ui_story_5007_50071501_18_dialog_content = "병사들과 함께 그 암귀를 쓰러트려라!",
  ui_story_5007_50071501_19_dialog_content = "전면 반격의 포문을 여는 거다!",
  ui_story_5007_50071501_20_dialog_content = "PlayerName, 안내를 부탁한다!",
  ui_story_5007_50071501_20X_dialog_content = "왼쪽이에요. 레비, 선두를 맡아줘. 도중에 나타나는 암귀를 쓰러트리는 거야!",
  ui_story_5007_50071501_20X1_dialog_content = "알겠어! 전류 돌격!",
  ui_story_5007_50071501_21_dialog_content = "퇴각해라! 서둘러!",
  ui_story_5007_50071501_22_dialog_content = "성벽은 포기해! 성벽 위에 서지 마!",
  ui_story_5007_50071501_23_dialog_content = "키에에엑──!",
  ui_story_5007_50071501_24_dialog_content = "쏴라! 쏴!",
  ui_story_5007_50071501_25_dialog_content = "대형 암귀를 쏴라!",
  ui_story_5007_50071501_26_dialog_content = "안 돼! 전혀 먹히질 않아!",
  ui_story_5007_50071501_26X_dialog_content = "이런... 더는 버틸 수가 없어!",
  ui_story_5007_50071501_26X1_dialog_content = "지원군은 대체 언제쯤 오는 거지?!",
  ui_story_5007_50071501_27_dialog_content = "크르르르...",
  ui_story_5007_50071501_28_dialog_content = "전류 돌격!",
  ui_story_5007_50071501_29_dialog_content = "고, 고마워!",
  ui_story_5007_50071501_30_dialog_content = "천만에.",
  ui_story_5007_50071501_31_dialog_content = "똑같이 생긴 대형 암귀잖아...",
  ui_story_5007_50071501_32_dialog_content = "난 이미 한 번 쓰러트렸어. 이번에도 분명히 쓰러트릴 수 있을 거야...",
  ui_story_5007_50071501_33_dialog_content = "다리... 떨지 마! 돌격!",
  ui_story_5007_50071501_34_dialog_content = "키에에엑...",
  ui_story_5007_50071501_35_dialog_content = "사, 살려줘... 다...다리가 풀려버렸어...",
  ui_story_5007_50071501_36_dialog_content = "야! 거기 멍하니 있지 마!",
  ui_story_5007_50071501_37_dialog_content = "어서 피해!",
  ui_story_5007_50071501_38_dialog_content = "너, 넌 왜 무서워하지 않는 건데...?",
  ui_story_5007_50071501_39_dialog_content = "내가 무서워할 리가 없잖아!",
  ui_story_5007_50071501_40_dialog_content = "레비! 그렇게 무턱대고 돌진해서 어쩌려는 거냐!",
  ui_story_5007_50071501_41_dialog_content = "PlayerName의 명령이야. 나한테 길을 뚫으라고 했다고. 장애물은 전부 없앴어!",
  ui_story_5007_50071501_42_dialog_content = "놈을 쓰러트리려면 강한 사람들이 많이 필요해! 모두의 힘이 필요하다고!",
  ui_story_5007_50071501_43_dialog_content = "그래서 계속 너흴 기다리고 있었어!",
  ui_story_5007_50071501_44_dialog_content = "...어느새 어엿한 전사가 된 거냐, 레비.",
  ui_story_5007_50071501_45_dialog_content = "크오오오오──!",
  ui_story_5007_50071501_46_dialog_content = "모두 들어라!",
  ui_story_5007_50071501_47_dialog_content = "적의 대장이 나타났다!",
  ui_story_5007_50071501_48_dialog_content = "작전 목표는 대형 고위 암귀를 처치하는 것!",
  ui_story_5007_50071501_49_dialog_content = "그리고 23호 지하성을 지키는 것이다!",
  ui_story_5007_50071501_50_dialog_content = "레비! 넌 나와 함께 놈을 제압한다!",
  ui_story_5007_50071501_51_dialog_content = "모든 힘을 끌어올려라!",
  ui_story_5007_50071501_52_dialog_content = "루미나를 모조리 써버리는 거다!",
  ui_story_5007_50071501_53_dialog_content = "전류! 슈퍼 전류!",
  ui_story_5007_50071501_54_dialog_content = "뭐든지 관통하는 슈퍼 섬광 전류! 참격!",
  ui_story_5007_50071501_55_dialog_content = "캬아아아악──!",
  ui_story_5007_50071501_56_dialog_content = "레비! 철수해라! 다음 공격이 온다!",
  ui_story_5007_50071501_57_dialog_content = "알루라!",
  ui_story_5007_50071501_58_dialog_content = "임시 사격대, 사격 개시!",
  ui_story_5007_50071501_59_dialog_content = "예!",
  ui_story_5007_50071501_60_dialog_content = "<color=#e8d9bb>타타타탕!</color>",
  ui_story_5007_50071501_61_dialog_content = "그으으...",
  ui_story_5007_50071501_62_dialog_content = "임시 대장님! 공격이 통하질 않습니다!",
  ui_story_5007_50071501_63_dialog_content = "사격은 다른 부대에게 보내는 신호일 뿐이야. 녀석의 주의도 끌 겸 말이야.",
  ui_story_5007_50071501_64_dialog_content = "시간을 버는 것만으로도 충분해.",
  ui_story_5007_50071501_65_dialog_content = "녀석에게 사격이 통하지 않는다는 건 알고 있어. 그럼 이번엔 어떨까나?",
  ui_story_5007_50071501_66_dialog_content = "위치 확인! 신호 확인! 전탄 발사!",
  ui_story_5007_50071501_67_dialog_content = "<color=#e8d9bb>쾅── 콰광── 쾅──!</color>",
  ui_story_5007_50071501_68_dialog_content = "녀석이 재생하려 한다면, 모든 에너지를 재생에 쏟아붓게 만드는 거다!",
  ui_story_5007_50071501_69_dialog_content = "포병은 모든 포탄을 발사해라!",
  ui_story_5007_50071501_70_dialog_content = "PlayerName! 우린 안전 범위로 대피했다!",
  ui_story_5007_50071501_71_dialog_content = "커디! 신호탄 발사!",
  ui_story_5007_50071501_72_dialog_content = "발사 완료!",
  ui_story_5007_50071501_73_dialog_content = "다들 엎드려! 충격파가 온다!",
  ui_story_5007_50071501_74_dialog_content = "AA-88 요새포다!",
  ui_story_5007_50071501_75_dialog_content = "<color=#e8d9bb>쾅── 콰광──!</color>",
  ui_story_5007_50071501_76_dialog_content = "윽...",
  ui_story_5007_50071501_77_dialog_content = "고막이 터질 것 같아...",
  ui_story_5007_50071501_78_dialog_content = "강제 감응...!",
  ui_story_5007_50071501_79_dialog_content = "......",
  ui_story_5007_50071501_80_dialog_content = "역시... 이 정도의 포격이라도 여전히 회복해내고 있어.",
  ui_story_5007_50071501_81_dialog_content = "카렌, 바이스! 준비됐어?",
  ui_story_5007_50071501_82_dialog_content = "힘은 충분히 모았어.",
  ui_story_5007_50071501_83_dialog_content = "간다!",
  ui_story_5007_50071501_84_dialog_content = "그람 씨! 총공격의 때가 왔어요! 외쳐주세요!",
  ui_story_5007_50071501_85_dialog_content = "돌격대의 정예 병사들이여! 잘 들어라!",
  ui_story_5007_50071501_86_dialog_content = "너희의 루미나를 남김없이 쏟아부어라!",
  ui_story_5007_50071501_87_dialog_content = "고위 암귀를 완전히 끝장내는 거다!",
  ui_story_5007_50071501_88_dialog_content = "놈이 산산조각 날 때까지!",
  ui_story_5007_50071501_89_dialog_content = "잿더미가 될 때까지 공격해라!",
  ui_story_5007_50071501_90_dialog_content = "전사들이여!",
  ui_story_5007_50071501_91_dialog_content = "<size=40>분노해라! 너희의 모든 기세를 보여주는 거다!</size>",
  ui_story_5007_50071501_92_dialog_content = "<size=40>이건 마지막 싸움이다!</size>",
  ui_story_5007_50071501_93_dialog_content = "<size=45>승리로 향하는 최후의 일전이다!</size>",
  ui_story_5007_50071501_94_dialog_content = "<size=50>우오오오오───!</size>",
  ui_story_5007_50071502_1_dialog_content = "......",
  ui_story_5007_50071502_2_dialog_content = "암귀가... 사라졌어...",
  ui_story_5007_50071502_3_dialog_content = "우리가 이긴 거야?",
  ui_story_5007_50071502_4_dialog_content = "고위 암귀를 쓰러트렸어!",
  ui_story_5007_50071502_5_dialog_content = "그람 씨! 모두에게 전해줘요!",
  ui_story_5007_50071502_6_dialog_content = "고위 암귀는──!",
  ui_story_5007_50071502_6X_dialog_content = "쓰러졌다──!",
  ui_story_5007_50071502_7_dialog_content = "전사들! 들었냐?!",
  ui_story_5007_50071502_8_dialog_content = "돌격대의 승리 신호다!",
  ui_story_5007_50071502_9_dialog_content = "제2군단! 24호 지하성 방어군! 잘 들어라!",
  ui_story_5007_50071502_10_dialog_content = "전면 반격을 개시한다!",
  ui_story_5007_50071502_11_dialog_content = "<size=40>돌격이다──!</size>",
  ui_story_5007_50071502_12_dialog_content = "<size=40>여명의 빛을 위하여!</size>",
  ui_story_5007_50071502_13_dialog_content = "<size=40>24호 지하성 방어전은!</size>",
  ui_story_5007_50071502_14_dialog_content = "<size=50>우리의 승리다──!</size>",
  ui_story_5007_50071502_15_dialog_content = "브랜트...",
  ui_story_5007_50071502_16_dialog_content = "보고 있는 거냐.",
  ui_story_5007_50071502_17_dialog_content = "우리가 이겼다...",
  ui_story_5007_50071502_18_dialog_content = "암귀와의 전쟁에서, 또 한 번 승리했다.",
  ui_story_5007_50071502_19_dialog_content = "이겼어? 끝난 거야?",
  ui_story_5007_50071502_20_dialog_content = "흑... 이게 브랜트 님이 말한 최종 승리야?",
  ui_story_5007_50071502_21_dialog_content = "그래... 일단은 끝났다. 울고 싶으면 실컷 울어라.",
  ui_story_5007_50071502_22_dialog_content = "아저씨는 틀렸어! 브랜트 님은 돌아가셨다고...",
  ui_story_5007_50071502_23_dialog_content = "근데 어떻게 브랜트 님이 볼 수가 있냐고... 흐아앙!",
  ui_story_5007_50071502_24_dialog_content = "이 녀석... 휴, 됐다. 속에 쌓아두는 것보다는 우는 게 낫겠지.",
  ui_story_5007_50071502_25_dialog_content = "그람 씨, 근데 일단은 끝났다는 건...",
  ui_story_5007_50071502_26_dialog_content = "그래. 이번엔 23호 지하성을 지켜냈지만...",
  ui_story_5007_50071502_27_dialog_content = "암귀는 언제든지 다시 올 거다...",
  ui_story_5007_50071502_27X1_dialog_content = "이 전쟁... 대체 얼마나 계속해야 하는 거죠? 얼마나 더 많은 사람들이 죽어야 하죠?",
  ui_story_5007_50071502_27X2_dialog_content = "모른다. 꽤 오랫동안 이어지겠지. 하지만 언젠가는 일루미나가 승리할 거다.",
  ui_story_5007_50071502_27X3_dialog_content = "우리가 모두 죽은 뒤라도 말이지...",
  ui_story_5007_50071502_32_dialog_content = "흑... 그럼 아직 못 이긴 거야?",
  ui_story_5007_50071502_33_dialog_content = "이겼습니다! 무슨 말씀들 하시는 겁니까? 23호 지하성 방어전은 우리가 이겼다구요!",
  ui_story_5007_50071502_34_dialog_content = "책임관님의 명령입니다. 모두 지하성으로 복귀하십시오!",
  ui_story_5007_50071502_35_dialog_content = "<color=#e8d9bb>지직, 지지직──</color>",
  ui_story_5007_50071502_X35_dialog_content = "여기는 레이스, 여기는 레이스, 응답하라.",
  ui_story_5007_50071502_X36_dialog_content = "수신 양호. 22호 지하성 쪽은 어떤가?",
  ui_story_5007_50071502_X37_dialog_content = "복구는 끝났어. 하지만 지하성의 에너지 장치에 작동된 흔적이 있었어.",
  ui_story_5007_50071502_X38_dialog_content = "아마 암귀에게 뺏긴 거겠지.",
  ui_story_5007_50071502_36_dialog_content = "에너지 장치를 빼앗겼다고? 암귀 놈들, 대체 뭘 할 작정이지?",
  ui_story_5007_50071502_X39_dialog_content = "지금 조사 중이야.",
  ui_story_5007_50071502_X40_dialog_content = "원래는 23호 지하성에 지원이 필요한지 물어보려던 건데, 모습을 보니까...",
  ui_story_5007_50071502_X41_dialog_content = "어디 터진 곳도 없고, 얼굴도 멀쩡하잖아?",
  ui_story_5007_50071502_X42_dialog_content = "누가 봐도 필요 없지 않겠냐!",
  ui_story_5007_50071502_X43_dialog_content = "넌 날 대신해서 라인하르트에게 보고해 놔라.\n23호 지하성 방어전은 승리했고, 암귀는 퇴각했다고.",
  ui_story_5007_50071502_X44_dialog_content = "그 녀석, 이미 예상한 모양이야. 당신은 일단 23호 지하성에 남아서 다음 지시를 기다리래.",
  ui_story_5007_50071502_X45_dialog_content = "이상이야.",
  ui_story_5007_50071502_X46_dialog_content = "쳇, 또 예상했다는 거냐. 정말 기분이 더럽군...",
  ui_story_5007_50071502_37_dialog_content = "군단장님! 24호 지하성의 그람 님이 찾아왔습니다.",
  ui_story_5007_50071502_38_dialog_content = "들여보내라.",
  ui_story_5007_50071502_39_dialog_content = "할 말이 있으면 단도직입적으로 해라. 난 다른 일이 있어서 바쁘니까.",
  ui_story_5007_50071502_40_dialog_content = "우리가 24호 지하성에서 싸우고 있을 때,\n암귀는 수송대의 화물을 빼앗으려고 했다.",
  ui_story_5007_50071502_41_dialog_content = "그건 너희가 제출한 보고서에도 적혀 있었다.",
  ui_story_5007_50071502_42_dialog_content = "암귀가 일루미나의 에너지 장치를 노리고 전략적인 움직임을 보이고 있다.\n...이게 가능한 일인가?",
  ui_story_5007_50071502_43_dialog_content = "안 될 게 어디 있어? 난 놈들이 우릴 시험하듯 방어선을 공격한 것 말고도,\n분명히 다른 목표가 있었다고 생각했다.",
  ui_story_5007_50071502_44_dialog_content = "놈들은 대체 뭘 하려는 거지? 놈들에게 우리의 에너지 장치가 무슨 소용이란 말이냐.",
  ui_story_5007_50071502_45_dialog_content = "나야 모르지. 그건 방금 전에 나도 했던 질문이다...",
  ui_story_5007_50071502_46_dialog_content = "대답은 <color=#FFB400>「지금 조사 중」</color>이라더군.",
  ui_story_5007_50071502_47_dialog_content = "우린 암귀의 정보를 입수하는 것만 해도 힘들다고.\n놈들이 무슨 생각인지 알아내는 건 말할 것도 없지.",
  ui_story_5007_50071502_48_dialog_content = "확실히 전에는 그랬었지...",
  ui_story_5007_50071502_49_dialog_content = "처음에 우리는 암귀들이 수만 많고 행동은 단순한 적이라고 생각했다.",
  ui_story_5007_50071502_50_dialog_content = "하지만 놈들은 끝없이 「성장」하고 있었고, 우린 그에 맞서 대응하기에도 벅찼다.",
  ui_story_5007_50071502_51_dialog_content = "그럼 우린 영원히 암귀를 이길 수 없는 건가?",
  ui_story_5007_50071502_52_dialog_content = "암귀와의 전쟁은 이미 오래전부터 지속돼 왔다...",
  ui_story_5007_50071502_53_dialog_content = "그럼에도 우리 일루미나는 패배하지 않았고,\n암귀의 대군과 싸울 수 있을 만큼의 힘을 길러냈다.",
  ui_story_5007_50071502_54_dialog_content = "심지어 지금의 일루미나에는 괴물이라고 부를 만한 녀석까지 있지.",
  ui_story_5007_50071502_54X_dialog_content = "우리가 자신의 임무를 완수한다면, 최종 승리의 날도 머지않아 올 것이다.",
  ui_story_5007_50071502_55_dialog_content = "통신실로 가 봐. <color=#FFB400>라인하르트</color>의 연설이 곧 시작될 테니까.",
  ui_story_5007_50071502_56_dialog_content = "<color=#e8d9bb>지직, 지지직──</color>",
  ui_story_5007_50071502_57_dialog_content = "어때?",
  ui_story_5007_50071502_58_dialog_content = "모래바람이 가라앉은 지 꽤 됐어. 이제 신호를 수신할 수 있을 거야.",
  ui_story_5007_50071502_59_dialog_content = "방금 암호를 수신했어. 통신이 회복되고 있다는 뜻이야.",
  ui_story_5007_50071502_60_dialog_content = "좀 더 조정해 보자고. 조금만 더 기다려.",
  ui_story_5007_50071502_61_dialog_content = "<size=30>흠, 저기... 이게 축하 행사인가요?</size>",
  ui_story_5007_50071502_62_dialog_content = "보면 알 거다.",
  ui_story_5007_50071502_63_dialog_content = "그람 씨, 어디 갔었어요?",
  ui_story_5007_50071502_64_dialog_content = "잠깐 바튼과 이야기를 좀 하고 왔다.",
  ui_story_5007_50071502_65_dialog_content = "내 신경은 쓰지 말고, 저들이 하는 일을 잘 살펴봐라.",
  ui_story_5007_50071502_66_dialog_content = "바이스, 지금 다들 통신 장치를 수리하고 있는 거지?",
  ui_story_5007_50071502_67_dialog_content = "응, 아마도? 더 가까이 와서 볼래?",
  ui_story_5007_50071502_68_dialog_content = "아니, 그냥 이 정도가 좋아. 너무 가까운 것도 좋지 않아.",
  ui_story_5007_50071502_69_dialog_content = "<color=#e8d9bb>지직, 지지직──</color>",
  ui_story_5007_50071502_70_dialog_content = "오! 된 것 같아!",
  ui_story_5007_50071502_71_dialog_content = "다들 조용히 들어! 대원수님께서 보내신 중요한 통신이야!",
  ui_story_5007_50071502_72_dialog_content = "동지들이여.",
  ui_story_5007_50071502_73_dialog_content = "우선 모두에게 전황을 설명하겠다.",
  ui_story_5007_50071502_74_dialog_content = "최근 사막 방어선은 암귀의 맹렬한 공격을 받았다.",
  ui_story_5007_50071502_75_dialog_content = "22호 지하성이 함락되었고...",
  ui_story_5007_50071502_76_dialog_content = "21호, 23호 지하성은 전면 방어 태세로 전환됐다.",
  ui_story_5007_50071502_77_dialog_content = "또한 일부 암귀들은 후방에 침투했고, 24호, 25호 지하성에까지 위협을 가했다.",
  ui_story_5007_50071502_78_dialog_content = "우리의 전사들은 밤낮으로 전력을 다해 싸웠다.",
  ui_story_5007_50071502_79_dialog_content = "아군은 22호 지하성 탈환에 성공했고,\n21호, 23호, 24호, 25호 지하성의 방어전에서 승리했다.",
  ui_story_5007_50071502_80_dialog_content = "이로써 암귀를 격퇴했고, 사막 방어선을 재건하여 암귀의 대규모 침공을 막아냈다.",
  ui_story_5007_50071502_81_dialog_content = "이것은 모든 병사가 함께 싸워서 얻은 승리다!",
  ui_story_5007_50071502_82_dialog_content = "일루미나의 주력 부대는 22호 지하성의 탈환을 노리고 있었던 거였나...",
  ui_story_5007_50071502_83_dialog_content = "후방의 지하성을 자율 방어 태세에 돌입시킨 건...\n방어선이 재건되기 전까진 주력 부대의 지원이 없었을 거란 뜻이겠지.",
  ui_story_5007_50071502_84_dialog_content = "22호 지하성을 탈환했는데 다른 지하성이 또 함락되면?",
  ui_story_5007_50071502_85_dialog_content = "후방에 있는 지하성은 지원군이 올 때까지 못 버티고 함락됐을지도 모르잖아.",
  ui_story_5007_50071502_86_dialog_content = "사막 방어선 전체가 무너지더라도 우리 일루미나는 반격한다...\n그 어떤 대가를 치르더라도 방어선을 재건할 거다.",
  ui_story_5007_50071502_87_dialog_content = "이 자리를 빌려, 나는 동지들에게 내 마음을 전하고자 한다.",
  ui_story_5007_50071502_88_dialog_content = "우리가 암귀의 침입에 반드시 저항할 수 있다는 보장은 없다.",
  ui_story_5007_50071502_89_dialog_content = "우린 고향을 지켜낼 수 있다는 것을 끊임없이 증명해야만 한다.",
  ui_story_5007_50071502_90_dialog_content = "비록 이 대지는 한때 메마르고, 위기로 가득 찬 곳이었지만...",
  ui_story_5007_50071502_91_dialog_content = "600년 전, 일루미나의 병사들은 망설임 없이 이 땅에 발을 디뎠다.",
  ui_story_5007_50071502_92_dialog_content = "그들은 개척하고, 뿌리를 내리고, 맞서 싸웠다!",
  ui_story_5007_50071502_93_dialog_content = "그들은 두 손으로 강철의 방어선을 세우고, 모든 적을 막아냈다!",
  ui_story_5007_50071502_94_dialog_content = "그렇게 대를 이어, 일루미나라는 터전을 지켜온 것이다...",
  ui_story_5007_50071502_95_dialog_content = "앞의 세대가 쓰러지더라도, 새로운 젊은 세대가 일어섰다.",
  ui_story_5007_50071502_96_dialog_content = "모든 일루미나인들이 싸우는 목표...",
  ui_story_5007_50071502_97_dialog_content = "그것은 바로 어떤 암귀도 다시는 우리의 영토를 침범할 수 없게 하는 것이다!",
  ui_story_5007_50071502_98_dialog_content = "그러나 암귀는 여전히 우릴 공격하고 있다...",
  ui_story_5007_50071502_99_dialog_content = "끝없이 이어지는 공격...",
  ui_story_5007_50071502_100_dialog_content = "그들의 유일한 목표는 우리를 말살하는 것이지.",
  ui_story_5007_50071502_101_dialog_content = "그들은 죽음을 두려워하지도 않고, 끝없이 나타난다.",
  ui_story_5007_50071502_102_dialog_content = "그러나 우리의 마음속 일루미나의 깃발이 한순간이라도 쓰러진 적이 있었나?",
  ui_story_5007_50071502_103_dialog_content = "<size=40>결코 없었다!</size>",
  ui_story_5007_50071502_104_dialog_content = "적의 힘이 우리를 절망에 빠트릴지라도.",
  ui_story_5007_50071502_105_dialog_content = "우리 모두의 마음속에는!",
  ui_story_5007_50071502_106_dialog_content = "열정과 용기, 동포와 고향에 대한 사랑이 변함없이 자리 잡고 있었다!",
  ui_story_5007_50071502_107_dialog_content = "우리의 믿음은 영원히 변치 않는다!",
  ui_story_5007_50071502_108_dialog_content = "우리가 계속해서 싸워야만, 강력한 힘을 얻을 수 있다!",
  ui_story_5007_50071502_109_dialog_content = "우리가 계속해서 싸워야만, 희망의 여명이 밝아오는 것을 볼 수 있다!",
  ui_story_5007_50071502_110_dialog_content = "동지들이여, 전사들이여.",
  ui_story_5007_50071502_111_dialog_content = "<size=40>계속해서 함께 싸우며 나아가자!</size>",
  ui_story_5007_50071502_112_dialog_content = "<size=50>여명의 빛을 위하여!</size>",
  ui_story_5007_50071502_113_dialog_content = "<size=50>우리는 끝내 승리할 것이다!</size>",
  ui_story_5007_50071502_114_dialog_content = "<anim type=Shake><size=45>우오오오오오!</size></anim>",
  ui_story_5007_50071502_115_dialog_content = "<size=50>여명의 빛을 위하여!</size>",
  ui_story_5007_50071502_116_dialog_content = "PlayerName, 해가 떴다. 이제 24호 지하성으로 돌아가자.",
  ui_story_5007_50071601_1_dialog_content = "(피곤해서 24호 지하성으로 돌아오자마자 우리는 바로 잠들어 버렸다.)",
  ui_story_5007_50071601_2_dialog_content = "(그리고 난 꿈을 꿨다...)",
  ui_story_5007_50071601_3_dialog_content = "(꿈에서 레비가 나왔다...)",
  ui_story_5007_50071601_4_dialog_content = "잘 들어! 사령관으로서 이야기하는 거니까!",
  ui_story_5007_50071601_5_dialog_content = "암귀가 지하성 근처에 나타났어. 우리한테 접근하진 않았지만 말야.",
  ui_story_5007_50071601_6_dialog_content = "그래도 우린 먼저 출격해서 공격할 거야! 공격! 공격!",
  ui_story_5007_50071601_7_dialog_content = "이 전투의 목표는 아주 간단해. 암귀를 없애면 돼!",
  ui_story_5007_50071601_8_dialog_content = "자세한 작전 명령은 문이 열리고 나서 상황에 따라 하달할게!",
  ui_story_5007_50071601_9_dialog_content = "여명의 빛을 위하여!",
  ui_story_5007_50071601_10_dialog_content = "24호 지하성 소대! 출발!",
  ui_story_5007_50071601_11_dialog_content = "예!",
  ui_story_5007_50071601_12_dialog_content = "(...그리고 꿈에 그람 씨도 나왔다...)",
  ui_story_5007_50071601_13_dialog_content = "PlayerName! 일어나라! 밥 먹을 시간이다!",
  ui_story_5007_50071601_14_dialog_content = "냄새가 진짜 좋네요...",
  ui_story_5007_50071601_15_dialog_content = "무슨 소리야? 얼른 일어나! 해가 중천에 떴다고!",
  ui_story_5007_50071601_16_dialog_content = "어떻게 지금까지 자고 있을 수가 있어?",
  ui_story_5007_50071601_17_dialog_content = "으음... 바이스, 무슨 일 있어?",
  ui_story_5007_50071601_18_dialog_content = "그람 씨가 나랑 얘기하다가 일루미나의 신병 훈련 시스템이 그리워졌나 봐.",
  ui_story_5007_50071601_19_dialog_content = "그래서 특별히 체험 자격을 신청했는데, 하는 김에 너도 꼭 데려오라고 하셨어.",
  ui_story_5007_50071601_20_dialog_content = "또... 날 훈련시키겠다는 거야?\n왜 일루미나 사람들은 하나같이 다 날 훈련시키고 싶어 하는 거지...",
  ui_story_5007_50071601_21_dialog_content = "그래도... 브랜트 씨가 거기 있었으면 분명히 날 불렀을 거야.",
  ui_story_5007_50071601_22_dialog_content = "그럼 씻고 바로 출발하자!",
  ui_story_5007_50071601_23_dialog_content = "전장 지휘도 그렇고 아직 배울 게 많으니까.",
  ui_story_5007_50071601_24_dialog_content = "응! 좋아. 그럼 난 먹을 걸 준비해 줄게.",
  ui_story_5007_50071601_25_dialog_content = "응. 고마워.",
  ui_story_5007_50071601_26_dialog_content = "(꿈에 그람 씨 수프가 나왔다는 말은 하지 말아야겠어...)",
  ui_story_5007_50071601_27_dialog_content = "그람, 앞으로 어떻게 할 계획인가?",
  ui_story_5007_50071601_28_dialog_content = "교관이 돼야겠어. 브랜트처럼 말이야.",
  ui_story_5007_50071601_29_dialog_content = "그거 좋은 생각이군. 자네가 그래준다면 녀석도 안심할 거야.",
  ui_story_5007_50071601_30_dialog_content = "그렇겠지.",
  ui_story_5007_50071601_31_dialog_content = "참, 가서 모두를 불러와라.",
  ui_story_5007_50071601_32_dialog_content = "자네를 따라 전선에서 싸웠던 병사들을 전부 불러 지하성 밖에 모여 봐.",
  ui_story_5007_50071601_33_dialog_content = "모여서 뭘 하려는 거지?",
  ui_story_5007_50071601_34_dialog_content = "이제 바깥은 안전하다. 날씨도 좋고 말이야.",
  ui_story_5007_50071601_35_dialog_content = "누가 우리한테 좋은 선물을 하나 보냈거든.",
  ui_story_5007_50071601_36_dialog_content = "깜짝 선물이지. 모이고 나면 알게 될 거다.",
  ui_story_5007_50071601_37_dialog_content = "그러니까 얼른 가 봐!",
  ui_story_5007_50071601_38_dialog_content = "알겠다고. 뭐가 그리 급해...",
  ui_story_5007_50071601_39_dialog_content = "아얏! 왜 여기 벽이... 아니네, 그람 님이구나.",
  ui_story_5007_50071601_40_dialog_content = "안시아, 뭘 하는 건가?",
  ui_story_5007_50071601_41_dialog_content = "지금 최신 통신 기기를 개발하는 중이에요!",
  ui_story_5007_50071601_42_dialog_content = "<anim type=Shake><size=45>어때요? 이 스피커, 멋지죠? 볼륨도 엄청 크다구요──!</size></anim>",
  ui_story_5007_50071601_43_dialog_content = "윽...",
  ui_story_5007_50071601_44_dialog_content = "복도에서 그런 걸 틀지 마라!",
  ui_story_5007_50071601_45_dialog_content = "아, 죄송해요. 실수로 스위치를 눌렀네요.",
  ui_story_5007_50071601_46_dialog_content = "휴... 됐다. 30분 뒤에 지하성 밖의 수송 거점 입구로 모여라.",
  ui_story_5007_50071601_47_dialog_content = "난 다른 사람들을 부르러 갈 테니 먼저 가라.",
  ui_story_5007_50071601_48_dialog_content = "누굴 불러야 되나요? 제가 도와드릴게요! 여기 이...",
  ui_story_5007_50071601_49X_dialog_content = "멈춰! 스피커는 필요 없어!",
  ui_story_5007_50071601_49X1_dialog_content = "헤헷, 농담이었어요. 그냥 장난친 거예요.",
  ui_story_5007_50071601_49X2_dialog_content = "넌... 좀 더 진중해질 필요가 있어.",
  ui_story_5007_50071601_49X3_dialog_content = "다들 절 미덥지 못하다고 싫어하는 건 알아요. 하지만 저도 조금은 성장했다구요!",
  ui_story_5007_50071601_49X4_dialog_content = "조금만 기다려 주세요! 전 반드시 믿음직하고 실력 있는 통신병이 될 테니까요!",
  ui_story_5007_50071601_50_dialog_content = "그래, 알겠다고. 아무튼 집결하는 거 잊지 마라!",
  ui_story_5007_50071601_51_dialog_content = "보초병, 레비하고 비다 못 봤나?",
  ui_story_5007_50071601_52_dialog_content = "그, 그람 님! 우와... 그람 님이 나한테 말을 걸어주셨어!",
  ui_story_5007_50071601_53_dialog_content = "안녕하세요! 그람 님, 전 패트라고 합니다. 정말 존경합니다!",
  ui_story_5007_50071601_54_dialog_content = "왜 날 존경하지?",
  ui_story_5007_50071601_55_dialog_content = "저희가 훈련할 때 브랜트 교관님이 자주 그람 님 말씀을 해주셨거든요.",
  ui_story_5007_50071601_56_dialog_content = "제 소원은 언젠가 그람 님처럼 전장에서 일당백의 전사가 되는 겁니다!",
  ui_story_5007_50071601_57_dialog_content = "비록 지금은 보초병일 뿐이지만, 언젠가는 이 목표를 이룰 수 있도록 노력하겠습니다!",
  ui_story_5007_50071601_58_dialog_content = "그렇군... 좋은 자세다! 네가 미래에 반드시 그 목표를 이룰 수 있을 거라 믿는다. 계속 노력해라!",
  ui_story_5007_50071601_59_dialog_content = "가, 감사합니다!",
  ui_story_5007_50071601_60_dialog_content = "혹시 그 유능한 신병 두 사람을 찾고 계신 겁니까? 제가 데려다 드리겠습니다!",
  ui_story_5007_50071601_61_dialog_content = "두 사람은 임무를 완수한 후 신병 훈련소로 갔습니다.",
  ui_story_5007_50071601_62_dialog_content = "신병 훈련소? 마침 잘됐군.",
  ui_story_5007_50071601_63_dialog_content = "봐! 내 전공! 훈장! 반짝반짝!",
  ui_story_5007_50071601_64_dialog_content = "음... 그걸 왜 나한테 자랑하러 온 거야?",
  ui_story_5007_50071601_65_dialog_content = "넌 내 지휘관이잖아. 너한테 내가 이룬 성과를 보여주는 게 이상해?",
  ui_story_5007_50071601_66_dialog_content = "난 임시로 전투를 몇 번 지휘했을 뿐이지, 지휘관도 아니고, 군인도 아냐.",
  ui_story_5007_50071601_67_dialog_content = "아, 맞다. 넌 임시구나.",
  ui_story_5007_50071601_68_dialog_content = "그럼 난 널 뭐라고 불러? 다들 보통 뭐라고 부르는데?",
  ui_story_5007_50071601_69_dialog_content = "PlayerName, 이름을 부르거나, 보통은 조종사라고 불러.",
  ui_story_5007_50071601_70_dialog_content = "PlayerName 조종사, 나 포상도 탔어!",
  ui_story_5007_50071601_71_dialog_content = "저기... 사실 저도 포, 포상을 탔어요.",
  ui_story_5007_50071601_72_dialog_content = "호, 혹시 저 기억하시나요...?",
  ui_story_5007_50071601_73_dialog_content = "......",
  ui_story_5007_50071601_74_dialog_content = "죄, 죄송해요... 저도 알아요. 제가 존재감이 없는 거... 전 마지막 결전에는 참가하지 못했으니까요.",
  ui_story_5007_50071601_75_dialog_content = "사실 지뢰를 폭파시킨 건 저예요! 가는 길에 계속 지뢰를 폭발시켰어요!",
  ui_story_5007_50071601_76_dialog_content = "읏챠, 이렇게 생긴 지뢰인데요...",
  ui_story_5007_50071601_77_dialog_content = "기, 기억해! 기억한다고! 우리 모두 네가 비다라는 거 알아!\n그러니까 그건 꺼낼 필요 없어!",
  ui_story_5007_50071601_78_dialog_content = "그것보다 너흰 무슨 포상을 받았는데?",
  ui_story_5007_50071601_79_dialog_content = "아... 훈장이랑, 보급품 교환 포인트... 그리고 연수 기회도 있어요.",
  ui_story_5007_50071601_80_dialog_content = "연수가 뭔데?",
  ui_story_5007_50071601_81_dialog_content = "연수? 우리 아버지가 가셨던 곳에 가는 거잖아.",
  ui_story_5007_50071601_82_dialog_content = "일루미나의 우수한 일원들은 가끔 백야성에 가서 연수할 수 있는 기회가 주어져.\n바이스도 그랬고 말이야.",
  ui_story_5007_50071601_83_dialog_content = "뭐, 예술 과목이랑 문법 과목은 엉망이었지만.",
  ui_story_5007_50071601_84_dialog_content = "흥! 카렌 너도 일루미나에 기계 도면을 배우러 오면 분명히 엉망일걸?",
  ui_story_5007_50071601_85_dialog_content = "예술이 뭐죠?",
  ui_story_5007_50071601_86_dialog_content = "음... 그게... 아름다움을 구현하는 활동이라는 것 같아!",
  ui_story_5007_50071601_87_dialog_content = "아름다움? 그럼 난 폭발이 무척 예술적이라고 생각해!",
  ui_story_5007_50071601_88_dialog_content = "역시 다 똑같은 일루미나 사람들이네...",
  ui_story_5007_50071601_89_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5007_50071601_90_dialog_content = "어디서 예술을 하고 있지? 우리까지 폭발할 뻔했잖아.",
  ui_story_5007_50071601_91_dialog_content = "이건 유탄이야! 너희 훈련소 너무 위험한 거 아냐?",
  ui_story_5007_50071601_92_dialog_content = "건너편 훈련장 같은데... 다 아는 사이니까 너무 뭐라 하진 말자.",
  ui_story_5007_50071601_93_dialog_content = "아... 이게 바로 예술이었군요...",
  ui_story_5007_50071601_94_dialog_content = "잘 들어, 커디! 넌 이제 평.생. 다.시.는 박격포에 손도 대지 마!",
  ui_story_5007_50071601_95_dialog_content = "하, 학교에서 이런 건 배울 기회가 없었단 말이야. 잘 모를 수도 있지.",
  ui_story_5007_50071601_96_dialog_content = "게다가 지금은 가르쳐 주는 사람이 있잖아? 안 그랬으면 나도 안 썼을 거라구.",
  ui_story_5007_50071601_97_dialog_content = "나는 못 믿어도, 교관님은 믿을 거잖아? 다 같은 「총잡이」들이니까.",
  ui_story_5007_50071601_98_dialog_content = "크흠, 그나마 교육용 유탄이라... 위력이 세지 않아서 다행이군.",
  ui_story_5007_50071601_99_dialog_content = "...내가 했던 말 따라하지 마.",
  ui_story_5007_50071601_100_dialog_content = "신뢰란 건 스스로 얻어내는 거야. 그럴 땐 「날 믿어줘」라고 말해야지.",
  ui_story_5007_50071601_101_dialog_content = "적어도 다음에 네가 또 날 의심한다면, 난 그렇게 말할 거야.",
  ui_story_5007_50071601_102_dialog_content = "...네가 그런 말도 할 줄은 몰랐네. 내가 전에 널 의심한 게 마음에 걸린 거야?",
  ui_story_5007_50071601_103_dialog_content = "근데 솔직히 난 널 감시하는 임무도 중간쯤엔 까먹어 버렸는걸.",
  ui_story_5007_50071601_104_dialog_content = "지금 다시 생각하면, 넌 꽤 믿을 수 있는 사람인 것 같아.",
  ui_story_5007_50071601_105_dialog_content = "그러니까 앞으로 나쁜 짓을 할 생각이라면 나랑 마주치지 않는 게 좋을 거야.\n움브라톤의 어느 용병단의 용병 아가씨!",
  ui_story_5007_50071601_106_dialog_content = "PlayerName! 일행들을 데리고 수송 거점의 입구로 모여라!",
  ui_story_5007_50071601_107_dialog_content = "우와... 여기서도 목소리가 들리다니...\n역시 그람 씨라니까!",
  ui_story_5007_50071601_108_dialog_content = "크흠...그럼 나도 해볼까?",
  ui_story_5007_50071601_109_dialog_content = "알! 겠! 어! 요... 콜록콜록...",
  ui_story_5007_50071601_110_dialog_content = "벌써 숨이 차는 거야? 아무래도 아직 배울 게 많을 것 같네.",
  ui_story_5007_50071601_111_dialog_content = "드디어 왔군. 이 인파를 봐라, 시끌벅적하고... 좋군.",
  ui_story_5007_50071601_112_dialog_content = "어이! 여기다! 여기!",
  ui_story_5007_50071601_113_dialog_content = "가고 있어!",
  ui_story_5007_50071601_114_dialog_content = "책임관님, 무슨 일인가요?",
  ui_story_5007_50071601_115_dialog_content = "아이테르와 일행은 곧 24호 지하성을 떠나 자난성으로 돌아갈 거다.",
  ui_story_5007_50071601_116_dialog_content = "모두 각자의 길을 가게 되겠지. 하지만 우린 전장의 전우들이다.\n함께 사진을 찍어서 추억을 남기는 것도 좋을 것 같아서 말이야.",
  ui_story_5007_50071601_117_dialog_content = "전원! 대열을 갖춰라!",
  ui_story_5007_50071601_118_dialog_content = "대열?",
  ui_story_5007_50071601_119_dialog_content = "아, 됐다. 그냥 다 같이 서 봐!",
  ui_story_5007_50071601_120_dialog_content = "음? 난 어디 서지...",
  ui_story_5007_50071601_121_dialog_content = "PlayerName, 넌 내 옆에 서라.",
  ui_story_5007_50071601_122_dialog_content = "아니야. 내 옆에 서야지.",
  ui_story_5007_50071601_123_dialog_content = "이런 것까지 가지고 싸우자는 거냐? 역시 아직은 어린애인가.",
  ui_story_5007_50071601_124_dialog_content = "난 어린애가 아냐! 아저씨가 너무 늙은 거야! 내 머리에 손대지 마!",
  ui_story_5007_50071601_125_dialog_content = "나이는 어린데 성격은 참 거칠단 말이지.",
  ui_story_5007_50071601_126_dialog_content = "카렌, 병사들이 하얀 창병에 대해 이야기하는 걸 들었는데...",
  ui_story_5007_50071601_127_dialog_content = "그거 너야?",
  ui_story_5007_50071601_128_dialog_content = "당연하지. 나 말고 누가 있겠어.",
  ui_story_5007_50071601_129_dialog_content = "그 별명에 꽤 만족한 모양인데?",
  ui_story_5007_50071601_129X_dialog_content = "아니, 난 그냥 이름이 간결하고 명확하다고 생각했을 뿐이야.",
  ui_story_5007_50071601_130_dialog_content = "다들 긴장 풀고, 기분 좀 내라. 자, 따라서 외쳐라!",
  ui_story_5007_50071601_131_dialog_content = "여명의 빛을 위하여!",
  ui_story_5007_50071601_132_dialog_content = "여명의 빛을 위하여──!",
  ui_story_5007_50071601_133_dialog_content = "선배, 같이 한 장 더 찍자고. 나도 기념품으로 한 장 가지고 싶거든.",
  ui_story_5007_50071601_134_dialog_content = "별일이군. 난 자네가 기념품 같은 건 좋아하지 않는 거로 기억하는데 말이지.",
  ui_story_5007_50071601_135_dialog_content = "맞아. 이건 브랜트를 위해서야.",
  ui_story_5007_50071601_136_dialog_content = "그거 알고 있나?",
  ui_story_5007_50071601_137_dialog_content = "암귀와의 끝없는 싸움 앞에서...",
  ui_story_5007_50071601_138_dialog_content = "전사이자 군인으로서 우리가 무엇에 기대 버텨야 하는지 말이야.",
  ui_story_5007_50071601_139_dialog_content = "빙빙 돌리지 말고 말해 봐.",
  ui_story_5007_50071601_140_dialog_content = "그저 한 마디면 된다. 「여명의 빛을 위하여」.",
  ui_story_5007_50071601_141_dialog_content = "여명의 빛은 미래다. 암귀가 없는 미래 말이다.",
  ui_story_5007_50071601_142_dialog_content = "아이들은 더는 암귀 때문에 부모를 잃지 않을 거다.",
  ui_story_5007_50071601_143_dialog_content = "청년들은 더는 암귀 때문에 연인을 잃지 않겠지.",
  ui_story_5007_50071601_144_dialog_content = "노인들은 더는 암귀 때문에 아이를 잃지 않는 그런 미래.",
  ui_story_5007_50071601_145_dialog_content = "난 내가 데려온 신병들, 저 새로운 세대야말로 미래이자, 승리의 희망이라고 생각한다.",
  ui_story_5007_50071601_146_dialog_content = "저들이야말로 여명의 빛인 거다!",
  ui_story_5007_50071601_147_dialog_content = "어이, 젊은이들! 다들 정신 바짝 차리고 날 따라 외쳐라!",
  ui_story_5007_50071601_148_dialog_content = "여명의 빛을 위하여!",
  ui_story_5007_50071601_149_dialog_content = "<size=45>브랜트를 위하여!</size>"
}
return config
